export default " \\\"lfx-alpha\\\", \\\"version\\\": \\\"9.9.9\\\"}), encoding=\\\"utf-8\\\")\\n    results = discover_inline_bundles([parent])\\n    assert results[0].extension_id == \\\"lfx-alpha\\\"\\n    assert results[0].extension_version == \\\"9.9.9\\\"\\n\\n\\ndef test_inline_module_import_failure_attributes_identity(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"AC #10: load results carry extension_id/bundle on partial failure (@extra).\\n\\n    Mirror of test_module_import_failure (which covers @official) for the\\n    inline-bundle path: a broken.py that raises at import time produces\\n    a typed ``module-import-failed`` error AND the LoadResult still\\n    carries the bundle identity so the events pipeline can attribute the\\n    failure to a specific source.\\n    \\\"\\\"\\\"\\n    parent = tmp_path / \\\"p\\\"\\n    parent.mkdir()\\n    make_inline_bundle(\\n        parent,\\n        \\\"alpha\\\",\\n        files={\\n            # One healthy file plus one that blows up at import-time.\\n            \\\"thing.py\\\": \\\"class Component:\\\\n    pass\\\\nclass Thing(Component):\\\\n    pass\\\\n\\\",\\n            \\\"broken.py\\\": \\\"raise RuntimeError('boom at import')\\\\n\\\",\\n        },\\n    )\\n    results = discover_inline_bundles([parent])\\n    assert len(results) == 1\\n    result = results[0]\\n    # Identity is attributed even though one file failed to import.\\n    assert result.bundle == \\\"alpha\\\"\\n    assert result.extension_id == \\\"alpha\\\"  # default-derived from dir name\\n    assert result.extension_version  # at least the default \\\"0.0.0\\\"\\n    # Typed error surfaced.\\n    codes = [e.code for e in result.errors]\\n    assert \\\"module-import-failed\\\" in codes\\n    failure = next(e for e in result.errors if e.code == \\\"module-import-failed\\\")\\n    assert \\\"boom at import\\\" in failure.message\\n    assert failure.hint  # AC: fix-hint payload\\n    # Healthy sibling still loaded.\\n    assert any(c.class_name == \\\"Thing\\\" for c in result.components)\\n\\n\\ndef test_handles_none_paths() -> None:\\n    assert discover_inline_bundles(None) == []\\n\\n\\ndef test_non_existent_path_emits_inline_path_missing(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A non-existent or non-dir path produces a typed warning, not silent skip.\\n\\n    A typo in LANGFLOW_COMPONENTS_PATH would otherwise yield zero\\n    components and zero diagnostics -- the AC item the second reviewer\\n    flagged as a tough debug experience.\\n    \\\"\\\"\\\"\\n    bogus = tmp_path / \\\"does-not-exist\\\"\\n    results = discover_inline_bundles([bogus])\\n    assert len(results) == 1\\n    result = results[0]\\n    # Path-level diagnostic: no bundle was identified.\\n    assert result.bundle is None\\n    assert any(w.code == \\\"inline-path-missing\\\" for w in result.warnings)\\n    warning = next(w for w in result.warnings if w.code == \\\"inline-path-missing\\\")\\n    assert str(bogus) in warning.location\\n    assert warning.hint  # AC: fix-hint payload\\n\\n\\ndef test_unreadable_path_emits_inline_path_unreadable(tmp_path: Path, monkeypatch) -> None:\\n    \\\"\\\"\\\"An OSError during iterdir surfaces ``inline-path-unreadable``, not a silent skip.\\n\\n    Permission-denied on a configured LANGFLOW_COMPONENTS_PATH entry is a\\n    real misconfiguration -- the user explicitly pointed us here. The\\n    OSError message must be carried through so an operator can diagnose.\\n    \\\"\\\"\\\"\\n    from pathlib import Path as _Path  # imported here to keep TYPE_CHECKING block clean\\n\\n    parent = tmp_path / \\\"p\\\"\\n    parent.mkdir()\\n\\n    # Patch ``Path.iterdir`` to raise PermissionError just for this dir.\\n    real_iterdir = _Path.iterdir\\n\\n    def _fake_iterdir(self):\\n        if self == parent.resolve():\\n            msg = \\\"Permission denied\\\"\\n            raise PermissionError(msg)\\n        return real_iterdir(self)\\n\\n    monkeypatch.setattr(_Path, \\\"iterdir\\\", _fake_iterdir)\\n\\n    results = discover_inline_bundles([parent])\\n    assert len(results) == 1\\n    result = results[0]\\n    assert not result.ok\\n    codes = [e.code for e in result.errors]\\n    assert \\\"inline-path-unreadable\\\" in codes\\n    err = next(e for e in result.errors if e.code == \\\"inline-path-unreadable\\\")\\n    assert \\\"Permission denied\\\" in err.message\\n    assert str(parent.resolve()) in err.location\\n    assert err.hint  # AC: fix-hint payload\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/loader/test_load_extension.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4232313b14c4aa45dc883831b0c965ce0b946b6ab2f0bb9e593bbe46a51084c3\",\"content\":\"\\\"\\\"\\\"Tests for ``load_extension`` -- happy path and failure modes.\\n\\nCovers the AC items for the @official slot:\\n    - single-Bundle happy path + identity tuple population\\n    - alternate / non-``./components/`` bundle path\\n    - distribution name flows through to the LoadedComponent\\n    - failure modes: missing manifest, missing bundle dir, empty bundle,\\n      no Component subclass, module import failure, duplicate component\\n      class names within a bundle\\n    - single-bundle API selection for multi-bundle manifests\\n    - dunder/conftest skip; recursive subdirectory walk;\\n      deterministic component order; re-imported class de-duplication\\n    - ``load_extension`` rejects unknown slot values up front\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom typing import TYPE_CHECKING\\n\\nimport pytest\\nfrom lfx.extension import (\\n    SLOT_OFFICIAL,\\n    LoadedComponent,\\n    load_extension,\\n    load_extension_bundles,\\n)\\n\\nfrom .conftest import _BASE_MANIFEST, component_source, make_extension\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n\\n# ---------------------------------------------------------------------------\\n# Happy path + identity tuple\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_single_bundle_registers_component(tmp_path: Path) -> None:\\n    root = make_extension(tmp_path)\\n    result = load_extension(root)\\n    assert result.ok, result.errors\\n    assert result.extension_id == \\\"lfx-pilot\\\"\\n    assert result.extension_version == \\\"1.2.3\\\"\\n    assert result.bundle == \\\"pilot\\\"\\n    assert result.slot == SLOT_OFFICIAL\\n    assert len(result.components) == 1\\n    component = result.components[0]\\n    assert isinstance(component, LoadedComponent)\\n    assert component.class_name == \\\"PilotThing\\\"\\n    assert component.namespaced_id == \\\"ext:pilot:PilotThing@official\\\"\\n    assert component.extension_version == \\\"1.2.3\\\"\\n    assert component.distribution is None\\n\\n\\ndef test_components_path_shorthand(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Manifest with bundle path = ``./components/`` (the recommended layout).\\\"\\\"\\\"\\n    manifest = {**_BASE_MANIFEST, \\\"bundles\\\": [{\\\"name\\\": \\\"pilot\\\", \\\"path\\\": \\\"components\\\"}]}\\n    root = make_extension(tmp_path, manifest=manifest)\\n    result = load_extension(root)\\n    assert result.ok, result.errors\\n    assert result.components[0].file_path.parent.name == \\\"components\\\"\\n\\n\\ndef test_alternate_bundle_path(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Manifest pointing at a non-``components/`` directory still works.\\\"\\\"\\\"\\n    manifest = {**_BASE_MANIFEST, \\\"bundles\\\": [{\\\"name\\\": \\\"pilot\\\", \\\"path\\\": \\\"src/pilot\\\"}]}\\n    root = make_extension(tmp_path, manifest=manifest)\\n    result = load_extension(root)\\n    assert result.ok, result.errors\\n    assert result.components[0].file_path.parent.name == \\\"pilot\\\"\\n\\n\\ndef test_distribution_passed_through(tmp_path: Path) -> None:\\n    root = make_extension(tmp_path)\\n    result = load_extension(root, distribution=\\\"lfx-pilot\\\")\\n    assert result.ok\\n    assert result.components[0].distribution == \\\"lfx-pilot\\\"\\n    assert result.distribution == \\\"lfx-pilot\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Failure paths\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_missing_manifest(tmp_path: Path) -> None:\\n    result = load_extension(tmp_path)\\n    assert not result.ok\\n    codes = [e.code for e in result.errors]\\n    assert codes == [\\\"manifest-not-found\\\"]\\n    # AC: fix-hint payload is present on failure.\\n    assert result.errors[0].hint\\n    assert result.errors[0].ref_url\\n\\n\\ndef test_multi_bundle_requires_selection_for_single_result_api(tmp_path: Path) -> None:\\n    multi = {**_BASE_MANIFEST, \\\"bundles\\\": [{\\\"name\\\": \\\"alpha\\\", \\\"path\\\": \\\"alpha\\\"}, {\\\"name\\\": \\\"bravo\\\", \\\"path\\\": \\\"bravo\\\"}]}\\n    (tmp_path / \\\"extension.json\\\").write_text(json.dumps(multi), encoding=\\\"utf-8\\\")\\n    (tmp_path / \\\"alpha\\\").mkdir()\\n    (tmp_path / \\\"bravo\\\").mkdir()\\n    result = load_extension(tmp_path)\\n    assert not result.ok\\n    assert result.errors[0].code == \\\"multi-bundle-unsupported\\\"\\n\\n\\ndef test_unknown_bundle_selection_reports_the_requested_name(tmp_path: Path) -> None:\\n    multi = {**_BASE_MANIFEST, \\\"bundles\\\": [{\\\"name\\\": \\\"alpha\\\", \\\"path\\\": \\\"alpha\\\"}, {\\\"name\\\": \\\"bravo\\\", \\\"path\\\": \\\"bravo\\\"}]}\\n    (tmp_path / \\\"extension.json\\\").write_text(json.dumps(multi), encoding=\\\"utf-8\\\")\\n\\n    result = load_extension(tmp_path, bundle_name=\\\"charlie\\\")\\n\\n    assert not result.ok\\n    assert result.errors[0].code == \\\"reload-bundle-name-mismatch\\\"\\n    assert result.errors[0].content == \\\"charlie\\\"\\n\\n\\ndef test_load_extension_bundles_loads_every_manifest_entry(tmp_path: Path) -> None:\\n    manifest = {\\n        **_BASE_MANIFEST,\\n        \\\"bundles\\\": [\\n            {\\\"name\\\": \\\"alpha\\\", \\\"path\\\": \\\"alpha\\\"},\\n            {\\\"name\\\": \\\"bravo\\\", \\\"path\\\": \\\"bravo\\\"},\\n        ],\\n    }\\n    (tmp_path / \\\"extension.json\\\").write_text(json.dumps(manifest), encoding=\\\"utf-8\\\")\\n    for name in (\\\"alpha\\\", \\\"bravo\\\"):\\n        bundle = tmp_path / name\\n        bundle.mkdir()\\n        (bundle / f\\\"{name}.py\\\").write_text(component_source(f\\\"{name.title()}Thing\\\"), encoding=\\\"utf-8\\\")\\n\\n    results = load_extension_bundles(tmp_path, distribution=\\\"lfx-pilot\\\")\\n\\n    assert [result.bundle for result in results] == [\\\"alpha\\\", \\\"bravo\\\"]\\n    assert all(result.ok for result in results)\\n    assert [result.components[0].bundle for result in results] == [\\\"alpha\\\", \\\"bravo\\\"]\\n\\n\\ndef test_version_constraint_unsatisfied(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:\\n    \\\"\\\"\\\"A manifest declaring lfx.compat without our BUNDLE_API_VERSION is rejected.\\n\\n    The ``compat`` field validator only enforces format (positive-integer\\n    strings, unique).  The runtime version check happens here at load time\\n    so a bundle declaring only ``[\\\"2\\\"]`` against a lfx that ships\\n    ``BUNDLE_API_VERSION=1`` cannot silently load and crash later when it\\n    touches a contract surface that does not exist yet.\\n    \\\"\\\"\\\"\\n    from lfx.extension.loader import _orchestrator\\n    from lfx.extension.manifest import (\\n        BundleRef,\\n        ExtensionManifest,\\n        LfxCompat,\\n        ManifestSource,\\n    )\\n\\n    (tmp_path / \\\"pilot\\\").mkdir()\\n    (tmp_path / \\\"extension.json\\\").write_text(\\\"{}\\\", encoding=\\\"utf-8\\\")  # placeholder\\n\\n    forged = ExtensionManifest.model_construct(\\n        id=\\\"lfx-pilot\\\",\\n        version=\\\"1.2.3\\\",\\n        name=\\\"Pilot\\\",\\n        lfx=LfxCompat(compat=[\\\"999\\\"]),  # well-formed but does not include BUNDLE_API_VERSION\\n        bundles=[BundleRef(name=\\\"pilot\\\", path=\\\"pilot\\\")],\\n    )\\n    source = ManifestSource.model_construct(manifest=forged, path=tmp_path / \\\"extension.json\\\", kind=\\\"extension.json\\\")\\n    monkeypatch.setattr(_orchestrator, \\\"load_manifest\\\", lambda _root: source)\\n\\n    result = load_extension(tmp_path)\\n    codes = [e.code for e in result.errors]\\n    assert codes == [\\\"version-constraint-unsatisfied\\\"]\\n    err = result.errors[0]\\n    # The fix-hint must name BUNDLE_API_VERSION so the author knows what to change.\\n    assert \\\"BUNDLE_API_VERSION\\\" in err.message\\n    assert err.hint\\n\\n\\ndef test_missing_bundle_directory(tmp_path: Path) -> None:\\n    manifest = {**_BASE_MANIFEST, \\\"bundles\\\": [{\\\"name\\\": \\\"pilot\\\", \\\"path\\\": \\\"missing\\\"}]}\\n    (tmp_path / \\\"extension.json\\\").write_text(json.dumps(manifest), encoding=\\\"utf-8\\\")\\n    result = load_extension(tmp_path)\\n    codes = [e.code for e in result.errors]\\n    assert codes == [\\\"bundle-path-not-found\\\"]\\n\\n\\ndef test_empty_bundle(tmp_path: Path) -> None:\\n    root = make_extension(tmp_path, files={})  # no .py files\\n    result = load_extension(root)\\n    codes = [e.code for e in result.errors]\\n    assert codes == [\\\"bundle-empty\\\"]\\n\\n\\ndef test_no_component_subclass(tmp_path: Path) -> None:\\n    root = make_extension(tmp_path, files={\\\"plain.py\\\": \\\"x = 1\\\\n\\\"})\\n    result = load_extension(root)\\n    codes = [e.code for e in result.errors]\\n    assert codes == [\\\"no-component-subclass\\\"]\\n\\n\\ndef test_module_import_failure(tmp_path: Path) -> None:\\n    root = make_extension(tmp_path, files={\\\"broken.py\\\": \\\"raise RuntimeError('boom at import')\\\\n\\\"})\\n    result = load_extension(root)\\n    codes = [e.code for e in result.errors]\\n    assert \\\"module-import-failed\\\" in codes\\n    failure = next(e for e in result.errors if e.code == \\\"module-import-failed\\\")\\n    assert \\\"boom at import\\\" in failure.message\\n    # Identity is still attributed even on partial failure (AC: fix-hint payload).\\n    assert result.extension_id == \\\"lfx-pilot\\\"\\n\\n\\ndef test_duplicate_component_name(tmp_path: Path) -> None:\\n    files = {\\n        \\\"first.py\\\": component_source(\\\"PilotThing\\\"),\\n        \\\"second.py\\\": component_source(\\\"PilotThing\\\"),\\n    }\\n    root = make_extension(tmp_path, files=files)\\n    result = load_extension(root)\\n    codes = [e.code for e in result.errors]\\n    assert \\\"duplicate-component-name\\\" in codes\\n    # First-seen component still registers; only the duplicate is rejected.\\n    classes = [c.class_name for c in result.components]\\n    assert classes.count(\\\"PilotThing\\\") == 1\\n\\n\\n# ---------------------------------------------------------------------------\\n# Walk semantics\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_skips_init_and_dunder_files(tmp_path: Path) -> None:\\n    files = {\\n        \\\"__init__.py\\\": \\\"\\\",  # skipped\\n        \\\"__main__.py\\\": \\\"raise SystemExit\\\\n\\\",  # skipped (would crash if executed)\\n        \\\"thing.py\\\": component_source(),\\n    }\\n    root = make_extension(tmp_path, files=files)\\n    result = load_extension(root)\\n    assert result.ok, result.errors\\n    assert {c.class_name for c in result.components} == {\\\"PilotThing\\\"}\\n\\n\\ndef test_recurses_subdirectories(tmp_path: Path) -> None:\\n    files = {\\n        \\\"a.py\\\": component_source(\\\"Alpha\\\"),\\n        \\\"nested/b.py\\\": component_source(\\\"Bravo\\\"),\\n        \\\"nested/deep/c.py\\\": component_source(\\\"Charlie\\\"),\\n    }\\n    root = make_extension(tmp_path, files=files)\\n    result = load_extension(root)\\n    assert result.ok, result.errors\\n    assert {c.class_name for c in result.components} == {\\\"Alpha\\\", \\\"Bravo\\\", \\\"Charlie\\\"}\\n\\n\\ndef test_component_order_is_deterministic(tmp_path: Path) -> None:\\n    files = {\\n        \\\"z.py\\\": component_source(\\\"Zeta\\\"),\\n        \\\"a.py\\\": component_source(\\\"Alpha\\\"),\\n        \\\"m.py\\\": component_source(\\\"Mike\\\"),\\n    }\\n    root = make_extension(tmp_path, files=files)\\n    result_first = load_extension(root)\\n    # Loading the same extension twice yields the same order.\\n    result_second = load_extension(root)\\n    names_first = [c.class_name for c in result_first.components]\\n    names_second = [c.class_name for c in result_second.components]\\n    assert names_first == names_second\\n    assert names_first == [\\\"Alpha\\\", \\\"Mike\\\", \\\"Zeta\\\"]\\n\\n\\ndef test_re_imported_class_is_skipped_via_module_filter(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"The ``__module__``-equality filter prevents re-imported classes from double-registering.\\n\\n    Previous incarnation of this test relied on a relative import that\\n    coincidentally failed because the loader's synthetic ``_lfx_ext.*``\\n    modules aren't registered as packages -- it passed via\\n    ``module-import-failed``, not via the filter under test, so a future\\n    refactor could weaken the actual guard without the test catching it.\\n\\n    This version uses ``sys.modules`` injection: a sibling module's value\\n    is inserted into the alias module's namespace at import time, with the\\n    class's ``__module__`` still pointing at its original definition. The\\n    only thing that prevents double-registration here is the\\n    ``__module__``-equality check in\\n    :func:`lfx.extension.loader._detection.collect_component_classes`.\\n    \\\"\\\"\\\"\\n    # Note: the loader walks files in lex order, so we name the alias\\n    # file ``z_alias.py`` to guarantee it runs AFTER ``primary.py``\\n    # (otherwise the sys.modules lookup below would StopIteration on an\\n    # empty generator).\\n    files = {\\n        \\\"primary.py\\\": component_source(\\\"Primary\\\"),\\n        # Pull the already-loaded primary module out of sys.modules and\\n        # alias its Primary class into our namespace WITHOUT changing the\\n        # class's __module__. The loader's filter must reject it because\\n        # __module__ != alias's synthetic module name.\\n        \\\"z_alias.py\\\": (\\n            \\\"import sys\\\\n\\\"\\n            \\\"_primary = next(\\\\n\\\"\\n            \\\"    m for name, m in sys.modules.items()\\\\n\\\"\\n            \\\"    if name.startswith('_lfx_ext.') and name.endswith('primary')\\\\n\\\"\\n            \\\")\\\\n\\\"\\n            \\\"Primary = _primary.Primary  # re-export, NOT re-declaration\\\\n\\\"\\n        ),\\n    }\\n    root = make_extension(tmp_path, files=files)\\n    result = load_extension(root)\\n    # No import errors: both files imported cleanly. This is the key\\n    # difference from the old test -- if alias.py had failed, we would\\n    # have been testing the wrong code path.\\n    import_errors = [e for e in result.errors if e.code == \\\"module-import-failed\\\"]\\n    assert import_errors == [], f\\\"alias.py should import cleanly; got {import_errors}\\\"\\n    # Exactly one Primary registration -- the filter rejected the alias.\\n    primary_count = sum(1 for c in result.components if c.class_name == \\\"Primary\\\")\\n    assert primary_count == 1, f\\\"__module__ filter failed: expected 1 Primary registration, got {primary_count}\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Path-safety: symlink-escape after validate\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_symlink_escape_silently_skipped(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A symlink under the bundle that points outside is silently skipped.\\n\\n    The path-safety check in the discovery walker quietly ignores escaping\\n    symlinks rather than aborting the load: we want ``ok=True`` if the\\n    in-tree files are fine, with the offending symlink simply absent from\\n    the registry.  ``path-escape`` errors at the bundle-root level are\\n    raised by the orchestrator's path resolver and exercised in\\n    test_validate.py.\\n    \\\"\\\"\\\"\\n    files = {\\\"thing.py\\\": component_source()}\\n    root = make_extension(tmp_path, files=files)\\n    bundle_dir = root / \\\"components\\\"\\n    outside = tmp_path / \\\"outside.py\\\"\\n    outside.write_text(\\\"class Component: pass\\\\nclass Outside(Component):\\\\n    pass\\\\n\\\", encoding=\\\"utf-8\\\")\\n    symlink = bundle_dir / \\\"outside_link.py\\\"\\n    try:\\n        symlink.symlink_to(outside)\\n    except OSError:\\n        pytest.skip(\\\"filesystem does not support symlinks\\\")\\n    result = load_extension(root)\\n    # Only the in-tree component registers.\\n    assert {c.class_name for c in result.components} == {\\\"PilotThing\\\"}\\n\\n\\n# ---------------------------------------------------------------------------\\n# Argument validation\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_invalid_slot_raises() -> None:\\n    with pytest.raises(ValueError, match=\\\"slot must be one of\\\"):\\n        load_extension(\\\"/tmp\\\", slot=\\\"bogus\\\")  # type: ignore[arg-type]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/loader/test_load_installed.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8339d74ee6152bbece74f790302e9141fafc7655b217393054d57604e99a3e4a\",\"content\":\"\\\"\\\"\\\"Tests for ``load_installed_extensions`` -- startup-time discovery flow.\\n\\nCovers the AC item: \\\"Tracked by distribution name; two same-named distributions\\nemit duplicate-distribution.\\\" Also exercises the lexicographically-first\\nmanifest-path tiebreaker that drives the winner selection.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom pathlib import Path\\n\\nimport pytest\\nfrom lfx.extension import (\\n    SLOT_OFFICIAL,\\n    load_installed_extensions,\\n)\\n\\nfrom .conftest import FakeDist, component_source, make_installed_extension\\n\\n\\ndef _populate_bundle(parent: Path, distribution_name: str) -> None:\\n    \\\"\\\"\\\"Put a Component source file under the manifest-declared bundle path.\\\"\\\"\\\"\\n    bundle_dir = parent / distribution_name / \\\"components\\\"\\n    bundle_dir.mkdir(parents=True, exist_ok=True)\\n    (bundle_dir / \\\"thing.py\\\").write_text(component_source(), encoding=\\\"utf-8\\\")\\n\\n\\ndef test_loads_each_installed_extension_once(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Two distinct distributions both load at @official with identity attributed.\\\"\\\"\\\"\\n    dist_a = make_installed_extension(tmp_path, \\\"lfx-alpha\\\")\\n    dist_b = make_installed_extension(tmp_path, \\\"lfx-bravo\\\")\\n    _populate_bundle(tmp_path, \\\"lfx-alpha\\\")\\n    _populate_bundle(tmp_path, \\\"lfx-bravo\\\")\\n\\n    results = load_installed_extensions(distributions=[dist_a, dist_b])\\n    by_dist = {r.distribution: r for r in results}\\n    assert set(by_dist) == {\\\"lfx-alpha\\\", \\\"lfx-bravo\\\"}\\n    for canonical, result in by_dist.items():\\n        assert result.ok, [e.code for e in result.errors]\\n        assert result.slot == SLOT_OFFICIAL\\n        assert result.extension_id == canonical\\n        assert result.distribution == canonical\\n        # Component is attributed via the canonical PEP-503 name.\\n        assert result.components[0].distribution == canonical\\n\\n\\ndef test_duplicate_distribution_emits_warning(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Two distributions with the same canonical name surface duplicate-distribution.\\n\\n    The lexicographically-first manifest path wins; the warning's location\\n    field names every involved manifest path so an operator can resolve.\\n    \\\"\\\"\\\"\\n    # Two on-disk locations, same canonical distribution name.\\n    first_root = tmp_path / \\\"first\\\"\\n    second_root = tmp_path / \\\"second\\\"\\n    first_root.mkdir()\\n    second_root.mkdir()\\n\\n    manifest = {\\n        \\\"id\\\": \\\"lfx-pilot\\\",\\n        \\\"version\\\": \\\"1.0.0\\\",\\n        \\\"name\\\": \\\"lfx-pilot\\\",\\n        \\\"lfx\\\": {\\\"compat\\\": [\\\"1\\\"]},\\n        \\\"bundles\\\": [{\\\"name\\\": \\\"pilot\\\", \\\"path\\\": \\\"components\\\"}],\\n    }\\n    (first_root / \\\"extension.json\\\").write_text(json.dumps(manifest), encoding=\\\"utf-8\\\")\\n    (second_root / \\\"extension.json\\\").write_text(json.dumps(manifest), encoding=\\\"utf-8\\\")\\n    (first_root / \\\"components\\\").mkdir()\\n    (first_root / \\\"components\\\" / \\\"thing.py\\\").write_text(component_source(), encoding=\\\"utf-8\\\")\\n\\n    dist_first = FakeDist(\\n        name=\\\"lfx-pilot\\\",\\n        root=first_root.parent,\\n        files=[Path(\\\"first\\\") / \\\"extension.json\\\"],\\n    )\\n    dist_second = FakeDist(\\n        name=\\\"lfx-pilot\\\",\\n        root=second_root.parent,\\n        files=[Path(\\\"second\\\") / \\\"extension.json\\\"],\\n    )\\n\\n    results = load_installed_extensions(distributions=[dist_first, dist_second])\\n    assert len(results) == 1\\n    result = results[0]\\n    assert result.distribution == \\\"lfx-pilot\\\"\\n    # Winner is the lexicographically-first manifest path.\\n    assert result.source_path == first_root.resolve()\\n    # AC: duplicate-distribution is surfaced as an ERROR (LoadResult.ok=False)\\n    # so the events pipeline emits ``extension_error`` rather than treating\\n    # the conflict as a successful load.\\n    assert not result.ok\\n    codes = [e.code for e in result.errors]\\n    assert \\\"duplicate-distribution\\\" in codes\\n    err = next(e for e in result.errors if e.code == \\\"duplicate-distribution\\\")\\n    # The location field names BOTH manifest paths so the operator can resolve.\\n    assert \\\"first\\\" in err.location\\n    assert \\\"second\\\" in err.location\\n    assert err.content == \\\"lfx-pilot\\\"\\n    assert err.hint  # AC: fix-hint payload\\n    # Winner's components still load -- only the conflict status changes.\\n    assert result.components, \\\"Winner's components should still be loaded\\\"\\n\\n\\ndef test_symlink_aliased_manifest_paths_are_not_duplicates(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Two sys.path spellings of ONE physical manifest must not emit duplicate-distribution.\\n\\n    RHEL-family (ubi) venvs create ``lib64`` as a symlink to ``lib`` and put\\n    both spellings on ``sys.path``, so ``importlib.metadata.distributions()``\\n    yields every installed distribution twice.  Both manifest paths resolve\\n    to the same file, so the loader collapses them to one clean load instead\\n    of a false ``duplicate-distribution`` error.  Physically distinct\\n    manifests still error -- see\\n    :func:`test_duplicate_distribution_emits_warning`.\\n    \\\"\\\"\\\"\\n    lib_root = tmp_path / \\\"lib\\\"\\n    make_installed_extension(lib_root, \\\"lfx-pilot\\\")\\n    _populate_bundle(lib_root, \\\"lfx-pilot\\\")\\n    lib64_root = tmp_path / \\\"lib64\\\"\\n    try:\\n        lib64_root.symlink_to(lib_root, target_is_directory=True)\\n    except OSError:\\n        pytest.skip(\\\"platform does not permit creating symlinks\\\")\\n\\n    dist_lib = FakeDist(\\n        name=\\\"lfx-pilot\\\",\\n        root=lib_root,\\n        files=[Path(\\\"lfx-pilot\\\") / \\\"extension.json\\\"],\\n    )\\n    dist_lib64 = FakeDist(\\n        name=\\\"lfx-pilot\\\",\\n        root=lib64_root,\\n        files=[Path(\\\"lfx-pilot\\\") / \\\"extension.json\\\"],\\n    )\\n\\n    results = load_installed_extensions(distributions=[dist_lib, dist_lib64])\\n    assert len(results) == 1\\n    result = results[0]\\n    assert result.ok, [e.code for e in result.errors]\\n    assert all(e.code != \\\"duplicate-distribution\\\" for e in result.errors)\\n    # The lexicographically-first spelling (lib < lib64) is the winner.\\n    assert result.source_path == (lib_root / \\\"lfx-pilot\\\").resolve()\\n    assert result.components, \\\"Aliased spellings must still load the winner's components\\\"\\n\\n\\ndef test_no_installed_extensions_returns_empty(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A distribution without a manifest contributes nothing.\\\"\\\"\\\"\\n    plain_dist = FakeDist(\\\"plain-pkg\\\", tmp_path, files=[Path(\\\"plain_pkg/__init__.py\\\")])\\n    results = load_installed_extensions(distributions=[plain_dist])\\n    assert results == []\\n\\n\\ndef test_editable_install_discovered_via_direct_url(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Editable installs (``pip install -e``) typically expose only dist-info files.\\n\\n    The dist-info pass finds no ``extension.json``; the loader must fall\\n    back to PEP 610 ``direct_url.json`` (``editable=true``) which records\\n    the source path.  Without this fallback, an ``lfx-duckduckgo`` linked\\n    via ``uv sync`` workspace member never reaches\\n    :func:`load_installed_extensions` -- the dogfood / dev case skipped\\n    the bundle entirely.\\n    \\\"\\\"\\\"\\n    # Lay out a real extension on disk to be the \\\"editable source\\\".\\n    project_root = tmp_path / \\\"src\\\" / \\\"bundles\\\" / \\\"duckduckgo\\\"\\n    bundle_dir = project_root / \\\"components\\\"\\n    bundle_dir.mkdir(parents=True)\\n    (project_root / \\\"extension.json\\\").write_text(\\n        json.dumps(\\n            {\\n                \\\"id\\\": \\\"lfx-pilot\\\",\\n                \\\"version\\\": \\\"1.0.0\\\",\\n                \\\"name\\\": \\\"lfx-pilot\\\",\\n                \\\"lfx\\\": {\\\"compat\\\": [\\\"1\\\"]},\\n                \\\"bundles\\\": [{\\\"name\\\": \\\"pilot\\\", \\\"path\\\": \\\"components\\\"}],\\n            }\\n        ),\\n        encoding=\\\"utf-8\\\",\\n    )\\n    (bundle_dir / \\\"thing.py\\\").write_text(component_source(), encoding=\\\"utf-8\\\")\\n\\n    class _EditableDist(FakeDist):\\n        \\\"\\\"\\\"FakeDist that exposes the same surface as ``importlib.metadata.Distribution``.\\n\\n        Editable installs leave ``files`` listing only dist-info entries;\\n        the manifest is reachable only via ``read_text(\\\"direct_url.json\\\")``.\\n        \\\"\\\"\\\"\\n\\n        def __init__(self, name: str, project_root: Path) -> None:\\n            super().__init__(name=name, root=tmp_path, files=[Path(\\\"dist-info\\\") / \\\"METADATA\\\"])\\n            self._direct_url = json.dumps(\\n                {\\n                    \\\"url\\\": project_root.resolve().as_uri(),\\n                    \\\"dir_info\\\": {\\\"editable\\\": True},\\n                }\\n            )\\n\\n        def read_text(self, name: str) -> str | None:\\n            if name == \\\"direct_url.json\\\":\\n                return self._direct_url\\n            return None\\n\\n        @property\\n        def entry_points(self):\\n            return []\\n\\n    dist = _EditableDist(\\\"lfx-pilot\\\", project_root)\\n\\n    results = load_installed_extensions(distributions=[dist])\\n    assert len(results) == 1\\n    result = results[0]\\n    assert result.ok, [e.code for e in result.errors]\\n    assert result.distribution == \\\"lfx-pilot\\\"\\n    assert result.source_path == project_root.resolve()\\n    assert result.components, \\\"Editable bundle's components must load\\\"\\n\\n\\ndef test_results_are_lexicographically_ordered(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Order is deterministic so events / logging are reproducible.\\\"\\\"\\\"\\n    for name in (\\\"lfx-zeta\\\", \\\"lfx-alpha\\\", \\\"lfx-mike\\\"):\\n        make_installed_extension(tmp_path, name)\\n        _populate_bundle(tmp_path, name)\\n    dists = [\\n        FakeDist(name=\\\"lfx-zeta\\\", root=tmp_path, files=[Path(\\\"lfx-zeta\\\") / \\\"extension.json\\\"]),\\n        FakeDist(name=\\\"lfx-alpha\\\", root=tmp_path, files=[Path(\\\"lfx-alpha\\\") / \\\"extension.json\\\"]),\\n        FakeDist(name=\\\"lfx-mike\\\", root=tmp_path, files=[Path(\\\"lfx-mike\\\") / \\\"extension.json\\\"]),\\n    ]\\n    results = load_installed_extensions(distributions=dists)\\n    assert [r.distribution for r in results] == [\\\"lfx-alpha\\\", \\\"lfx-mike\\\", \\\"lfx-zeta\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/loader/test_load_lfx_bundles.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fd997b9890068def5bae1ab92a0db75fed9e35a29315d8424e947cf983830288\",\"content\":\"\\\"\\\"\\\"Tests for ``load_lfx_bundles_extensions`` -- the manifest-less @official source.\\n\\nThe third @official-slot production source after installed-manifest and\\nseed-directory bundles. A distribution declares ``[project.entry-points.\\\"lfx.bundles\\\"]``\\npointing at a package whose immediate subdirectories are each a bundle,\\nregistered at @official with no ``extension.json`` (the langchain-community\\nmodel). Covers:\\n\\n  - a resolved bundle root registers each provider subdirectory at @official;\\n  - an entry-point declaration that does not resolve to a package directory\\n    yields a ``bundle-discovery-malformed`` *warning* and never raises;\\n  - a manifest source shadows a same-named manifest-less provider with a\\n    ``bundle-shadowed`` warning (the graduate-with-no-lockstep property),\\n    verified through ``_resolve_bundle_shadowing`` directly.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport importlib\\nimport sys\\nfrom pathlib import Path\\nfrom types import SimpleNamespace\\n\\nfrom lfx.extension import SLOT_OFFICIAL, LoadedComponent, LoadResult, load_lfx_bundles_extensions\\nfrom lfx.extension.loader._bundles_root import (\\n    LFX_BUNDLES_ENTRY_POINT_GROUP,\\n    _BundleRoot,\\n    _load_bundle_roots,\\n    _optional_dependency_distributions,\\n    _resolve_bundle_roots,\\n)\\nfrom lfx.extension.loader._orchestrator import _load_bundle_directory\\nfrom lfx.interface.components import _claimed_official_bundles, _emit_extension_diagnostics, _resolve_bundle_shadowing\\n\\nfrom .conftest import component_source\\n\\n\\nclass _FakeBundlesEntryPoint:\\n    \\\"\\\"\\\"An ``lfx.bundles`` entry point stand-in carrying ``name``/``value``/``dist``.\\n\\n    ``value`` is the dotted package name the loader resolves via\\n    ``importlib.util.find_spec``; ``dist`` (optional) supplies the\\n    extension_id/version stamped on discovered components.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, value: str, *, name: str = \\\"lfx_bundles\\\", dist: object | None = None) -> None:\\n        self.name = name\\n        self.value = value\\n        self.dist = dist\\n        self.group = LFX_BUNDLES_ENTRY_POINT_GROUP\\n\\n    def __repr__(self) -> str:  # pragma: no cover - debug aid\\n        return f\\\"_FakeBundlesEntryPoint(name={self.name!r}, value={self.value!r})\\\"\\n\\n\\ndef _make_provider(root: Path, name: str, *, class_name: str | None = None) -> Path:\\n    \\\"\\\"\\\"Create one provider subdirectory with a single Component module.\\\"\\\"\\\"\\n    provider = root / name\\n    provider.mkdir(parents=True, exist_ok=True)\\n    cls = class_name or f\\\"{name.replace('_', ' ').title().replace(' ', '')}Thing\\\"\\n    (provider / \\\"thing.py\\\").write_text(component_source(cls), encoding=\\\"utf-8\\\")\\n    return provider\\n\\n\\ndef _make_bundles_root(parent: Path, *provider_names: str, pkg: str = \\\"lfx_bundles\\\") -> Path:\\n    \\\"\\\"\\\"Lay out a manifest-less metapackage tree: ``<pkg>/<provider>/thing.py``.\\\"\\\"\\\"\\n    root = parent / pkg\\n    root.mkdir(parents=True, exist_ok=True)\\n    (root / \\\"__init__.py\\\").write_text(\\\"\\\", encoding=\\\"utf-8\\\")\\n    for name in provider_names:\\n        _make_provider(root, name)\\n    return root\\n\\n\\ndef _component(bundle: str, class_name: str = \\\"Thing\\\") -> LoadedComponent:\\n    \\\"\\\"\\\"A minimal @official LoadedComponent for resolver-level shadowing tests.\\\"\\\"\\\"\\n    return LoadedComponent(\\n        extension_id=bundle,\\n        extension_version=\\\"1.0.0\\\",\\n        bundle=bundle,\\n        class_name=class_name,\\n        slot=SLOT_OFFICIAL,\\n        klass=object,\\n        module_name=f\\\"_synthetic.{bundle}.{class_name}\\\",\\n        file_path=Path(\\\"synthetic\\\") / bundle / \\\"thing.py\\\",\\n    )\\n\\n\\n# ---------------------------------------------------------------------------\\n# Folder-walk core: _load_bundle_roots\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_root_registers_each_provider_at_official(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Every immediate subdirectory becomes one @official bundle named after it.\\\"\\\"\\\"\\n    root = _make_bundles_root(tmp_path, \\\"alpha\\\", \\\"beta\\\")\\n\\n    results = _load_bundle_roots([_BundleRoot(root, \\\"lfx-bundles\\\", \\\"1.0.0\\\")])\\n    by_bundle = {r.bundle: r for r in results if r.bundle}\\n\\n    assert set(by_bundle) == {\\\"alpha\\\", \\\"beta\\\"}\\n    for bundle, result in by_bundle.items():\\n        assert result.ok, [e.code for e in result.errors]\\n        assert result.slot == SLOT_OFFICIAL\\n        # Manifest-less records carry the providing-distribution identity for\\n        # display but no distribution (they are not the installed-manifest tier).\\n        assert result.distribution is None\\n        assert result.extension_id == \\\"lfx-bundles\\\"\\n        assert result.extension_version == \\\"1.0.0\\\"\\n        assert result.components\\n        for comp in result.components:\\n            assert comp.slot == SLOT_OFFICIAL\\n            assert comp.distribution is None\\n            assert comp.bundle == bundle\\n            assert comp.namespaced_id == f\\\"ext:{bundle}:{comp.class_name}@official\\\"\\n\\n\\ndef test_mrscraper_provider_loads_with_production_bundle_loader(monkeypatch) -> None:\\n    \\\"\\\"\\\"The checked-in MrScraper provider registers all components at @official.\\\"\\\"\\\"\\n    repo_root = Path(__file__).resolve().parents[6]\\n    bundles_source = repo_root / \\\"src\\\" / \\\"bundles\\\" / \\\"lfx-bundles\\\" / \\\"src\\\"\\n    provider = bundles_source / \\\"lfx_bundles\\\" / \\\"mrscraper\\\"\\n    result = LoadResult(\\n        slot=SLOT_OFFICIAL,\\n        source_path=provider,\\n        bundle=\\\"mrscraper\\\",\\n        extension_id=\\\"lfx-bundles\\\",\\n        extension_version=\\\"1.0.0\\\",\\n        manifestless=True,\\n    )\\n    module_prefixes = (\\\"_lfx_ext.official.mrscraper\\\", \\\"lfx_bundles\\\")\\n    prior_modules = {\\n        name: module\\n        for name, module in sys.modules.items()\\n        if name == \\\"lfx_bundles\\\" or name.startswith(tuple(f\\\"{prefix}.\\\" for prefix in module_prefixes))\\n    }\\n    for name in prior_modules:\\n        sys.modules.pop(name, None)\\n\\n    monkeypatch.syspath_prepend(str(bundles_source))\\n    importlib.invalidate_caches()\\n    try:\\n        _load_bundle_directory(\\n            bundle_root=provider,\\n            bundle_name=\\\"mrscraper\\\",\\n            extension_id=\\\"lfx-bundles\\\",\\n            extension_version=\\\"1.0.0\\\",\\n            slot=SLOT_OFFICIAL,\\n            distribution=None,\\n            result=result,\\n        )\\n    finally:\\n        for name in list(sys.modules):\\n            if name == \\\"lfx_bundles\\\" or name.startswith(tuple(f\\\"{prefix}.\\\" for prefix in module_prefixes)):\\n                sys.modules.pop(name, None)\\n        sys.modules.update(prior_modules)\\n        importlib.invalidate_caches()\\n\\n    assert result.ok, [(error.code, error.message) for error in result.errors]\\n    assert {component.class_name for component in result.components} == {\\n        \\\"MrscraperAiScraper\\\",\\n        \\\"MrscraperBatchScrape\\\",\\n        \\\"MrscraperCrawlWebsite\\\",\\n        \\\"MrscraperFetchHtml\\\",\\n        \\\"MrscraperGetResult\\\",\\n        \\\"MrscraperGetResults\\\",\\n        \\\"MrscraperRunAiScraper\\\",\\n        \\\"MrscraperRunManualScraper\\\",\\n    }\\n\\n\\ndef test_invalid_provider_name_emits_typed_warning_and_skips(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A provider folder that is not lowercase snake_case is surfaced, not silently dropped.\\n\\n    Dedicated code (not ``bundle-discovery-malformed``): the fix is renaming\\n    the directory, not editing the entry-point declaration, and the rendered\\n    template/hint must say so.\\n    \\\"\\\"\\\"\\n    root = _make_bundles_root(tmp_path, \\\"good\\\")\\n    _make_provider(root, \\\"BadName\\\")  # capitals fail BUNDLE_NAME_RE\\n\\n    results = _load_bundle_roots([_BundleRoot(root, \\\"lfx-bundles\\\", \\\"1.0.0\\\")])\\n\\n    loaded = {r.bundle for r in results if r.bundle and r.components}\\n    assert loaded == {\\\"good\\\"}  # the invalid one did not load\\n    invalid = [e for r in results for e in r.warnings if e.code == \\\"bundles-provider-name-invalid\\\"]\\n    assert any(e.content == \\\"BadName\\\" for e in invalid)\\n    # The invalid entry produced no components.\\n    assert all(not r.components for r in results if any(w.content == \\\"BadName\\\" for w in r.warnings))\\n\\n\\ndef test_internal_directories_skipped_silently(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Dot/underscore-prefixed and __pycache__ dirs are package machinery, not bundles.\\\"\\\"\\\"\\n    root = _make_bundles_root(tmp_path, \\\"valid\\\")\\n    (root / \\\"_shared\\\").mkdir()\\n    (root / \\\"_shared\\\" / \\\"base.py\\\").write_text(\\\"X = 1\\\\n\\\", encoding=\\\"utf-8\\\")\\n    (root / \\\".hidden\\\").mkdir()\\n    (root / \\\"__pycache__\\\").mkdir()\\n\\n    results = _load_bundle_roots([_BundleRoot(root, \\\"lfx-bundles\\\", \\\"1.0.0\\\")])\\n\\n    assert [r.bundle for r in results if r.bundle] == [\\\"valid\\\"]\\n    # No spurious warnings for the internal directories.\\n    assert not [e for r in results for e in r.warnings]\\n\\n\\ndef test_symlinked_provider_escaping_root_is_skipped(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A provider dir symlinked outside the bundle root is rejected, not loaded.\\n\\n    Mirrors the seed-directory walk's containment rule: the trust boundary is\\n    the installed package tree, so a symlink pointing elsewhere (e.g. into an\\n    operator's filesystem) must not be folder-walked and imported.\\n    \\\"\\\"\\\"\\n    outside = tmp_path / \\\"outside\\\" / \\\"evil\\\"\\n    outside.mkdir(parents=True)\\n    (outside / \\\"thing.py\\\").write_text(component_source(\\\"EvilThing\\\"), encoding=\\\"utf-8\\\")\\n\\n    root = _make_bundles_root(tmp_path, \\\"good\\\")\\n    (root / \\\"escapee\\\").symlink_to(outside, target_is_directory=True)\\n\\n    results = _load_bundle_roots([_BundleRoot(root, \\\"lfx-bundles\\\", \\\"1.0.0\\\")])\\n\\n    loaded = {r.bundle for r in results if r.bundle and r.components}\\n    assert loaded == {\\\"good\\\"}  # the symlinked-out provider did not load\\n    escapes = [e for r in results for e in r.warnings if e.code == \\\"path-escape\\\"]\\n    assert any(e.content == \\\"escapee\\\" and \\\"outside the bundle root\\\" in e.message for e in escapes)\\n\\n\\ndef test_duplicate_provider_across_roots_first_wins(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Two roots shipping the same provider name: first wins, loser warns.\\\"\\\"\\\"\\n    root_a = _make_bundles_root(tmp_path / \\\"a\\\", \\\"dup\\\", pkg=\\\"lfx_bundles\\\")\\n    root_b = _make_bundles_root(tmp_path / \\\"b\\\", \\\"dup\\\", pkg=\\\"lfx_bundles_other\\\")\\n\\n    results = _load_bundle_roots(\\n        [\\n            _BundleRoot(root_a, \\\"lfx-bundles\\\", \\\"1.0.0\\\"),\\n            _BundleRoot(root_b, \\\"lfx-bundles-other\\\", \\\"2.0.0\\\"),\\n        ]\\n    )\\n\\n    dup_results = [r for r in results if r.bundle == \\\"dup\\\"]\\n    with_components = [r for r in dup_results if r.components]\\n    # Same-tier duplicate carries its own code -- ``bundle-shadowed`` means\\n    # cross-source precedence and would render a misleading template here.\\n    shadowed = [r for r in dup_results if any(e.code == \\\"duplicate-lfx-bundles-provider\\\" for e in r.warnings)]\\n    assert len(with_components) == 1  # exactly one winner\\n    assert len(shadowed) == 1  # exactly one shadowed loser\\n    assert not shadowed[0].components\\n\\n\\ndef test_claimed_bundle_name_is_not_imported(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A name won by an installed/seed source is skipped *without importing*.\\n\\n    All @official sources share the ``_lfx_ext.official.<bundle>.*``\\n    sys.modules namespace; importing the metapackage's losing copy would\\n    overwrite the winner's live modules even though shadow resolution drops\\n    the loser's components afterwards.  This is the expected post-graduation\\n    state (standalone ``lfx-<provider>`` next to an older metapackage).\\n    \\\"\\\"\\\"\\n    root = _make_bundles_root(tmp_path, \\\"claimedprov\\\", \\\"freeprov\\\")\\n\\n    results = _load_bundle_roots(\\n        [_BundleRoot(root, \\\"lfx-bundles\\\", \\\"1.0.0\\\")],\\n        claimed_bundles={\\\"claimedprov\\\": (\\\"installed\\\", \\\"/site-packages/lfx_claimedprov\\\")},\\n    )\\n    by_bundle = {r.bundle: r for r in results if r.bundle}\\n\\n    assert set(by_bundle) == {\\\"claimedprov\\\", \\\"freeprov\\\"}\\n    claimed = by_bundle[\\\"claimedprov\\\"]\\n    assert not claimed.components\\n    # Same code AND same severity as _resolve_bundle_shadowing emits\\n    # for every other cross-source shadow pair.\\n    assert [e.code for e in claimed.warnings] == [\\\"bundle-shadowed\\\"]\\n    assert \\\"installed\\\" in claimed.warnings[0].message\\n    assert claimed.ok\\n    # The decisive property: nothing was imported for the claimed name, so\\n    # the winner's live modules cannot have been overwritten.\\n    assert not [k for k in sys.modules if k.startswith(\\\"_lfx_ext.official.claimedprov\\\")]\\n    # The unclaimed sibling in the same root still loads normally.\\n    assert by_bundle[\\\"freeprov\\\"].components\\n\\n\\ndef test_provider_results_are_marked_manifestless(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Provider results carry the provenance flag the reload pipeline keys on.\\\"\\\"\\\"\\n    root = _make_bundles_root(tmp_path, \\\"flagged\\\")\\n\\n    results = _load_bundle_roots([_BundleRoot(root, \\\"lfx-bundles\\\", \\\"1.0.0\\\")])\\n\\n    assert results\\n    assert all(r.manifestless for r in results if r.bundle)\\n\\n\\ndef test_declared_optional_dependency_missing_is_warning_only(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A missing dependency declared by this provider extra does not fail startup.\\\"\\\"\\\"\\n    root = _make_bundles_root(tmp_path, \\\"composio\\\")\\n    (root / \\\"composio\\\" / \\\"thing.py\\\").write_text(\\\"import composio_missing_fixture\\\\n\\\", encoding=\\\"utf-8\\\")\\n    requirements = ('composio-missing-fixture>=1; extra == \\\"composio\\\"',)\\n\\n    results = _load_bundle_roots([_BundleRoot(root, \\\"lfx-bundles\\\", \\\"1.0.0\\\", requirements)])\\n\\n    result = next(item for item in results if item.bundle == \\\"composio\\\")\\n    assert result.ok\\n    assert not result.errors\\n    assert [warning.code for warning in result.warnings] == [\\\"optional-dependency-missing\\\"]\\n    assert result.warnings[0].content == \\\"composio_missing_fixture\\\"\\n\\n\\ndef test_undeclared_missing_dependency_remains_error(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Manifest-less code cannot downgrade an undeclared import failure.\\\"\\\"\\\"\\n    root = _make_bundles_root(tmp_path, \\\"composio\\\")\\n    (root / \\\"composio\\\" / \\\"thing.py\\\").write_text(\\\"import unrelated_missing_fixture\\\\n\\\", encoding=\\\"utf-8\\\")\\n    requirements = ('composio>=1; extra == \\\"composio\\\"',)\\n\\n    results = _load_bundle_roots([_BundleRoot(root, \\\"lfx-bundles\\\", \\\"1.0.0\\\", requirements)])\\n\\n    result = next(item for item in results if item.bundle == \\\"composio\\\")\\n    assert not result.ok\\n    assert [error.code for error in result.errors] == [\\\"module-import-failed\\\"]\\n    assert not result.warnings\\n\\n\\ndef test_only_module_not_found_is_downgraded_for_manifestless_bundle(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"ImportError, syntax failures, and runtime failures stay hard errors.\\\"\\\"\\\"\\n    root = _make_bundles_root(tmp_path, \\\"composio\\\")\\n    provider = root / \\\"composio\\\"\\n    (provider / \\\"import_error.py\\\").write_text(\\\"raise ImportError('missing symbol')\\\\n\\\", encoding=\\\"utf-8\\\")\\n    (provider / \\\"syntax_error.py\\\").write_text(\\\"if:\\\\n\\\", encoding=\\\"utf-8\\\")\\n    (provider / \\\"runtime_error.py\\\").write_text(\\\"raise RuntimeError('boom')\\\\n\\\", encoding=\\\"utf-8\\\")\\n    requirements = ('composio>=1; extra == \\\"composio\\\"',)\\n\\n    results = _load_bundle_roots([_BundleRoot(root, \\\"lfx-bundles\\\", \\\"1.0.0\\\", requirements)])\\n\\n    result = next(item for item in results if item.bundle == \\\"composio\\\")\\n    assert [error.code for error in result.errors] == [\\\"module-import-failed\\\"] * 3\\n    assert not [warning for warning in result.warnings if warning.code == \\\"optional-dependency-missing\\\"]\\n\\n\\ndef test_declared_missing_dependency_stays_error_outside_manifestless_tier(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Installed, seed, dev, and inline loaders cannot opt into this downgrade.\\\"\\\"\\\"\\n    provider = tmp_path / \\\"composio\\\"\\n    provider.mkdir()\\n    (provider / \\\"thing.py\\\").write_text(\\\"import composio_missing_fixture\\\\n\\\", encoding=\\\"utf-8\\\")\\n    result = LoadResult(slot=SLOT_OFFICIAL, source_path=provider, bundle=\\\"composio\\\", manifestless=False)\\n\\n    _load_bundle_directory(\\n        bundle_root=provider,\\n        bundle_name=\\\"composio\\\",\\n        extension_id=\\\"lfx-composio\\\",\\n        extension_version=\\\"1.0.0\\\",\\n        slot=SLOT_OFFICIAL,\\n        distribution=\\\"lfx-composio\\\",\\n        result=result,\\n        optional_dependency_distributions={\\\"composiomissingfixture\\\": \\\"composio-missing-fixture\\\"},\\n    )\\n\\n    assert [error.code for error in result.errors] == [\\\"module-import-failed\\\"]\\n    assert not result.warnings\\n\\n\\ndef test_optional_dependency_distributions_come_from_matching_extra_metadata() -> None:\\n    requirements = (\\n        'langchain-mistralai>=1; extra == \\\"mistral\\\"',\\n        'opensearch-py>=2; extra == \\\"elastic\\\"',\\n        'unrelated>=1; extra == \\\"other\\\"',\\n    )\\n\\n    mistral_distributions = _optional_dependency_distributions(requirements, bundle_name=\\\"mistral\\\")\\n    assert mistral_distributions == {\\\"langchainmistralai\\\": \\\"langchain-mistralai\\\"}\\n    elastic_distributions = _optional_dependency_distributions(requirements, bundle_name=\\\"elastic\\\")\\n    assert elastic_distributions == {\\\"opensearchpy\\\": \\\"opensearch-py\\\"}\\n\\n\\ndef test_shared_lfx_namespace_failure_remains_error(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A declared lfx-* distribution cannot downgrade arbitrary lfx.* failures.\\\"\\\"\\\"\\n    root = _make_bundles_root(tmp_path, \\\"openai\\\")\\n    (root / \\\"openai\\\" / \\\"thing.py\\\").write_text(\\\"import lfx.missing_optional_fixture\\\\n\\\", encoding=\\\"utf-8\\\")\\n    requirements = ('lfx-openai>=1; extra == \\\"openai\\\"',)\\n\\n    results = _load_bundle_roots([_BundleRoot(root, \\\"lfx-bundles\\\", \\\"1.0.0\\\", requirements)])\\n\\n    result = next(item for item in results if item.bundle == \\\"openai\\\")\\n    assert [error.code for error in result.errors] == [\\\"module-import-failed\\\"]\\n    assert not result.warnings\\n\\n\\ndef test_shared_langchain_namespace_failure_remains_error(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A declared langchain-* distribution cannot downgrade arbitrary langchain.* failures.\\\"\\\"\\\"\\n    root = _make_bundles_root(tmp_path, \\\"mistral\\\")\\n    (root / \\\"mistral\\\" / \\\"thing.py\\\").write_text(\\\"import langchain.missing_optional_fixture\\\\n\\\", encoding=\\\"utf-8\\\")\\n    requirements = ('langchain-mistralai>=1; extra == \\\"mistral\\\"',)\\n\\n    results = _load_bundle_roots([_BundleRoot(root, \\\"lfx-bundles\\\", \\\"1.0.0\\\", requirements)])\\n\\n    result = next(item for item in results if item.bundle == \\\"mistral\\\")\\n    assert [error.code for error in result.errors] == [\\\"module-import-failed\\\"]\\n    assert not result.warnings\\n\\n\\ndef test_installed_but_broken_optional_dependency_remains_error(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Metadata presence proves the dependency is installed, so a broken import stays hard.\\\"\\\"\\\"\\n    root = _make_bundles_root(tmp_path, \\\"packaging_provider\\\")\\n    (root / \\\"packaging_provider\\\" / \\\"thing.py\\\").write_text(\\n        \\\"import packaging.missing_optional_fixture\\\\n\\\", encoding=\\\"utf-8\\\"\\n    )\\n    requirements = ('packaging>=1; extra == \\\"packaging-provider\\\"',)\\n\\n    results = _load_bundle_roots([_BundleRoot(root, \\\"lfx-bundles\\\", \\\"1.0.0\\\", requirements)])\\n\\n    result = next(item for item in results if item.bundle == \\\"packaging_provider\\\")\\n    assert [error.code for error in result.errors] == [\\\"module-import-failed\\\"]\\n    assert not result.warnings\\n\\n\\ndef test_entry_point_distribution_metadata_drives_optional_warning(tmp_path: Path, monkeypatch) -> None:\\n    \\\"\\\"\\\"The production entry-point path carries Requires-Dist into provider loading.\\\"\\\"\\\"\\n    package_name = \\\"lfx_bundles_optional_metadata_fixture\\\"\\n    root = _make_bundles_root(tmp_path, \\\"composio\\\", pkg=package_name)\\n    (root / \\\"composio\\\" / \\\"thing.py\\\").write_text(\\\"import composio_missing_fixture\\\\n\\\", encoding=\\\"utf-8\\\")\\n    distribution = SimpleNamespace(\\n        name=\\\"lfx-bundles\\\",\\n        version=\\\"1.0.0\\\",\\n        requires=['composio-missing-fixture>=1; extra == \\\"composio\\\"'],\\n    )\\n    monkeypatch.syspath_prepend(str(tmp_path))\\n    importlib.invalidate_caches()\\n    try:\\n        results = load_lfx_bundles_extensions(entry_points=[_FakeBundlesEntryPoint(package_name, dist=distribution)])\\n    finally:\\n        importlib.invalidate_caches()\\n\\n    result = next(item for item in results if item.bundle == \\\"composio\\\")\\n    assert result.ok\\n    assert [warning.code for warning in result.warnings] == [\\\"optional-dependency-missing\\\"]\\n\\n\\ndef test_optional_dependency_diagnostics_are_aggregated(monkeypatch, tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Repeated missing imports produce one operator warning plus debug details.\\\"\\\"\\\"\\n    from lfx.extension.errors import ExtensionError\\n    from lfx.interface import components as components_module\\n\\n    missing_modules = (\\\"composio.foo\\\", \\\"composio.bar\\\", \\\"composio\\\")\\n    results = []\\n    for index, missing_module in enumerate(missing_modules):\\n        result = LoadResult(bundle=\\\"composio\\\", manifestless=True)\\n        result.warnings.append(\\n            ExtensionError(\\n                code=\\\"optional-dependency-missing\\\",\\n                message=\\\"ModuleNotFoundError: optional dependency is not installed.\\\",\\n                location=str(tmp_path / f\\\"module_{index}.py\\\"),\\n                content=missing_module,\\n                hint=\\\"Install lfx-bundles[composio].\\\",\\n            )\\n        )\\n        results.append(result)\\n    warning_calls = []\\n    debug_calls = []\\n    monkeypatch.setattr(components_module.logger, \\\"warning\\\", lambda *args: warning_calls.append(args))\\n    monkeypatch.setattr(components_module.logger, \\\"debug\\\", lambda *args: debug_calls.append(args))\\n\\n    _emit_extension_diagnostics(results)\\n\\n    assert len(warning_calls) == 1\\n    assert warning_calls[0][2] == \\\"composio\\\"\\n    assert warning_calls[0][3] == 3\\n    assert str(tmp_path / \\\"module_0.py\\\") == warning_calls[0][4]\\n    assert len(debug_calls) == 3\\n\\n\\ndef test_claimed_official_bundles_first_wins_and_requires_components(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"The claim map mirrors the resolver's winner rule.\\n\\n    Only results that produced components claim a name, and the\\n    highest-precedence claimant (installed before seed) wins.\\n    \\\"\\\"\\\"\\n    installed_alpha = LoadResult(\\n        slot=SLOT_OFFICIAL,\\n        bundle=\\\"alpha\\\",\\n        source_path=tmp_path / \\\"inst\\\" / \\\"alpha\\\",\\n        components=[_component(\\\"alpha\\\")],\\n    )\\n    seed_alpha = LoadResult(\\n        slot=SLOT_OFFICIAL,\\n        bundle=\\\"alpha\\\",\\n        source_path=tmp_path / \\\"seed\\\" / \\\"alpha\\\",\\n        components=[_component(\\\"alpha\\\")],\\n    )\\n    seed_empty = LoadResult(slot=SLOT_OFFICIAL, bundle=\\\"empty\\\", source_path=tmp_path / \\\"seed\\\" / \\\"empty\\\")\\n\\n    claimed = _claimed_official_bundles([installed_alpha], [seed_alpha, seed_empty])\\n\\n    assert claimed == {\\\"alpha\\\": (\\\"installed\\\", str(tmp_path / \\\"inst\\\" / \\\"alpha\\\"))}\\n\\n\\n# ---------------------------------------------------------------------------\\n# Entry-point resolution + malformed declarations\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_unresolvable_declaration_warns_and_does_not_raise() -> None:\\n    \\\"\\\"\\\"A declaration pointing at a non-existent module degrades to a warning.\\\"\\\"\\\"\\n    roots, sentinels = _resolve_bundle_roots([_FakeBundlesEntryPoint(\\\"module_that_does_not_exist_xyz\\\")])\\n\\n    assert roots == []\\n    codes = [e.code for s in sentinels for e in s.warnings]\\n    assert codes == [\\\"bundle-discovery-malformed\\\"]\\n    # Warning-only: ok stays True, so a broken third-party declaration never\\n    # flips a startup gate.\\n    assert all(s.ok for s in sentinels)\\n\\n\\ndef test_empty_entry_point_value_is_malformed() -> None:\\n    \\\"\\\"\\\"An empty entry-point value is reported, not silently ignored.\\\"\\\"\\\"\\n    roots, sentinels = _resolve_bundle_roots([_FakeBundlesEntryPoint(\\\"\\\")])\\n    assert roots == []\\n    assert [e.code for s in sentinels for e in s.warnings] == [\\\"bundle-discovery-malformed\\\"]\\n\\n\\ndef test_raising_parent_package_degrades_to_malformed(tmp_path: Path, monkeypatch) -> None:\\n    \\\"\\\"\\\"A dotted declaration whose parent package raises on import never escapes.\\n\\n    ``find_spec(\\\"pkg.sub\\\")`` imports ``pkg`` -- arbitrary third-party\\n    ``__init__`` code that can raise anything, not just ImportError.  An\\n    escape here would reach the palette cache's catch-all and wipe EVERY\\n    source's components for the boot; instead it degrades to one malformed\\n    sentinel and the rest of discovery proceeds.\\n    \\\"\\\"\\\"\\n    pkg = tmp_path / \\\"rottenpkg_fixture\\\"\\n    pkg.mkdir()\\n    (pkg / \\\"__init__.py\\\").write_text(\\\"raise RuntimeError('boom')\\\\n\\\", encoding=\\\"utf-8\\\")\\n    (pkg / \\\"bundles\\\").mkdir()\\n    (pkg / \\\"bundles\\\" / \\\"__init__.py\\\").write_text(\\\"\\\", encoding=\\\"utf-8\\\")\\n    monkeypatch.syspath_prepend(str(tmp_path))\\n    importlib.invalidate_caches()\\n    try:\\n        roots, sentinels = _resolve_bundle_roots([_FakeBundlesEntryPoint(\\\"rottenpkg_fixture.bundles\\\")])\\n        assert roots == []\\n        assert [e.code for s in sentinels for e in s.warnings] == [\\\"bundle-discovery-malformed\\\"]\\n        assert \\\"RuntimeError\\\" in sentinels[0].warnings[0].message\\n        assert all(s.ok for s in sentinels)\\n    finally:\\n        sys.modules.pop(\\\"rottenpkg_fixture\\\", None)\\n        importlib.invalidate_caches()\\n\\n\\ndef test_namespace_package_portions_are_all_walked(tmp_path: Path, monkeypatch) -> None:\\n    \\\"\\\"\\\"Every portion of a namespace package contributes providers.\\n\\n    A namespace package split across two sys.path entries has one\\n    ``submodule_search_locations`` entry per portion; walking only the first\\n    would silently drop the other portion's providers (with the winner\\n    decided by sys.path order).\\n    \\\"\\\"\\\"\\n    pkg = \\\"ns_bundles_fixture\\\"\\n    for portion, provider in ((\\\"a\\\", \\\"portiona_prov\\\"), (\\\"b\\\", \\\"portionb_prov\\\")):\\n        root = tmp_path / portion / pkg\\n        root.mkdir(parents=True)  # deliberately no __init__.py: namespace portions\\n        _make_provider(root, provider)\\n        monkeypatch.syspath_prepend(str(tmp_path / portion))\\n    importlib.invalidate_caches()\\n    try:\\n        results = load_lfx_bundles_extensions(entry_points=[_FakeBundlesEntryPoint(pkg)])\\n        loaded = {r.bundle for r in results if r.bundle and r.components}\\n        assert loaded == {\\\"portiona_prov\\\", \\\"portionb_prov\\\"}\\n        assert not [e for r in results for e in (*r.warnings, *r.errors)]\\n    finally:\\n        importlib.invalidate_caches()\\n\\n\\ndef test_duplicate_entry_points_walk_the_root_once(tmp_path: Path, monkeypatch) -> None:\\n    \\\"\\\"\\\"Two declarations naming the same package do not walk its directory twice.\\n\\n    Without path-level dedupe the second walk would make every provider in\\n    the root shadow-warn against itself.\\n    \\\"\\\"\\\"\\n    pkg = \\\"dup_ep_bundles_fixture\\\"\\n    _make_bundles_root(tmp_path, \\\"dupepprov\\\", pkg=pkg)\\n    monkeypatch.syspath_prepend(str(tmp_path))\\n    importlib.invalidate_caches()\\n    try:\\n        results = load_lfx_bundles_extensions(\\n            entry_points=[\\n                _FakeBundlesEntryPoint(pkg, name=\\\"first\\\"),\\n                _FakeBundlesEntryPoint(pkg, name=\\\"second\\\"),\\n            ]\\n        )\\n        dup = [r for r in results if r.bundle == \\\"dupepprov\\\"]\\n        assert len(dup) == 1\\n        assert dup[0].components\\n        assert not [e for r in results for e in (*r.warnings, *r.errors)]\\n    finally:\\n        importlib.invalidate_caches()\\n\\n\\ndef test_plain_module_entry_point_is_malformed_not_scanned(tmp_path: Path, monkeypatch) -> None:\\n    \\\"\\\"\\\"A declaration pointing at a single-file module is malformed, not a root.\\n\\n    A plain module has no provider subdirectories; treating its parent\\n    directory as a bundle root would folder-walk unrelated siblings (here a\\n    provider-shaped directory next to the module file).\\n    \\\"\\\"\\\"\\n    module_name = \\\"lfx_bundles_plain_module_fixture\\\"\\n    (tmp_path / f\\\"{module_name}.py\\\").write_text(\\\"\\\", encoding=\\\"utf-8\\\")\\n    _make_provider(tmp_path, \\\"sneaky_sibling\\\")\\n    monkeypatch.syspath_prepend(str(tmp_path))\\n    importlib.invalidate_caches()\\n    try:\\n        roots, sentinels = _resolve_bundle_roots([_FakeBundlesEntryPoint(module_name)])\\n        assert roots == []\\n        assert [e.code for s in sentinels for e in s.warnings] == [\\\"bundle-discovery-malformed\\\"]\\n        assert all(s.ok for s in sentinels)\\n    finally:\\n        importlib.invalidate_caches()\\n\\n\\ndef test_no_entry_points_is_empty_no_op() -> None:\\n    \\\"\\\"\\\"Engine-only install (no distribution declares lfx.bundles) -> [].\\\"\\\"\\\"\\n    assert load_lfx_bundles_extensions(entry_points=[]) == []\\n\\n\\ndef test_end_to_end_real_package_resolution(tmp_path: Path, monkeypatch) -> None:\\n    \\\"\\\"\\\"A real importable package on sys.path resolves and its providers load.\\\"\\\"\\\"\\n    pkg_name = \\\"lfx_bundles_e2e_fixture\\\"\\n    _make_bundles_root(tmp_path, \\\"gamma\\\", \\\"delta\\\", pkg=pkg_name)\\n    monkeypatch.syspath_prepend(str(tmp_path))\\n    importlib.invalidate_caches()\\n    try:\\n        results = load_lfx_bundles_extensions(entry_points=[_FakeBundlesEntryPoint(pkg_name)])\\n        by_bundle = {r.bundle: r for r in results if r.bundle and r.components}\\n        assert set(by_bundle) == {\\\"gamma\\\", \\\"delta\\\"}\\n        for result in by_bundle.values():\\n            assert result.slot == SLOT_OFFICIAL\\n            assert result.ok, [e.code for e in result.errors]\\n    finally:\\n        importlib.invalidate_caches()\\n\\n\\n# ---------------------------------------------------------------------------\\n# Cross-source precedence: manifest shadows manifest-less (the graduation property)\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_installed_manifest_shadows_manifest_less_provider() -> None:\\n    \\\"\\\"\\\"A graduated lfx-<provider> (installed manifest) wins over the same name in lfx-bundles.\\\"\\\"\\\"\\n    installed = LoadResult(\\n        slot=SLOT_OFFICIAL,\\n        source_path=Path(\\\"/install/lfx_openai\\\"),\\n        distribution=\\\"lfx-openai\\\",\\n        bundle=\\\"openai\\\",\\n        components=[_component(\\\"openai\\\")],\\n    )\\n    metapackage = LoadResult(\\n        slot=SLOT_OFFICIAL,\\n        source_path=Path(\\\"/install/lfx_bundles/openai\\\"),\\n        distribution=None,\\n        bundle=\\\"openai\\\",\\n        components=[_component(\\\"openai\\\")],\\n    )\\n\\n    _resolve_bundle_shadowing(\\n        extension_results=[installed],\\n        seed_results=[],\\n        lfx_bundles_results=[metapackage],\\n        dev_results=[],\\n        inline_results=[],\\n    )\\n\\n    # Installed manifest keeps its components; the manifest-less copy is dropped\\n    # with a typed bundle-shadowed warning.\\n    assert installed.components\\n    assert metapackage.components == []\\n    assert any(e.code == \\\"bundle-shadowed\\\" for e in metapackage.warnings)\\n    assert metapackage.ok\\n\\n\\ndef test_manifest_less_shadows_loose_inline_source() -> None:\\n    \\\"\\\"\\\"lfx-bundles sits above the loose dev/inline sources in precedence.\\\"\\\"\\\"\\n    metapackage = LoadResult(\\n        slot=SLOT_OFFICIAL,\\n        source_path=Path(\\\"/install/lfx_bundles/tavily\\\"),\\n        distribution=None,\\n        bundle=\\\"tavily\\\",\\n        components=[_component(\\\"tavily\\\")],\\n    )\\n    inline = LoadResult(\\n        slot=\\\"extra\\\",\\n        source_path=Path(\\\"/loose/tavily\\\"),\\n        distribution=None,\\n        bundle=\\\"tavily\\\",\\n        components=[_component(\\\"tavily\\\")],\\n    )\\n\\n    _resolve_bundle_shadowing(\\n        extension_results=[],\\n        seed_results=[],\\n        lfx_bundles_results=[metapackage],\\n        dev_results=[],\\n        inline_results=[inline],\\n    )\\n\\n    assert metapackage.components  # higher precedence wins\\n    assert inline.components == []\\n    assert any(e.code == \\\"bundle-shadowed\\\" for e in inline.warnings)\\n    assert inline.ok\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/loader/test_load_seed.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b65ea754e9a4f29712d6f9da7f9c38a608bb0b46ae70532f0974c21295b6266b\",\"content\":\"\\\"\\\"\\\"Tests for ``load_seed_extensions`` -- the filesystem-resident @official source.\\n\\nCovers the deployment-doc contract: an immediate subdirectory of\\n``$LANGFLOW_SEED_DIR`` (or the default ``/opt/langflow/bundles/``) that\\nships a v0 manifest is loaded at the @official slot, identical in shape to\\na pip-installed distribution. Configured-but-missing roots emit a typed\\n``seed-directory-not-found`` error; the default-and-absent case is a silent\\nno-op so Mode A laptops do not pay for a missing ``/opt`` path.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport os\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.extension import (\\n    SLOT_OFFICIAL,\\n    load_seed_extensions,\\n)\\n\\nfrom .conftest import make_extension\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n\\ndef _seed_subdir(seed_root: Path, extension_id: str, *, bundle_name: str = \\\"pilot\\\") -> Path:\\n    \\\"\\\"\\\"Lay out a synthetic seed-directory subdirectory.\\\"\\\"\\\"\\n    sub = seed_root / extension_id\\n    sub.mkdir(parents=True, exist_ok=True)\\n    manifest = {\\n        \\\"id\\\": extension_id,\\n        \\\"version\\\": \\\"0.1.0\\\",\\n        \\\"name\\\": extension_id,\\n        \\\"lfx\\\": {\\\"compat\\\": [\\\"1\\\"]},\\n        \\\"bundles\\\": [{\\\"name\\\": bundle_name, \\\"path\\\": \\\"components\\\"}],\\n    }\\n    return make_extension(sub, manifest=manifest)\\n\\n\\ndef test_seed_default_absent_is_silent_no_op(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Mode A: $LANGFLOW_SEED_DIR unset and the default doesn't exist -> [].\\\"\\\"\\\"\\n    results = load_seed_extensions(seed_dir_env=\\\"\\\", default_seed_dir=tmp_path / \\\"does-not-exist\\\")\\n    assert results == []\\n\\n\\ndef test_seed_directory_loads_each_subdirectory(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Two subdirectories under the seed root each load at @official.\\\"\\\"\\\"\\n    seed_root = tmp_path / \\\"bundles\\\"\\n    seed_root.mkdir()\\n    _seed_subdir(seed_root, \\\"lfx-alpha\\\", bundle_name=\\\"alpha\\\")\\n    _seed_subdir(seed_root, \\\"lfx-bravo\\\", bundle_name=\\\"bravo\\\")\\n\\n    results = load_seed_extensions(seed_dir_env=str(seed_root), default_seed_dir=None)\\n    by_bundle = {r.bundle: r for r in results if r.bundle}\\n    assert set(by_bundle) == {\\\"alpha\\\", \\\"bravo\\\"}\\n    for bundle, result in by_bundle.items():\\n        assert result.ok, [e.code for e in result.errors]\\n        assert result.slot == SLOT_OFFICIAL\\n        # Seed records carry no distribution -- they are filesystem-resident.\\n        assert result.distribution is None\\n        # Components inherit the slot/bundle.\\n        for comp in result.components:\\n            assert comp.slot == SLOT_OFFICIAL\\n            assert comp.bundle == bundle\\n            assert comp.distribution is None\\n\\n\\ndef test_seed_skips_subdirectories_without_a_manifest(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Operators stage non-extension content alongside bundles -> silent skip.\\\"\\\"\\\"\\n    seed_root = tmp_path / \\\"bundles\\\"\\n    seed_root.mkdir()\\n    _seed_subdir(seed_root, \\\"lfx-alpha\\\")\\n    # README, scripts, etc.\\n    (seed_root / \\\"README.md\\\").write_text(\\\"not an extension\\\")\\n    notes = seed_root / \\\"operator-notes\\\"\\n    notes.mkdir()\\n    (notes / \\\"todo.txt\\\").write_text(\\\"ignore me\\\")\\n\\n    results = load_seed_extensions(seed_dir_env=str(seed_root), default_seed_dir=None)\\n    bundles = [r.bundle for r in results if r.bundle]\\n    assert bundles == [\\\"pilot\\\"]\\n\\n\\ndef test_seed_directory_missing_emits_typed_error(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"An explicitly configured seed root that is absent surfaces an error.\\\"\\\"\\\"\\n    missing = tmp_path / \\\"no-such-dir\\\"\\n    results = load_seed_extensions(seed_dir_env=str(missing), default_seed_dir=None)\\n\\n    sentinel_errors = [err for r in results for err in r.errors]\\n    codes = {err.code for err in sentinel_errors}\\n    assert \\\"seed-directory-not-found\\\" in codes\\n    # No component records came back: the directory was empty.\\n    assert all(not r.components for r in results)\\n\\n\\ndef test_seed_invalid_manifest_emits_typed_error(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A subdirectory with a malformed manifest surfaces a typed load error.\\\"\\\"\\\"\\n    seed_root = tmp_path / \\\"bundles\\\"\\n    seed_root.mkdir()\\n    bad = seed_root / \\\"lfx-broken\\\"\\n    bad.mkdir()\\n    (bad / \\\"extension.json\\\").write_text(\\\"{not-valid-json\\\")\\n\\n    results = load_seed_extensions(seed_dir_env=str(seed_root), default_seed_dir=None)\\n    codes = {err.code for r in results for err in r.errors}\\n    # Either the discovery layer reports manifest-invalid, or load_extension\\n    # does -- both are acceptable; we just want it surfaced as a typed error.\\n    assert codes & {\\\"manifest-invalid\\\", \\\"manifest-not-found\\\"}\\n\\n\\ndef test_seed_results_are_deterministic(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Order is sorted by subdirectory path so events emit deterministically.\\\"\\\"\\\"\\n    seed_root = tmp_path / \\\"bundles\\\"\\n    seed_root.mkdir()\\n    _seed_subdir(seed_root, \\\"lfx-charlie\\\", bundle_name=\\\"charlie\\\")\\n    _seed_subdir(seed_root, \\\"lfx-alpha\\\", bundle_name=\\\"alpha\\\")\\n    _seed_subdir(seed_root, \\\"lfx-bravo\\\", bundle_name=\\\"bravo\\\")\\n\\n    results = load_seed_extensions(seed_dir_env=str(seed_root), default_seed_dir=None)\\n    bundles = [r.bundle for r in results if r.bundle]\\n    assert bundles == [\\\"alpha\\\", \\\"bravo\\\", \\\"charlie\\\"]\\n\\n\\ndef test_pathsep_split_loads_multiple_seed_roots(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"``$LANGFLOW_SEED_DIR`` is pathsep-separated for multiple roots.\\\"\\\"\\\"\\n    root_a = tmp_path / \\\"a\\\"\\n    root_b = tmp_path / \\\"b\\\"\\n    root_a.mkdir()\\n    root_b.mkdir()\\n    _seed_subdir(root_a, \\\"lfx-a\\\", bundle_name=\\\"aa\\\")\\n    _seed_subdir(root_b, \\\"lfx-b\\\", bundle_name=\\\"bb\\\")\\n\\n    env = os.pathsep.join([str(root_a), str(root_b)])\\n    results = load_seed_extensions(seed_dir_env=env, default_seed_dir=None)\\n    bundles = sorted(r.bundle for r in results if r.bundle)\\n    assert bundles == [\\\"aa\\\", \\\"bb\\\"]\\n\\n\\ndef test_default_seed_dir_used_when_env_unset(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"An unset env var falls back to ``default_seed_dir``.\\\"\\\"\\\"\\n    seed_root = tmp_path / \\\"default-bundles\\\"\\n    seed_root.mkdir()\\n    _seed_subdir(seed_root, \\\"lfx-default\\\", bundle_name=\\\"defaultbundle\\\")\\n\\n    results = load_seed_extensions(seed_dir_env=\\\"\\\", default_seed_dir=seed_root)\\n    bundles = [r.bundle for r in results if r.bundle]\\n    assert bundles == [\\\"defaultbundle\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/loader/test_plugins.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8d0f67d3e7ab013463a372283cbec26d0509561b95fdd384e8f9714243548211\",\"content\":\"\\\"\\\"\\\"Tests for manifest-first precedence over ``langflow.plugins``.\\n\\nCovers the AC item: \\\"package with manifest + legacy component entry-point\\nloads its components ONCE via the manifest, not twice.\\\"  We model \\\"loaded\\nonce\\\" by partitioning the entry points; the manifest-shipping distribution\\nends up in ``skipped`` while non-component entry-points on a manifest-less\\ndistribution stay in ``kept``.\\n\\nAlso covers the supporting primitives:\\n    - PEP-503 distribution-name canonicalization\\n    - ``installed_extension_roots`` skips distributions without a manifest\\n    - ``installed_extension_roots`` survives ``files=None``\\n    - ``manifest_owning_distributions`` is the canonical-name set\\n    - ``filter_plugin_entry_points`` is defensive on ``dist=None`` and\\n      consults the real environment when ``skip`` is omitted\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom importlib import metadata as importlib_metadata\\nfrom pathlib import Path\\n\\nfrom lfx.extension import (\\n    filter_component_entry_points,\\n    filter_plugin_entry_points,\\n    installed_extension_roots,\\n    manifest_owning_distributions,\\n)\\nfrom lfx.extension.loader._plugins import canonicalize_distribution\\n\\nfrom .conftest import (\\n    FakeDist,\\n    FakeEntryPoint,\\n    make_installed_extension,\\n    make_installed_pyproject_extension,\\n    make_installed_pyproject_malformed_extension,\\n    make_installed_pyproject_no_extension,\\n)\\n\\n\\nclass _FakePluginComponent:\\n    \\\"\\\"\\\"Base class whose name ends in 'Component' -- triggers loader heuristic.\\\"\\\"\\\"\\n\\n\\nclass _LegacyPluginComponent(_FakePluginComponent):\\n    \\\"\\\"\\\"Stands in for a legacy component-style entry-point value.\\n\\n    Inherits from a base whose name ends in 'Component' so\\n    ``is_component_subclass`` recognizes it as a component class without\\n    requiring the real heavyweight Component machinery.\\n    \\\"\\\"\\\"\\n\\n\\ndef _route_register(_app):\\n    \\\"\\\"\\\"Stands in for a non-component entry-point value (route registrar).\\\"\\\"\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# installed_extension_roots\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_finds_manifest_shipping_distribution(tmp_path: Path) -> None:\\n    dist = make_installed_extension(tmp_path, \\\"lfx-pilot\\\")\\n    roots = installed_extension_roots(distributions=[dist])\\n    assert \\\"lfx-pilot\\\" in roots\\n    assert (roots[\\\"lfx-pilot\\\"] / \\\"extension.json\\\").is_file()\\n\\n\\ndef test_canonicalizes_distribution_name(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"PEP-503: ``Lfx_Pilot`` and ``lfx-pilot`` are the same distribution.\\\"\\\"\\\"\\n    dist = make_installed_extension(tmp_path, \\\"lfx-pilot\\\")\\n    # Override the metadata Name to test the canonicalize path.\\n    dist._name = \\\"LFX_Pilot\\\"\\n    roots = installed_extension_roots(distributions=[dist])\\n    assert list(roots) == [\\\"lfx-pilot\\\"]\\n\\n\\ndef test_ignores_distributions_without_manifest(tmp_path: Path) -> None:\\n    plain_dist = FakeDist(\\\"plain-pkg\\\", tmp_path, files=[Path(\\\"plain_pkg/__init__.py\\\")])\\n    roots = installed_extension_roots(distributions=[plain_dist])\\n    assert roots == {}\\n\\n\\ndef test_handles_files_none(tmp_path: Path) -> None:\\n    dist = FakeDist(\\\"orphan\\\", tmp_path, files=None)\\n    roots = installed_extension_roots(distributions=[dist])\\n    assert roots == {}\\n\\n\\n# ---------------------------------------------------------------------------\\n# pyproject.toml manifest discovery (the AC's second supported manifest form)\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_finds_pyproject_only_distribution(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A distribution shipping pyproject.toml with [tool.langflow.extension] is found.\\\"\\\"\\\"\\n    dist = make_installed_pyproject_extension(tmp_path, \\\"lfx-pyproject\\\")\\n    roots = installed_extension_roots(distributions=[dist])\\n    assert \\\"lfx-pyproject\\\" in roots\\n    assert (roots[\\\"lfx-pyproject\\\"] / \\\"pyproject.toml\\\").is_file()\\n\\n\\ndef test_pyproject_without_extension_section_is_ignored(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A pyproject.toml without [tool.langflow.extension] is NOT treated as a manifest.\\n\\n    Defensive: many regular packages ship pyproject.toml; we must only\\n    accept it as a manifest source when the section actually exists.\\n    \\\"\\\"\\\"\\n    dist = make_installed_pyproject_no_extension(tmp_path, \\\"plain-pyproject\\\")\\n    roots = installed_extension_roots(distributions=[dist])\\n    assert roots == {}\\n\\n\\ndef test_malformed_pyproject_section_surfaces_manifest_invalid(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A pyproject with [tool.langflow.extension] missing required fields surfaces manifest-invalid.\\n\\n    Detection MUST be presence-only: if the section exists but pydantic\\n    validation fails, the distribution is still discovered as a\\n    manifest-shipping Extension and ``load_installed_extensions`` produces\\n    a typed ``manifest-invalid`` :class:`LoadResult`. Conflating \\\"section\\n    absent\\\" with \\\"section malformed\\\" would silently drop the\\n    distribution, hiding the typo from operators and skipping the\\n    manifest-first suppression of legacy component entry-points.\\n    \\\"\\\"\\\"\\n    from lfx.extension import load_installed_extensions\\n\\n    dist = make_installed_pyproject_malformed_extension(tmp_path, \\\"lfx-bad-pyproject\\\")\\n    # Discovery must classify the distribution as manifest-shipping despite\\n    # the broken section, so manifest-first precedence still suppresses any\\n    # legacy entry-points it might have.\\n    owners = manifest_owning_distributions(distributions=[dist])\\n    assert \\\"lfx-bad-pyproject\\\" in owners\\n\\n    # And load_installed_extensions must produce a typed failure result, not\\n    # silently return an empty list.\\n    results = load_installed_extensions(distributions=[dist])\\n    assert len(results) == 1, f\\\"expected exactly one LoadResult, got {results}\\\"\\n    result = results[0]\\n    assert not result.ok\\n    codes = [e.code for e in result.errors]\\n    assert \\\"manifest-invalid\\\" in codes, codes\\n    assert result.distribution == \\\"lfx-bad-pyproject\\\"\\n    err = next(e for e in result.errors if e.code == \\\"manifest-invalid\\\")\\n    assert err.hint  # AC: fix-hint payload on failure\\n    assert err.ref_url\\n\\n\\ndef test_malformed_pyproject_section_suppresses_legacy_component_entry_point(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Manifest-first precedence applies even when the pyproject manifest is malformed.\\n\\n    If the section exists, the distribution is manifest-shipping by intent;\\n    its legacy ``langflow.plugins`` component entry-points must be\\n    suppressed regardless of whether the manifest itself validates --\\n    otherwise the AC's \\\"loaded once via manifest\\\" promise breaks for any\\n    pyproject author who typo'd a field.\\n    \\\"\\\"\\\"\\n    dist = make_installed_pyproject_malformed_extension(tmp_path, \\\"lfx-bad-pyproject\\\")\\n    component_ep = FakeEntryPoint(\\\"BadComp\\\", dist, loaded_value=_LegacyPluginComponent)\\n\\n    owners = manifest_owning_distributions(distributions=[dist])\\n    kept, skipped = filter_component_entry_points([component_ep], skip=owners)\\n    assert [ep.name for ep in skipped] == [\\\"BadComp\\\"]\\n    assert kept == []\\n\\n\\ndef test_extension_json_wins_over_pyproject(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"When both forms ship, extension.json wins (matches load_manifest order).\\\"\\\"\\\"\\n    pkg_dir = tmp_path / \\\"lfx-both\\\"\\n    pkg_dir.mkdir()\\n    manifest = {\\n        \\\"id\\\": \\\"lfx-both\\\",\\n        \\\"version\\\": \\\"1.0.0\\\",\\n        \\\"name\\\": \\\"lfx-both\\\",\\n        \\\"lfx\\\": {\\\"compat\\\": [\\\"1\\\"]},\\n        \\\"bundles\\\": [{\\\"name\\\": \\\"both\\\", \\\"path\\\": \\\"components\\\"}],\\n    }\\n    (pkg_dir / \\\"extension.json\\\").write_text(__import__(\\\"json\\\").dumps(manifest), encoding=\\\"utf-8\\\")\\n    (pkg_dir / \\\"pyproject.toml\\\").write_text(\\n        '[project]\\\\nname = \\\"lfx-both\\\"\\\\n[tool.langflow.extension]\\\\nid = \\\"lfx-both\\\"\\\\n',\\n        encoding=\\\"utf-8\\\",\\n    )\\n    dist = FakeDist(\\n        name=\\\"lfx-both\\\",\\n        root=tmp_path,\\n        files=[Path(\\\"lfx-both\\\") / \\\"extension.json\\\", Path(\\\"lfx-both\\\") / \\\"pyproject.toml\\\"],\\n    )\\n    roots = installed_extension_roots(distributions=[dist])\\n    # Both forms point at the same root directory, but the manifest path\\n    # used for resolution should be the JSON file.\\n    assert \\\"lfx-both\\\" in roots\\n    assert (roots[\\\"lfx-both\\\"] / \\\"extension.json\\\").is_file()\\n\\n\\ndef test_pyproject_only_extension_loads_at_official_slot(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"End-to-end: a pyproject-only Extension is discovered by load_installed_extensions.\\n\\n    Without this path the AC's \\\"extension.json or [tool.langflow.extension]\\\"\\n    wording is half-implemented.\\n    \\\"\\\"\\\"\\n    from lfx.extension import load_installed_extensions\\n\\n    dist = make_installed_pyproject_extension(tmp_path, \\\"lfx-pyproject\\\")\\n    # Populate the bundle directory referenced by the pyproject manifest.\\n    bundle_dir = tmp_path / \\\"lfx-pyproject\\\" / \\\"components\\\"\\n    bundle_dir.mkdir(parents=True)\\n    (bundle_dir / \\\"thing.py\\\").write_text(\\n        \\\"class Component:\\\\n    pass\\\\nclass Thing(Component):\\\\n    pass\\\\n\\\",\\n        encoding=\\\"utf-8\\\",\\n    )\\n\\n    results = load_installed_extensions(distributions=[dist])\\n    assert len(results) == 1\\n    result = results[0]\\n    assert result.ok, [e.code for e in result.errors]\\n    assert result.distribution == \\\"lfx-pyproject\\\"\\n    assert result.extension_id == \\\"lfx-pyproject\\\"\\n    # Bundle name comes from the pyproject manifest section.\\n    assert result.bundle == \\\"lfx_pyproject\\\"\\n    assert result.components, \\\"pyproject-form Extension should yield components\\\"\\n\\n\\ndef test_pyproject_only_distribution_suppresses_legacy_component_entry_point(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Manifest-first precedence applies to pyproject-form Extensions too.\\n\\n    A legacy ``langflow.plugins`` component entry-point on a pyproject-form\\n    manifest-shipping distribution must be skipped exactly like the JSON\\n    form, otherwise the same-distribution double-registration the AC\\n    forbids would still occur.\\n    \\\"\\\"\\\"\\n    dist = make_installed_pyproject_extension(tmp_path, \\\"lfx-pyproject\\\")\\n    component_ep = FakeEntryPoint(\\\"PyComponent\\\", dist, loaded_value=_LegacyPluginComponent)\\n\\n    owners = manifest_owning_distributions(distributions=[dist])\\n    assert \\\"lfx-pyproject\\\" in owners\\n    kept, skipped = filter_component_entry_points([component_ep], skip=owners)\\n    assert [ep.name for ep in skipped] == [\\\"PyComponent\\\"]\\n    assert kept == []\\n\\n\\n# ---------------------------------------------------------------------------\\n# manifest_owning_distributions\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_owning_distributions_is_set_of_canonical_names(tmp_path: Path) -> None:\\n    dist = make_installed_extension(tmp_path, \\\"lfx-pilot\\\")\\n    other = FakeDist(\\\"plain-pkg\\\", tmp_path, files=[Path(\\\"plain_pkg/__init__.py\\\")])\\n    owners = manifest_owning_distributions(distributions=[dist, other])\\n    assert owners == frozenset({\\\"lfx-pilot\\\"})\\n\\n\\n# ---------------------------------------------------------------------------\\n# filter_plugin_entry_points (the AC test)\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_skips_manifest_shipping_distribution(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Manifest-first precedence: AC test for \\\"loaded once via manifest\\\".\\n\\n    Package with manifest + legacy component entry-point loads its\\n    components ONCE via the manifest, not twice.  We model \\\"loaded once\\\"\\n    by partitioning the entry points: the manifest's distribution lands in\\n    ``skipped`` (the loader's manifest path will register them), while\\n    non-component entry-points on a distribution that does NOT ship a\\n    manifest are kept (the legacy path still runs for those).\\n    \\\"\\\"\\\"\\n    manifest_dist = make_installed_extension(tmp_path, \\\"lfx-pilot\\\")\\n    other_dist = FakeDist(\\\"legacy-pkg\\\", tmp_path, files=[Path(\\\"legacy_pkg/__init__.py\\\")])\\n\\n    eps = [\\n        FakeEntryPoint(\\\"PilotComponent\\\", manifest_dist),  # should be skipped\\n        FakeEntryPoint(\\\"LegacyComponent\\\", other_dist),  # should be kept\\n    ]\\n    kept, skipped = filter_plugin_entry_points(\\n        eps,\\n        skip=manifest_owning_distributions(distributions=[manifest_dist, other_dist]),\\n    )\\n    assert [ep.name for ep in kept] == [\\\"LegacyComponent\\\"]\\n    assert [ep.name for ep in skipped] == [\\\"PilotComponent\\\"]\\n\\n\\ndef test_keeps_entry_points_without_distribution() -> None:\\n    \\\"\\\"\\\"Defensive: dist=None on an EntryPoint shouldn't drop it.\\n\\n    Some Python packagers expose entry points without a back-reference to\\n    the owning distribution (e.g. older wheel formats).  We err on the side\\n    of compatibility and keep those entry points.\\n    \\\"\\\"\\\"\\n    ep = FakeEntryPoint(\\\"Orphan\\\", None)\\n    kept, skipped = filter_plugin_entry_points([ep], skip=frozenset({\\\"lfx-pilot\\\"}))\\n    assert kept == [ep]\\n    assert skipped == []\\n\\n\\ndef test_uses_real_distributions_by_default(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"When ``skip`` is omitted, the filter consults the real environment.\\n\\n    The default value calls into ``importlib.metadata.distributions``;\\n    Langflow itself does not ship an extension manifest today, but if a\\n    transitive test-only dep ever does, ``kept`` / ``skipped`` could pick\\n    up additional entries we don't control. Robust assertion: pin the\\n    synthetic ``ep``'s placement (kept, not skipped) without requiring the\\n    output lists to be exactly ``[ep]`` / ``[]``.\\n    \\\"\\\"\\\"\\n    plain = FakeDist(\\\"plain-pkg\\\", tmp_path, files=[Path(\\\"plain_pkg/__init__.py\\\")])\\n    ep = FakeEntryPoint(\\\"PlainComponent\\\", plain)\\n    kept, skipped = filter_plugin_entry_points([ep])\\n    assert ep in kept\\n    assert ep not in skipped\\n\\n\\n# ---------------------------------------------------------------------------\\n# canonicalize_distribution\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_canonicalize_distribution_matches_pep503() -> None:\\n    assert canonicalize_distribution(\\\"Lfx-Pilot\\\") == \\\"lfx-pilot\\\"\\n    assert canonicalize_distribution(\\\"lfx_pilot\\\") == \\\"lfx-pilot\\\"\\n    assert canonicalize_distribution(\\\"LFX...PILOT\\\") == \\\"lfx-pilot\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Module-level smoke\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_importlib_metadata_distribution_is_available() -> None:\\n    \\\"\\\"\\\"Sanity check that the stdlib API the precedence helpers rely on exists.\\\"\\\"\\\"\\n    assert hasattr(importlib_metadata, \\\"distributions\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# filter_component_entry_points: type-aware (the runtime AC test)\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_component_filter_skips_only_component_entry_points(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"AC: same distribution exposes BOTH a component EP and a non-component EP.\\n\\n    Manifest-shipping distribution -> component EP gets skipped (manifest\\n    is the source of truth), but the non-component (route) EP keeps loading\\n    via the legacy path. This is the case the previous reviewer flagged as\\n    missing.\\n    \\\"\\\"\\\"\\n    manifest_dist = make_installed_extension(tmp_path, \\\"lfx-pilot\\\")\\n    component_ep = FakeEntryPoint(\\\"PilotComponent\\\", manifest_dist, loaded_value=_LegacyPluginComponent)\\n    route_ep = FakeEntryPoint(\\\"pilot_routes\\\", manifest_dist, loaded_value=_route_register)\\n\\n    kept, skipped = filter_component_entry_points(\\n        [component_ep, route_ep],\\n        skip=manifest_owning_distributions(distributions=[manifest_dist]),\\n    )\\n    assert [ep.name for ep in kept] == [\\\"pilot_routes\\\"]\\n    assert [ep.name for ep in skipped] == [\\\"PilotComponent\\\"]\\n\\n\\ndef test_component_filter_keeps_components_on_non_manifest_distribution(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A component EP on a distribution that does NOT ship a manifest stays kept.\\n\\n    The legacy ``langflow.plugins`` path is still the registration channel\\n    for those distributions; filtering them would silently drop them.\\n    \\\"\\\"\\\"\\n    other_dist = FakeDist(\\\"legacy-pkg\\\", tmp_path, files=[Path(\\\"legacy_pkg/__init__.py\\\")])\\n    component_ep = FakeEntryPoint(\\\"LegacyComponent\\\", other_dist, loaded_value=_LegacyPluginComponent)\\n    kept, skipped = filter_component_entry_points([component_ep], skip=frozenset())\\n    assert [ep.name for ep in kept] == [\\\"LegacyComponent\\\"]\\n    assert skipped == []\\n\\n\\ndef test_component_filter_handles_unloadable_entry_point(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Defensive: an entry-point whose load() raises is treated as non-component.\\n\\n    The resulting partition keeps it (so the legacy loader can decide what\\n    to do), rather than swallowing it as if it were component.\\n    \\\"\\\"\\\"\\n\\n    class _ExplodingEP(FakeEntryPoint):\\n        def load(self) -> object:\\n            msg = \\\"boom\\\"\\n            raise RuntimeError(msg)\\n\\n    manifest_dist = make_installed_extension(tmp_path, \\\"lfx-pilot\\\")\\n    bad_ep = _ExplodingEP(\\\"Boom\\\", manifest_dist, loaded_value=None)\\n    kept, skipped = filter_component_entry_points(\\n        [bad_ep],\\n        skip=manifest_owning_distributions(distributions=[manifest_dist]),\\n    )\\n    assert [ep.name for ep in kept] == [\\\"Boom\\\"]\\n    assert skipped == []\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/loader/test_types.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9751c9b887ba7d24ffb0ff6da3e2813859cf01fe8017b600bd7f989cba58eeef\",\"content\":\"\\\"\\\"\\\"Tests for the loader's public dataclasses.\\n\\n``LoadedComponent`` and ``LoadResult`` are the values the rest of the\\nLangflow stack consumes (events pipeline, registry, future reload).\\nThese tests pin their shape and behavior independently of the orchestrator\\nso a future refactor can move the dataclass code without breaking\\ndownstream consumers.\\n\\nAlso covers the loader-specific error-code registration invariant: every\\nloader code that the orchestrator can emit must be in ``ERROR_CODES``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom pathlib import Path\\n\\nfrom lfx.extension import (\\n    SLOT_OFFICIAL,\\n    LoadedComponent,\\n    LoadResult,\\n)\\nfrom lfx.extension.errors import ERROR_CODES\\n\\n# Loader-specific codes the orchestrator / inline-bundle path can emit.\\n# Keep this list in sync with the producer modules; if a code disappears\\n# from the registry but stays here (or vice versa), the test below fails.\\nLOADER_CODES = frozenset(\\n    {\\n        \\\"module-import-failed\\\",\\n        \\\"optional-dependency-missing\\\",\\n        \\\"duplicate-component-name\\\",\\n        \\\"duplicate-inline-bundle\\\",\\n        \\\"inline-bundle-name-invalid\\\",\\n    }\\n)\\n\\n\\n# ---------------------------------------------------------------------------\\n# LoadResult shape\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_load_result_default_is_ok() -> None:\\n    result = LoadResult()\\n    assert result.ok\\n    assert bool(result) is True\\n    assert result.components == []\\n\\n\\n# ---------------------------------------------------------------------------\\n# LoadedComponent shape\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_loaded_component_namespaced_id_format() -> None:\\n    class Dummy:\\n        pass\\n\\n    component = LoadedComponent(\\n        extension_id=\\\"lfx-pilot\\\",\\n        extension_version=\\\"1.2.3\\\",\\n        bundle=\\\"pilot\\\",\\n        class_name=\\\"PilotThing\\\",\\n        slot=SLOT_OFFICIAL,\\n        klass=Dummy,\\n        module_name=\\\"_lfx_ext.official.pilot.thing\\\",\\n        file_path=Path(\\\"/tmp/thing.py\\\"),\\n    )\\n    assert component.namespaced_id == \\\"ext:pilot:PilotThing@official\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Error-code registry parity\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_all_loader_error_codes_are_in_registry() -> None:\\n    missing = LOADER_CODES - ERROR_CODES\\n    assert not missing, f\\\"Loader code(s) missing from ERROR_CODES: {sorted(missing)}\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/migration/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/migration/test_append_only_script.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cd7b63c9aa565110caf1ae280a980cfebd1f318bea27f0bcc6ac825fe6365980\",\"content\":\"\\\"\\\"\\\"Smoke tests for scripts/migrate/check_migration_append_only.py.\\n\\nWe exercise the script as a black-box subprocess so the test catches\\nSystemExit / argparse drift the same way CI would.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nimport subprocess\\nimport sys\\nfrom pathlib import Path\\n\\nimport pytest\\n\\nREPO_ROOT = Path(__file__).resolve().parents[6]\\nSCRIPT = REPO_ROOT / \\\"scripts\\\" / \\\"migrate\\\" / \\\"check_migration_append_only.py\\\"\\n\\n\\ndef _write_table(\\n    path: Path,\\n    entries: list[dict],\\n    *,\\n    ambiguous_bare_names: list[dict] | None = None,\\n) -> None:\\n    body: dict = {\\\"schema_version\\\": 1, \\\"entries\\\": entries}\\n    if ambiguous_bare_names is not None:\\n        body[\\\"ambiguous_bare_names\\\"] = ambiguous_bare_names\\n    path.write_text(json.dumps(body, indent=2), encoding=\\\"utf-8\\\")\\n\\n\\ndef _run(*args: str) -> subprocess.CompletedProcess[str]:\\n    return subprocess.run(  # noqa: S603 - test harness invoking our own script\\n        [sys.executable, str(SCRIPT), *args],\\n        check=False,\\n        capture_output=True,\\n        text=True,\\n        cwd=REPO_ROOT,\\n    )\\n\\n\\n@pytest.mark.unit\\ndef test_script_exists() -> None:\\n    assert SCRIPT.is_file(), f\\\"missing CI guard script at {SCRIPT}\\\"\\n\\n\\n@pytest.mark.unit\\ndef test_no_baseline_passes(tmp_path: Path) -> None:\\n    current = tmp_path / \\\"current.json\\\"\\n    _write_table(current, [])\\n    missing = tmp_path / \\\"does-not-exist.json\\\"\\n    proc = _run(\\\"--baseline\\\", str(missing), \\\"--current\\\", str(current))\\n    # Script exits 2 on missing baseline file; that's a CI usage error,\\n    # not an append-only violation.\\n    assert proc.returncode == 2\\n\\n\\n@pytest.mark.unit\\ndef test_pure_addition_passes(tmp_path: Path) -> None:\\n    baseline = tmp_path / \\\"baseline.json\\\"\\n    current = tmp_path / \\\"current.json\\\"\\n    _write_table(\\n        baseline,\\n        [\\n            {\\n                \\\"bare_class_name\\\": \\\"Foo\\\",\\n                \\\"target\\\": \\\"ext:a:Foo@official\\\",\\n                \\\"added_in\\\": \\\"1.10.0\\\",\\n            }\\n        ],\\n    )\\n    _write_table(\\n        current,\\n        [\\n            {\\n                \\\"bare_class_name\\\": \\\"Foo\\\",\\n                \\\"target\\\": \\\"ext:a:Foo@official\\\",\\n                \\\"added_in\\\": \\\"1.10.0\\\",\\n            },\\n            {\\n                \\\"bare_class_name\\\": \\\"Bar\\\",\\n                \\\"target\\\": \\\"ext:b:Bar@official\\\",\\n                \\\"added_in\\\": \\\"1.11.0\\\",\\n            },\\n        ],\\n    )\\n    proc = _run(\\\"--baseline\\\", str(baseline), \\\"--current\\\", str(current))\\n    assert proc.returncode == 0, proc.stderr\\n\\n\\n@pytest.mark.unit\\ndef test_removal_fails(tmp_path: Path) -> None:\\n    baseline = tmp_path / \\\"baseline.json\\\"\\n    current = tmp_path / \\\"current.json\\\"\\n    _write_table(\\n        baseline,\\n        [\\n            {\\n                \\\"bare_class_name\\\": \\\"Foo\\\",\\n                \\\"target\\\": \\\"ext:a:Foo@official\\\",\\n                \\\"added_in\\\": \\\"1.10.0\\\",\\n            }\\n        ],\\n    )\\n    _write_table(current, [])\\n    proc = _run(\\\"--baseline\\\", str(baseline), \\\"--current\\\", str(current))\\n    assert proc.returncode == 1\\n    assert \\\"entry removed\\\" in proc.stderr\\n\\n\\n@pytest.mark.unit\\ndef test_target_mutation_fails(tmp_path: Path) -> None:\\n    baseline = tmp_path / \\\"baseline.json\\\"\\n    current = tmp_path / \\\"current.json\\\"\\n    _write_table(\\n        baseline,\\n        [\\n            {\\n                \\\"bare_class_name\\\": \\\"Foo\\\",\\n                \\\"target\\\": \\\"ext:a:Foo@official\\\",\\n                \\\"added_in\\\": \\\"1.10.0\\\",\\n            }\\n        ],\\n    )\\n    _write_table(\\n        current,\\n        [\\n            {\\n                \\\"bare_class_name\\\": \\\"Foo\\\",\\n                \\\"target\\\": \\\"ext:b:Foo@official\\\",  # changed bundle\\n                \\\"added_in\\\": \\\"1.10.0\\\",\\n            }\\n        ],\\n    )\\n    proc = _run(\\\"--baseline\\\", str(baseline), \\\"--current\\\", str(current))\\n    assert proc.returncode == 1\\n    assert \\\"target changed\\\" in proc.stderr\\n\\n\\n@pytest.mark.unit\\ndef test_reordering_is_allowed(tmp_path: Path) -> None:\\n    baseline = tmp_path / \\\"baseline.json\\\"\\n    current = tmp_path / \\\"current.json\\\"\\n    a = {\\\"bare_class_name\\\": \\\"A\\\", \\\"target\\\": \\\"ext:x:A@official\\\", \\\"added_in\\\": \\\"1.10.0\\\"}\\n    b = {\\\"bare_class_name\\\": \\\"B\\\", \\\"target\\\": \\\"ext:x:B@official\\\", \\\"added_in\\\": \\\"1.10.0\\\"}\\n    _write_table(baseline, [a, b])\\n    _write_table(current, [b, a])  # reordered\\n    proc = _run(\\\"--baseline\\\", str(baseline), \\\"--current\\\", str(current))\\n    assert proc.returncode == 0, proc.stderr\\n\\n\\n# ---------------------------------------------------------------------------\\n# ambiguous_bare_names append-only invariants\\n# ---------------------------------------------------------------------------\\n\\n_AMBIG_MERGE = {\\n    \\\"name\\\": \\\"MergeDataComponent\\\",\\n    \\\"candidates\\\": [\\n        \\\"ext:processing:MergeDataComponent@official\\\",\\n        \\\"ext:deactivated:MergeDataComponent@official\\\",\\n    ],\\n    \\\"added_in\\\": \\\"1.10.0\\\",\\n}\\n\\n\\n@pytest.mark.unit\\ndef test_ambiguous_marker_addition_passes(tmp_path: Path) -> None:\\n    baseline = tmp_path / \\\"baseline.json\\\"\\n    current = tmp_path / \\\"current.json\\\"\\n    _write_table(baseline, [], ambiguous_bare_names=[])\\n    _write_table(current, [], ambiguous_bare_names=[_AMBIG_MERGE])\\n    proc = _run(\\\"--baseline\\\", str(baseline), \\\"--current\\\", str(current))\\n    assert proc.returncode == 0, proc.stderr\\n\\n\\n@pytest.mark.unit\\ndef test_ambiguous_marker_removal_fails(tmp_path: Path) -> None:\\n    baseline = tmp_path / \\\"baseline.json\\\"\\n    current = tmp_path / \\\"current.json\\\"\\n    _write_table(baseline, [], ambiguous_bare_names=[_AMBIG_MERGE])\\n    _write_table(current, [], ambiguous_bare_names=[])\\n    proc = _run(\\\"--baseline\\\", str(baseline), \\\"--current\\\", str(current))\\n    assert proc.returncode == 1\\n    assert \\\"ambiguous_bare_names marker removed\\\" in proc.stderr\\n    assert \\\"MergeDataComponent\\\" in proc.stderr\\n\\n\\n@pytest.mark.unit\\ndef test_ambiguous_marker_candidates_shrunk_fails(tmp_path: Path) -> None:\\n    baseline = tmp_path / \\\"baseline.json\\\"\\n    current = tmp_path / \\\"current.json\\\"\\n    shrunk = {\\n        \\\"name\\\": \\\"MergeDataComponent\\\",\\n        \\\"candidates\\\": [\\\"ext:processing:MergeDataComponent@official\\\"],  # one candidate dropped\\n        \\\"added_in\\\": \\\"1.10.0\\\",\\n    }\\n    _write_table(baseline, [], ambiguous_bare_names=[_AMBIG_MERGE])\\n    _write_table(current, [], ambiguous_bare_names=[shrunk])\\n    proc = _run(\\\"--baseline\\\", str(baseline), \\\"--current\\\", str(current))\\n    assert proc.returncode == 1\\n    assert \\\"candidates shrunk\\\" in proc.stderr\\n    assert \\\"ext:deactivated:MergeDataComponent@official\\\" in proc.stderr\\n\\n\\n@pytest.mark.unit\\ndef test_ambiguous_marker_candidate_addition_passes(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Adding a new candidate to an existing marker is allowed (set grows).\\\"\\\"\\\"\\n    baseline = tmp_path / \\\"baseline.json\\\"\\n    current = tmp_path / \\\"current.json\\\"\\n    grown = {\\n        \\\"name\\\": \\\"MergeDataComponent\\\",\\n        \\\"candidates\\\": [\\n            \\\"ext:processing:MergeDataComponent@official\\\",\\n            \\\"ext:deactivated:MergeDataComponent@official\\\",\\n            \\\"ext:newbundle:MergeDataComponent@official\\\",\\n        ],\\n        \\\"added_in\\\": \\\"1.10.0\\\",\\n    }\\n    _write_table(baseline, [], ambiguous_bare_names=[_AMBIG_MERGE])\\n    _write_table(current, [], ambiguous_bare_names=[grown])\\n    proc = _run(\\\"--baseline\\\", str(baseline), \\\"--current\\\", str(current))\\n    assert proc.returncode == 0, proc.stderr\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/migration/test_bare_names_script.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c1f95a35a51658bf928c5baa71c5760b14c456c46e68e96316bf524e597c0df1\",\"content\":\"\\\"\\\"\\\"Smoke tests for scripts/migrate/check_bare_names.py.\\n\\nExercise the script as a black-box subprocess so the test catches\\nSystemExit / argparse drift the same way CI would.  Uses a synthetic\\ncomponents root so we don't depend on the real lfx component tree.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nimport subprocess\\nimport sys\\nfrom pathlib import Path\\n\\nimport pytest\\n\\nREPO_ROOT = Path(__file__).resolve().parents[6]\\nSCRIPT = REPO_ROOT / \\\"scripts\\\" / \\\"migrate\\\" / \\\"check_bare_names.py\\\"\\n\\n\\ndef _write_table(path: Path, entries: list[dict]) -> None:\\n    path.write_text(\\n        json.dumps({\\\"schema_version\\\": 1, \\\"entries\\\": entries}, indent=2),\\n        encoding=\\\"utf-8\\\",\\n    )\\n\\n\\ndef _make_component(root: Path, bundle: str, filename: str, class_name: str) -> Path:\\n    bundle_dir = root / bundle\\n    bundle_dir.mkdir(parents=True, exist_ok=True)\\n    file_path = bundle_dir / filename\\n    file_path.write_text(\\n        f\\\"class {class_name}:\\\\n    pass\\\\n\\\",\\n        encoding=\\\"utf-8\\\",\\n    )\\n    return file_path\\n\\n\\ndef _run(*args: str) -> subprocess.CompletedProcess[str]:\\n    return subprocess.run(  # noqa: S603 - test harness invoking our own script\\n        [sys.executable, str(SCRIPT), *args],\\n        check=False,\\n        capture_output=True,\\n        text=True,\\n        cwd=REPO_ROOT,\\n    )\\n\\n\\n@pytest.mark.unit\\ndef test_script_exists() -> None:\\n    assert SCRIPT.is_file(), f\\\"missing CI guard script at {SCRIPT}\\\"\\n\\n\\n@pytest.mark.unit\\ndef test_empty_table_passes(tmp_path: Path) -> None:\\n    table = tmp_path / \\\"table.json\\\"\\n    _write_table(table, [])\\n    proc = _run(\\\"--table\\\", str(table), \\\"--components-root\\\", str(tmp_path))\\n    assert proc.returncode == 0, proc.stderr\\n\\n\\n@pytest.mark.unit\\ndef test_table_without_bare_names_passes(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Entries that only declare import_path or legacy_slot are not bare-name guarded.\\\"\\\"\\\"\\n    table = tmp_path / \\\"table.json\\\"\\n    _write_table(\\n        table,\\n        [\\n            {\\n                \\\"import_path\\\": \\\"lfx.components.foo.Foo\\\",\\n                \\\"target\\\": \\\"ext:foo:Foo@official\\\",\\n                \\\"added_in\\\": \\\"1.10.0\\\",\\n            },\\n        ],\\n    )\\n    proc = _run(\\\"--table\\\", str(table), \\\"--components-root\\\", str(tmp_path))\\n    assert proc.returncode == 0, proc.stderr\\n\\n\\n@pytest.mark.unit\\ndef test_unique_bare_name_passes(tmp_path: Path) -> None:\\n    components = tmp_path / \\\"components\\\"\\n    _make_component(components, \\\"duckduckgo\\\", \\\"search.py\\\", \\\"DuckDuckGoSearchComponent\\\")\\n\\n    table = tmp_path / \\\"table.json\\\"\\n    _write_table(\\n        table,\\n        [\\n            {\\n                \\\"bare_class_name\\\": \\\"DuckDuckGoSearchComponent\\\",\\n                \\\"target\\\": \\\"ext:duckduckgo:DuckDuckGoSearchComponent@official\\\",\\n                \\\"added_in\\\": \\\"1.10.0\\\",\\n            },\\n        ],\\n    )\\n\\n    proc = _run(\\\"--table\\\", str(table), \\\"--components-root\\\", str(components))\\n    assert proc.returncode == 0, proc.stderr\\n\\n\\n@pytest.mark.unit\\ndef test_ambiguous_bare_name_fails(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A class declared in two bundle folders must not have a bare-name entry.\\n\\n    This is the canonical regression case: MergeDataComponent / SplitTextComponent /\\n    SubFlowComponent all live in both ``processing/`` and ``deactivated/`` in\\n    the real tree.  Adding a bare-name entry for any of them would let saved\\n    flows silently load into the wrong bundle.\\n    \\\"\\\"\\\"\\n    components = tmp_path / \\\"components\\\"\\n    _make_component(components, \\\"processing\\\", \\\"merge_data.py\\\", \\\"MergeDataComponent\\\")\\n    _make_component(components, \\\"deactivated\\\", \\\"merge_data.py\\\", \\\"MergeDataComponent\\\")\\n\\n    table = tmp_path / \\\"table.json\\\"\\n    _write_table(\\n        table,\\n        [\\n            {\\n                \\\"bare_class_name\\\": \\\"MergeDataComponent\\\",\\n                \\\"target\\\": \\\"ext:processing:MergeDataComponent@official\\\",\\n                \\\"added_in\\\": \\\"1.10.0\\\",\\n            },\\n        ],\\n    )\\n\\n    proc = _run(\\\"--table\\\", str(table), \\\"--components-root\\\", str(components))\\n    assert proc.returncode == 1, proc.stdout + proc.stderr\\n    assert \\\"ambiguous\\\" in proc.stderr.lower()\\n    assert \\\"MergeDataComponent\\\" in proc.stderr\\n    # The error must name BOTH offending bundles so the engineer can resolve it.\\n    assert \\\"processing\\\" in proc.stderr\\n    assert \\\"deactivated\\\" in proc.stderr\\n\\n\\n@pytest.mark.unit\\ndef test_unknown_bare_name_fails(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A bare-name entry referring to a class no bundle declares is a typo or stale.\\\"\\\"\\\"\\n    components = tmp_path / \\\"components\\\"\\n    _make_component(components, \\\"duckduckgo\\\", \\\"search.py\\\", \\\"DuckDuckGoSearchComponent\\\")\\n\\n    table = tmp_path / \\\"table.json\\\"\\n    _write_table(\\n        table,\\n        [\\n            {\\n                \\\"bare_class_name\\\": \\\"TypoComponent\\\",\\n                \\\"target\\\": \\\"ext:duckduckgo:TypoComponent@official\\\",\\n                \\\"added_in\\\": \\\"1.10.0\\\",\\n            },\\n        ],\\n    )\\n\\n    proc = _run(\\\"--table\\\", str(table), \\\"--components-root\\\", str(components))\\n    assert proc.returncode == 1\\n    assert \\\"TypoComponent\\\" in proc.stderr\\n    assert \\\"no class named\\\" in proc.stderr.lower()\\n\\n\\n@pytest.mark.unit\\ndef test_dunder_init_files_not_counted(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A class re-exported from __init__.py must not double-count the bundle.\\n\\n    Without this guard, every package that re-exports its component would\\n    show up as TWO bundle folders for the same class name, breaking the\\n    uniqueness check.\\n    \\\"\\\"\\\"\\n    components = tmp_path / \\\"components\\\"\\n    _make_component(components, \\\"duckduckgo\\\", \\\"search.py\\\", \\\"DuckDuckGoSearchComponent\\\")\\n    # __init__ that re-exports the class via a class declaration would falsely\\n    # double-register it.  The script skips __init__.py entirely.\\n    (components / \\\"duckduckgo\\\" / \\\"__init__.py\\\").write_text(\\\"class DuckDuckGoSearchComponent: pass\\\\n\\\", encoding=\\\"utf-8\\\")\\n\\n    table = tmp_path / \\\"table.json\\\"\\n    _write_table(\\n        table,\\n        [\\n            {\\n                \\\"bare_class_name\\\": \\\"DuckDuckGoSearchComponent\\\",\\n                \\\"target\\\": \\\"ext:duckduckgo:DuckDuckGoSearchComponent@official\\\",\\n                \\\"added_in\\\": \\\"1.10.0\\\",\\n            },\\n        ],\\n    )\\n\\n    proc = _run(\\\"--table\\\", str(table), \\\"--components-root\\\", str(components))\\n    assert proc.returncode == 0, proc.stderr\\n\\n\\n@pytest.mark.unit\\ndef test_missing_table_is_usage_error(tmp_path: Path) -> None:\\n    proc = _run(\\\"--table\\\", str(tmp_path / \\\"does-not-exist.json\\\"))\\n    assert proc.returncode == 2\\n    assert \\\"not found\\\" in proc.stderr.lower()\\n\\n\\n@pytest.mark.unit\\ndef test_invalid_table_json_is_usage_error(tmp_path: Path) -> None:\\n    table = tmp_path / \\\"table.json\\\"\\n    table.write_text(\\\"not valid json{\\\", encoding=\\\"utf-8\\\")\\n    proc = _run(\\\"--table\\\", str(table))\\n    assert proc.returncode == 2\\n    assert \\\"json\\\" in proc.stderr.lower()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/migration/test_bundle_api_changelog_script.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"68f3ab552bc5fd0c750d40be605a0b916d58e8773e39c60dfc1df62fe98f3455\",\"content\":\"\\\"\\\"\\\"Smoke tests for scripts/migrate/check_bundle_api_changelog.py.\\n\\nExercise the script as a black-box subprocess.  Each test sets up a\\nsynthetic git repo so we don't depend on the real working tree's diff\\nstate (which changes from PR to PR).\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport subprocess\\nimport sys\\nfrom pathlib import Path\\n\\nimport pytest\\n\\nREPO_ROOT = Path(__file__).resolve().parents[6]\\nSCRIPT = REPO_ROOT / \\\"scripts\\\" / \\\"migrate\\\" / \\\"check_bundle_api_changelog.py\\\"\\n\\n\\ndef _git(cwd: Path, *args: str, check: bool = True) -> subprocess.CompletedProcess[str]:\\n    return subprocess.run(  # noqa: S603 - test harness invoking git on a tmp repo\\n        [\\\"git\\\", *args],  # noqa: S607\\n        cwd=cwd,\\n        check=check,\\n        capture_output=True,\\n        text=True,\\n    )\\n\\n\\ndef _run_script(cwd: Path, *args: str) -> subprocess.CompletedProcess[str]:\\n    # The script resolves REPO_ROOT relative to its own location; copy it into\\n    # the synthetic repo so its CWD heuristic matches.\\n    repo_script_dir = cwd / \\\"scripts\\\" / \\\"migrate\\\"\\n    repo_script_dir.mkdir(parents=True, exist_ok=True)\\n    target = repo_script_dir / SCRIPT.name\\n    target.write_text(SCRIPT.read_text(encoding=\\\"utf-8\\\"), encoding=\\\"utf-8\\\")\\n    return subprocess.run(  # noqa: S603 - test harness\\n        [sys.executable, str(target), *args],\\n        cwd=cwd,\\n        check=False,\\n        capture_output=True,\\n        text=True,\\n    )\\n\\n\\ndef _init_repo(cwd: Path) -> None:\\n    _git(cwd, \\\"init\\\", \\\"-q\\\", \\\"-b\\\", \\\"main\\\")\\n    _git(cwd, \\\"config\\\", \\\"user.email\\\", \\\"test@example.com\\\")\\n    _git(cwd, \\\"config\\\", \\\"user.name\\\", \\\"Test\\\")\\n\\n\\ndef _commit(cwd: Path, message: str) -> None:\\n    _git(cwd, \\\"add\\\", \\\"-A\\\")\\n    _git(cwd, \\\"commit\\\", \\\"-q\\\", \\\"-m\\\", message)\\n\\n\\n@pytest.mark.unit\\ndef test_script_exists() -> None:\\n    assert SCRIPT.is_file(), f\\\"missing CI guard script at {SCRIPT}\\\"\\n\\n\\n@pytest.mark.unit\\ndef test_no_in_scope_changes_passes(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A PR that only touches unrelated files passes without touching BUNDLE_API.md.\\\"\\\"\\\"\\n    _init_repo(tmp_path)\\n    (tmp_path / \\\"BUNDLE_API.md\\\").write_text(\\\"# Bundle API\\\\n\\\\n## Changelog\\\\n\\\\n### v0\\\\n\\\\n- initial\\\\n\\\", encoding=\\\"utf-8\\\")\\n    (tmp_path / \\\"README.md\\\").write_text(\\\"hello\\\\n\\\", encoding=\\\"utf-8\\\")\\n    _commit(tmp_path, \\\"initial\\\")\\n    _git(tmp_path, \\\"checkout\\\", \\\"-q\\\", \\\"-b\\\", \\\"feat/x\\\")\\n\\n    (tmp_path / \\\"README.md\\\").write_text(\\\"hello world\\\\n\\\", encoding=\\\"utf-8\\\")\\n    _commit(tmp_path, \\\"tweak readme\\\")\\n\\n    proc = _run_script(tmp_path, \\\"--base\\\", \\\"main\\\")\\n    assert proc.returncode == 0, proc.stdout + proc.stderr\\n    assert \\\"no in-scope\\\" in proc.stdout.lower()\\n\\n\\n@pytest.mark.unit\\ndef test_in_scope_change_without_changelog_fails(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Editing manifest.py without updating BUNDLE_API.md is rejected.\\\"\\\"\\\"\\n    _init_repo(tmp_path)\\n    (tmp_path / \\\"BUNDLE_API.md\\\").write_text(\\\"# Bundle API\\\\n\\\\n## Changelog\\\\n\\\\n### v0\\\\n\\\\n- initial\\\\n\\\", encoding=\\\"utf-8\\\")\\n    manifest = tmp_path / \\\"src\\\" / \\\"lfx\\\" / \\\"src\\\" / \\\"lfx\\\" / \\\"extension\\\" / \\\"manifest.py\\\"\\n    manifest.parent.mkdir(parents=True, exist_ok=True)\\n    manifest.write_text(\\\"# manifest v0\\\\n\\\", encoding=\\\"utf-8\\\")\\n    _commit(tmp_path, \\\"initial\\\")\\n    _git(tmp_path, \\\"checkout\\\", \\\"-q\\\", \\\"-b\\\", \\\"feat/x\\\")\\n\\n    manifest.write_text(\\\"# manifest v0\\\\n# extra\\\\n\\\", encoding=\\\"utf-8\\\")\\n    _commit(tmp_path, \\\"tweak manifest\\\")\\n\\n    proc = _run_script(tmp_path, \\\"--base\\\", \\\"main\\\")\\n    assert proc.returncode == 1, proc.stdout + proc.stderr\\n    assert \\\"BUNDLE_API.md\\\" in proc.stderr\\n\\n\\n@pytest.mark.unit\\ndef test_in_scope_change_with_changelog_passes(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Editing manifest.py and adding a new ## Changelog line is accepted.\\\"\\\"\\\"\\n    _init_repo(tmp_path)\\n    (tmp_path / \\\"BUNDLE_API.md\\\").write_text(\\\"# Bundle API\\\\n\\\\n## Changelog\\\\n\\\\n### v0\\\\n\\\\n- initial\\\\n\\\", encoding=\\\"utf-8\\\")\\n    manifest = tmp_path / \\\"src\\\" / \\\"lfx\\\" / \\\"src\\\" / \\\"lfx\\\" / \\\"extension\\\" / \\\"manifest.py\\\"\\n    manifest.parent.mkdir(parents=True, exist_ok=True)\\n    manifest.write_text(\\\"# manifest v0\\\\n\\\", encoding=\\\"utf-8\\\")\\n    _commit(tmp_path, \\\"initial\\\")\\n    _git(tmp_path, \\\"checkout\\\", \\\"-q\\\", \\\"-b\\\", \\\"feat/x\\\")\\n\\n    manifest.write_text(\\\"# manifest v0\\\\n# extra\\\\n\\\", encoding=\\\"utf-8\\\")\\n    (tmp_path / \\\"BUNDLE_API.md\\\").write_text(\\n        \\\"# Bundle API\\\\n\\\\n## Changelog\\\\n\\\\n### v0\\\\n\\\\n- initial\\\\n- added a new field\\\\n\\\",\\n        encoding=\\\"utf-8\\\",\\n    )\\n    _commit(tmp_path, \\\"tweak manifest + changelog\\\")\\n\\n    proc = _run_script(tmp_path, \\\"--base\\\", \\\"main\\\")\\n    assert proc.returncode == 0, proc.stdout + proc.stderr\\n\\n\\n@pytest.mark.unit\\ndef test_in_scope_change_with_unrelated_bundle_api_edit_fails(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Editing manifest.py and BUNDLE_API.md but NOT under ## Changelog is rejected.\\\"\\\"\\\"\\n    _init_repo(tmp_path)\\n    (tmp_path / \\\"BUNDLE_API.md\\\").write_text(\\n        \\\"# Bundle API\\\\n\\\\nIntro paragraph.\\\\n\\\\n## Changelog\\\\n\\\\n### v0\\\\n\\\\n- initial\\\\n\\\",\\n        encoding=\\\"utf-8\\\",\\n    )\\n    manifest = tmp_path / \\\"src\\\" / \\\"lfx\\\" / \\\"src\\\" / \\\"lfx\\\" / \\\"extension\\\" / \\\"manifest.py\\\"\\n    manifest.parent.mkdir(parents=True, exist_ok=True)\\n    manifest.write_text(\\\"# manifest v0\\\\n\\\", encoding=\\\"utf-8\\\")\\n    _commit(tmp_path, \\\"initial\\\")\\n    _git(tmp_path, \\\"checkout\\\", \\\"-q\\\", \\\"-b\\\", \\\"feat/x\\\")\\n\\n    manifest.write_text(\\\"# manifest v0\\\\n# extra\\\\n\\\", encoding=\\\"utf-8\\\")\\n    # Edit BUNDLE_API.md but only the intro paragraph, not the changelog.\\n    (tmp_path / \\\"BUNDLE_API.md\\\").write_text(\\n        \\\"# Bundle API\\\\n\\\\nIntro paragraph.  Now reworded.\\\\n\\\\n## Changelog\\\\n\\\\n### v0\\\\n\\\\n- initial\\\\n\\\",\\n        encoding=\\\"utf-8\\\",\\n    )\\n    _commit(tmp_path, \\\"tweak manifest + intro\\\")\\n\\n    proc = _run_script(tmp_path, \\\"--base\\\", \\\"main\\\")\\n    assert proc.returncode == 1, proc.stdout + proc.stderr\\n    assert \\\"## Changelog\\\" in proc.stderr or \\\"Changelog\\\" in proc.stderr\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/migration/test_loader.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8a6a61c652771b9727daa6493ca7c29178729f5d17a4a9d65031f0cf07674d4d\",\"content\":\"\\\"\\\"\\\"Tests for the migration table loader.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom typing import TYPE_CHECKING\\n\\nimport pytest\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\nfrom lfx.extension.migration import loader as loader_mod\\nfrom lfx.extension.migration.loader import (\\n    MIGRATION_TABLE_PATH,\\n    invalidate_cache,\\n    load_migration_table,\\n)\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _clear_cache() -> None:\\n    invalidate_cache()\\n\\n\\n@pytest.mark.unit\\ndef test_canonical_table_loads() -> None:\\n    \\\"\\\"\\\"The shipped migration_table.json must always parse cleanly.\\\"\\\"\\\"\\n    table, error = load_migration_table()\\n    assert error is None\\n    assert table is not None\\n    assert table.schema_version == 1\\n\\n\\n@pytest.mark.unit\\ndef test_canonical_table_rewrites_legacy_tavily_tool() -> None:\\n    table, error = load_migration_table()\\n    assert error is None\\n    assert table is not None\\n    target = \\\"ext:tavily:TavilySearchComponent@official\\\"\\n\\n    direct_import_path = \\\"lfx.components.tools.tavily_search_tool.TavilySearchToolComponent\\\"\\n    package_import_path = \\\"lfx.components.tools.TavilySearchToolComponent\\\"\\n    direct_tavily_tool_import = table.lookup_import_path(direct_import_path)\\n    package_tavily_tool_import = table.lookup_import_path(package_import_path)\\n\\n    assert direct_tavily_tool_import is not None\\n    assert package_tavily_tool_import is not None\\n    assert direct_tavily_tool_import.target == target\\n    assert package_tavily_tool_import.target == target\\n\\n\\n@pytest.mark.unit\\ndef test_canonical_path_lives_in_lfx_package() -> None:\\n    \\\"\\\"\\\"Sanity: the canonical path is inside the lfx wheel layout.\\\"\\\"\\\"\\n    assert MIGRATION_TABLE_PATH.name == \\\"migration_table.json\\\"\\n    assert \\\"extension\\\" in MIGRATION_TABLE_PATH.parts\\n\\n\\n@pytest.mark.unit\\ndef test_missing_file_returns_typed_error(tmp_path: Path) -> None:\\n    nope = tmp_path / \\\"missing.json\\\"\\n    table, error = load_migration_table(nope, use_cache=False)\\n    assert table is None\\n    assert error is not None\\n    assert error.code == \\\"migration-table-missing\\\"\\n\\n\\n@pytest.mark.unit\\ndef test_invalid_json_returns_typed_error(tmp_path: Path) -> None:\\n    bad = tmp_path / \\\"bad.json\\\"\\n    bad.write_text(\\\"{not valid json\\\", encoding=\\\"utf-8\\\")\\n    table, error = load_migration_table(bad, use_cache=False)\\n    assert table is None\\n    assert error is not None\\n    assert error.code == \\\"migration-table-invalid\\\"\\n\\n\\n@pytest.mark.unit\\ndef test_non_object_top_level_returns_typed_error(tmp_path: Path) -> None:\\n    bad = tmp_path / \\\"bad.json\\\"\\n    bad.write_text(\\\"[]\\\", encoding=\\\"utf-8\\\")\\n    table, error = load_migration_table(bad, use_cache=False)\\n    assert table is None\\n    assert error is not None\\n    assert error.code == \\\"migration-table-invalid\\\"\\n\\n\\n@pytest.mark.unit\\ndef test_pydantic_validation_failure_returns_typed_error(tmp_path: Path) -> None:\\n    bad = tmp_path / \\\"bad.json\\\"\\n    bad.write_text(\\n        json.dumps(\\n            {\\n                \\\"schema_version\\\": 1,\\n                \\\"entries\\\": [\\n                    {\\n                        # Missing all three legacy_* fields -> validator rejects.\\n                        \\\"target\\\": \\\"ext:openai:Foo@official\\\",\\n                        \\\"added_in\\\": \\\"1.10.0\\\",\\n                    }\\n                ],\\n            }\\n        ),\\n        encoding=\\\"utf-8\\\",\\n    )\\n    table, error = load_migration_table(bad, use_cache=False)\\n    assert table is None\\n    assert error is not None\\n    assert error.code == \\\"migration-table-invalid\\\"\\n\\n\\n@pytest.mark.unit\\ndef test_cache_returns_same_instance() -> None:\\n    first, _ = load_migration_table()\\n    second, _ = load_migration_table()\\n    assert first is second\\n    invalidate_cache()\\n    third, _ = load_migration_table()\\n    # After invalidate_cache the parser runs again; identity will differ.\\n    assert third is not first\\n    assert third == first\\n\\n\\n@pytest.mark.unit\\ndef test_path_override_bypasses_cache(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Explicit ``path`` argument must read from disk, not the process cache.\\n\\n    Mirrors the cached canonical table into a temp file so we can assert\\n    value-equality while still distinguishing object identity, regardless of\\n    what the canonical migration_table.json currently contains.  Drift in\\n    the canonical table no longer breaks this test.\\n    \\\"\\\"\\\"\\n    cached, _ = load_migration_table()\\n    custom = tmp_path / \\\"custom.json\\\"\\n    custom.write_text(\\n        json.dumps(\\n            {\\n                \\\"schema_version\\\": cached.schema_version,\\n                \\\"entries\\\": [e.model_dump(exclude_none=True) for e in cached.entries],\\n                \\\"ambiguous_bare_names\\\": [a.model_dump(exclude_none=True) for a in cached.ambiguous_bare_names],\\n            }\\n        ),\\n        encoding=\\\"utf-8\\\",\\n    )\\n    direct, _ = load_migration_table(custom)\\n    # Explicit path bypasses cache entirely; direct must be a fresh instance,\\n    # not the cached one, but should compare value-equal when content matches.\\n    assert direct is not cached\\n    assert direct == cached\\n\\n\\n@pytest.mark.unit\\ndef test_empty_table_helper() -> None:\\n    table = loader_mod.empty_table()\\n    assert table.schema_version == 1\\n    assert table.entries == []\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/migration/test_migration_table_completeness.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"aa2387866318805a7f5a4b3c92d0901fae3f7b1f1bd082ae10bb44f8f791235a\",\"content\":\"\\\"\\\"\\\"Migration-table completeness guard for the lfx-bundles long tail.\\n\\nSaved flows match components **by class name**.  When a provider moved into\\n``src/bundles/lfx-bundles/src/lfx_bundles/<provider>/`` its component classes\\nmust be reachable through the canonical ``migration_table.json`` as an\\n``ext:<provider>:<Class>@<slot>`` target, or a flow that referenced the old\\nlocation silently fails to upgrade.\\n\\nThis test locks that invariant: for every provider folder under\\n``lfx_bundles`` it discovers the component class names *statically* (via\\n``ast`` -- many providers import optional SDKs at module top level and cannot\\nbe imported in a bare test env) and asserts that each discovered class appears\\nas a migration target for that provider.  The table is complete today, so this\\ntest passes; it exists so a future provider (or component class) moved into a\\nbundle **without** a corresponding table entry fails CI instead of shipping a\\nflow that cannot be upgraded.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport ast\\nimport re\\nfrom pathlib import Path\\n\\nimport pytest\\nfrom lfx.extension.migration.loader import MIGRATION_TABLE_PATH, load_migration_table\\n\\n# ---------------------------------------------------------------------------\\n# Repo / bundle discovery\\n# ---------------------------------------------------------------------------\\n\\n# .../src/lfx/tests/unit/extension/migration/<thisfile> -> repo root is 6 up.\\n_REPO_ROOT: Path = Path(__file__).resolve().parents[6]\\n_LFX_BUNDLES_ROOT: Path = _REPO_ROOT / \\\"src\\\" / \\\"bundles\\\" / \\\"lfx-bundles\\\" / \\\"src\\\" / \\\"lfx_bundles\\\"\\n\\n# Matches the bundle + class segments of a canonical ``ext:<bundle>:<Class>@<slot>``\\n# target.  Kept local to the test so a schema-regex change can't silently widen\\n# what counts as \\\"covered\\\".\\n_TARGET_RE: re.Pattern[str] = re.compile(r\\\"^ext:(?P<bundle>[a-z][a-z0-9_]*):(?P<klass>[A-Za-z_][A-Za-z0-9_]*)@\\\")\\n\\n\\ndef _discover_providers() -> list[str]:\\n    \\\"\\\"\\\"Provider folders under ``lfx_bundles`` (each a package with ``__init__.py``).\\\"\\\"\\\"\\n    if not _LFX_BUNDLES_ROOT.is_dir():\\n        return []\\n    return sorted(\\n        entry.name\\n        for entry in _LFX_BUNDLES_ROOT.iterdir()\\n        if entry.is_dir() and entry.name != \\\"__pycache__\\\" and (entry / \\\"__init__.py\\\").exists()\\n    )\\n\\n\\ndef _base_name(base: ast.expr) -> str | None:\\n    \\\"\\\"\\\"Return the trailing identifier of a class base (``Foo`` or ``mod.Foo``).\\\"\\\"\\\"\\n    if isinstance(base, ast.Name):\\n        return base.id\\n    if isinstance(base, ast.Attribute):\\n        return base.attr\\n    return None\\n\\n\\ndef _discover_component_classes(provider_dir: Path) -> set[str]:\\n    \\\"\\\"\\\"Statically collect component class names defined under ``provider_dir``.\\n\\n    A \\\"component\\\" is any class whose base list contains an identifier ending in\\n    ``Component`` (e.g. ``class Foo(Component)`` or ``class Foo(LCToolComponent)``).\\n    We parse with ``ast`` rather than importing because many providers import\\n    optional third-party SDKs at module import time and would blow up here.\\n    Over-inclusion is fine: the table check below is what fails if a class is\\n    genuinely unmapped.\\n    \\\"\\\"\\\"\\n    names: set[str] = set()\\n    for py_file in sorted(provider_dir.rglob(\\\"*.py\\\")):\\n        if \\\"__pycache__\\\" in py_file.parts:\\n            continue\\n        try:\\n            tree = ast.parse(py_file.read_text(encoding=\\\"utf-8\\\"))\\n        except (SyntaxError, UnicodeDecodeError):\\n            continue\\n        for node in ast.walk(tree):\\n            if not isinstance(node, ast.ClassDef):\\n                continue\\n            if any((name := _base_name(base)) is not None and name.endswith(\\\"Component\\\") for base in node.bases):\\n                names.add(node.name)\\n    return names\\n\\n\\n_PROVIDERS: list[str] = _discover_providers()\\n\\n\\n@pytest.fixture(scope=\\\"module\\\")\\ndef migration_targets() -> dict[str, set[str]]:\\n    \\\"\\\"\\\"Map ``bundle name -> {class names}`` from the canonical migration table.\\\"\\\"\\\"\\n    table, error = load_migration_table(MIGRATION_TABLE_PATH, use_cache=False)\\n    assert error is None, f\\\"migration table failed to load: {error}\\\"\\n    assert table is not None\\n    targets: dict[str, set[str]] = {}\\n    for entry in table.entries:\\n        match = _TARGET_RE.match(entry.target)\\n        if match is not None:\\n            targets.setdefault(match.group(\\\"bundle\\\"), set()).add(match.group(\\\"klass\\\"))\\n    return targets\\n\\n\\n@pytest.mark.unit\\ndef test_lfx_bundles_root_discovers_providers() -> None:\\n    \\\"\\\"\\\"Guard the guard: discovery must actually find providers.\\n\\n    If discovery silently finds nothing the parametrized test below would\\n    vacuously pass, so assert we enumerated at least one provider.\\n    \\\"\\\"\\\"\\n    assert _LFX_BUNDLES_ROOT.is_dir(), f\\\"lfx_bundles root not found at {_LFX_BUNDLES_ROOT}\\\"\\n    assert _PROVIDERS, \\\"no lfx_bundles providers discovered -- discovery logic is broken\\\"\\n\\n\\n@pytest.mark.unit\\n@pytest.mark.parametrize(\\\"provider\\\", _PROVIDERS)\\ndef test_provider_components_have_migration_targets(provider: str, migration_targets: dict[str, set[str]]) -> None:\\n    \\\"\\\"\\\"Every component class in a bundle must be an ``ext:<provider>:<Class>`` target.\\n\\n    Saved flows resolve components by class name; an unmapped class means an old\\n    flow referencing it cannot be upgraded after the bundle move.\\n    \\\"\\\"\\\"\\n    discovered = _discover_component_classes(_LFX_BUNDLES_ROOT / provider)\\n    assert discovered, (\\n        f\\\"no component classes discovered under bundle {provider!r} -- \\\"\\n        \\\"either the bundle has no components (unexpected) or discovery is broken\\\"\\n    )\\n\\n    table_classes = migration_targets.get(provider, set())\\n    assert table_classes, (\\n        f\\\"bundle {provider!r} has no ext:{provider}:...@ target in migration_table.json; \\\"\\n        \\\"saved flows using its components cannot be upgraded after the bundle move\\\"\\n    )\\n\\n    missing = discovered - table_classes\\n    assert not missing, (\\n        f\\\"bundle {provider!r} component class(es) {sorted(missing)} are missing from \\\"\\n        f\\\"migration_table.json (no ext:{provider}:<Class>@ target); add a migration \\\"\\n        \\\"entry so saved flows referencing them upgrade correctly\\\"\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/migration/test_rewrite.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"087f7ec342018be7d0201f306f2ef262212c3bd697d426f92665bdb18500a49d\",\"content\":\"\\\"\\\"\\\"Tests for the flow-deserializer rewrite hook.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport sys\\nfrom types import SimpleNamespace\\n\\nimport pytest\\nfrom lfx.extension.migration.rewrite import migrate_flow_payload\\nfrom lfx.extension.migration.schema import (\\n    AmbiguousBareName,\\n    MigrationEntry,\\n    MigrationTable,\\n)\\n\\n\\ndef _node(node_id: str, type_value: str) -> dict:\\n    \\\"\\\"\\\"Build a minimal saved-flow node skeleton for testing.\\\"\\\"\\\"\\n    return {\\n        \\\"id\\\": node_id,\\n        \\\"type\\\": \\\"genericNode\\\",\\n        \\\"data\\\": {\\n            \\\"id\\\": node_id,\\n            \\\"type\\\": type_value,\\n            \\\"node\\\": {\\\"template\\\": {}},\\n        },\\n    }\\n\\n\\ndef _note_node(node_id: str) -> dict:\\n    \\\"\\\"\\\"Build a note node that still carries a data.type value.\\\"\\\"\\\"\\n    return {\\n        \\\"id\\\": node_id,\\n        \\\"type\\\": \\\"noteNode\\\",\\n        \\\"data\\\": {\\n            \\\"id\\\": node_id,\\n            \\\"type\\\": \\\"note\\\",\\n            \\\"node\\\": {\\\"template\\\": {}},\\n        },\\n    }\\n\\n\\ndef _payload(*nodes: dict) -> dict:\\n    return {\\\"data\\\": {\\\"nodes\\\": list(nodes), \\\"edges\\\": []}}\\n\\n\\n@pytest.fixture\\ndef table() -> MigrationTable:\\n    return MigrationTable(\\n        schema_version=1,\\n        entries=[\\n            MigrationEntry(\\n                bare_class_name=\\\"OpenAIEmbeddings\\\",\\n                target=\\\"ext:openai:OpenAIEmbeddings@official\\\",\\n                added_in=\\\"1.10.0\\\",\\n            ),\\n            MigrationEntry(\\n                import_path=\\\"langflow.components.openai.OpenAIEmbeddings\\\",\\n                target=\\\"ext:openai:OpenAIEmbeddings@official\\\",\\n                added_in=\\\"1.10.0\\\",\\n            ),\\n            MigrationEntry(\\n                legacy_slot=\\\"ext:openai:OpenAIEmbeddings@official-pre-a\\\",\\n                target=\\\"ext:openai:OpenAIEmbeddings@official\\\",\\n                added_in=\\\"1.10.0\\\",\\n            ),\\n            MigrationEntry(\\n                bare_class_name=\\\"MergeDataComponent\\\",\\n                target=\\\"ext:utilities:MergeDataComponent@official\\\",\\n                added_in=\\\"1.10.0\\\",\\n            ),\\n        ],\\n    )\\n\\n\\n@pytest.mark.unit\\ndef test_rewrites_bare_class_name(table: MigrationTable) -> None:\\n    payload = _payload(_node(\\\"OpenAIEmbeddings-1\\\", \\\"OpenAIEmbeddings\\\"))\\n    report = migrate_flow_payload(payload, table=table)\\n    assert report.rewritten_count == 1\\n    assert payload[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"type\\\"] == \\\"ext:openai:OpenAIEmbeddings@official\\\"\\n    [record] = report.records\\n    assert record.outcome == \\\"rewritten\\\"\\n    assert record.legacy_form_kind == \\\"bare_class_name\\\"\\n    assert record.new_value == \\\"ext:openai:OpenAIEmbeddings@official\\\"\\n\\n\\n@pytest.mark.unit\\ndef test_rewrites_import_path(table: MigrationTable) -> None:\\n    payload = _payload(_node(\\\"X-1\\\", \\\"langflow.components.openai.OpenAIEmbeddings\\\"))\\n    report = migrate_flow_payload(payload, table=table)\\n    assert report.rewritten_count == 1\\n    assert payload[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"type\\\"] == \\\"ext:openai:OpenAIEmbeddings@official\\\"\\n    assert report.records[0].legacy_form_kind == \\\"import_path\\\"\\n\\n\\n@pytest.mark.unit\\ndef test_rewrites_pre_phase_a_slot(table: MigrationTable) -> None:\\n    payload = _payload(_node(\\\"X-1\\\", \\\"ext:openai:OpenAIEmbeddings@official-pre-a\\\"))\\n    report = migrate_flow_payload(payload, table=table)\\n    assert report.rewritten_count == 1\\n    assert payload[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"type\\\"] == \\\"ext:openai:OpenAIEmbeddings@official\\\"\\n    assert report.records[0].legacy_form_kind == \\\"legacy_slot\\\"\\n\\n\\n@pytest.mark.unit\\ndef test_rewrites_every_known_reference_in_one_pass(table: MigrationTable) -> None:\\n    payload = _payload(\\n        _node(\\\"a\\\", \\\"OpenAIEmbeddings\\\"),\\n        _node(\\\"b\\\", \\\"langflow.components.openai.OpenAIEmbeddings\\\"),\\n        _node(\\\"c\\\", \\\"ext:openai:OpenAIEmbeddings@official-pre-a\\\"),\\n        _node(\\\"d\\\", \\\"MergeDataComponent\\\"),\\n    )\\n    report = migrate_flow_payload(payload, table=table)\\n    assert report.rewritten_count == 4\\n    new_types = [n[\\\"data\\\"][\\\"type\\\"] for n in payload[\\\"data\\\"][\\\"nodes\\\"]]\\n    assert new_types == [\\n        \\\"ext:openai:OpenAIEmbeddings@official\\\",\\n        \\\"ext:openai:OpenAIEmbeddings@official\\\",\\n        \\\"ext:openai:OpenAIEmbeddings@official\\\",\\n        \\\"ext:utilities:MergeDataComponent@official\\\",\\n    ]\\n\\n\\n@pytest.mark.unit\\ndef test_already_canonical_left_alone(table: MigrationTable) -> None:\\n    payload = _payload(_node(\\\"x\\\", \\\"ext:openai:OpenAIEmbeddings@official\\\"))\\n    report = migrate_flow_payload(payload, table=table)\\n    assert report.rewritten_count == 0\\n    assert report.records[0].outcome == \\\"already_canonical\\\"\\n    assert payload[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"type\\\"] == \\\"ext:openai:OpenAIEmbeddings@official\\\"\\n\\n\\n@pytest.mark.unit\\n@pytest.mark.parametrize(\\n    \\\"type_value\\\",\\n    [\\n        \\\"Prompt\\\",\\n        \\\"ChatOutput\\\",\\n        \\\"ParserComponent\\\",\\n        \\\"URLComponent\\\",\\n        \\\"LanguageModelComponent\\\",\\n    ],\\n)\\ndef test_known_current_components_left_alone_without_errors(table: MigrationTable, type_value: str) -> None:\\n    payload = _payload(_node(f\\\"{type_value}-1\\\", type_value))\\n    known_current_types = {\\n        \\\"Prompt\\\",\\n        \\\"ChatOutput\\\",\\n        \\\"ParserComponent\\\",\\n        \\\"URLComponent\\\",\\n        \\\"LanguageModelComponent\\\",\\n    }\\n\\n    report = migrate_flow_payload(payload, table=table, known_current_types=known_current_types)\\n\\n    assert report.rewritten_count == 0\\n    assert report.errors == []\\n    [record] = report.records\\n    assert record.outcome == \\\"known_current_component\\\"\\n    assert record.error is None\\n    assert payload[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"type\\\"] == type_value\\n\\n\\n@pytest.mark.unit\\ndef test_note_node_with_data_type_is_skipped(table: MigrationTable) -> None:\\n    payload = _payload(_note_node(\\\"note-1\\\"))\\n\\n    report = migrate_flow_payload(payload, table=table, known_current_types=set())\\n\\n    assert report.records == []\\n    assert report.errors == []\\n    assert payload[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"type\\\"] == \\\"note\\\"\\n\\n\\n@pytest.mark.unit\\ndef test_migration_table_entry_wins_over_known_current_type(table: MigrationTable) -> None:\\n    payload = _payload(_node(\\\"OpenAIEmbeddings-1\\\", \\\"OpenAIEmbeddings\\\"))\\n\\n    report = migrate_flow_payload(payload, table=table, known_current_types={\\\"OpenAIEmbeddings\\\"})\\n\\n    assert report.rewritten_count == 1\\n    assert report.errors == []\\n    [record] = report.records\\n    assert record.outcome == \\\"rewritten\\\"\\n    assert payload[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"type\\\"] == \\\"ext:openai:OpenAIEmbeddings@official\\\"\\n\\n\\n@pytest.mark.unit\\ndef test_bundled_index_alias_suppresses_current_component_noise() -> None:\\n    payload = _payload(_node(\\\"Prompt-1\\\", \\\"Prompt\\\"))\\n    table = MigrationTable(schema_version=1, entries=[])\\n\\n    report = migrate_flow_payload(payload, table=table)\\n\\n    assert report.rewritten_count == 0\\n    assert report.errors == []\\n    [record] = report.records\\n    assert record.outcome == \\\"known_current_component\\\"\\n    assert payload[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"type\\\"] == \\\"Prompt\\\"\\n\\n\\n@pytest.mark.unit\\ndef test_loaded_component_cache_suppresses_current_component_noise(monkeypatch: pytest.MonkeyPatch) -> None:\\n    payload = _payload(_node(\\\"CustomCurrent-1\\\", \\\"CustomCurrent\\\"))\\n    table = MigrationTable(schema_version=1, entries=[])\\n    fake_components_module = SimpleNamespace(\\n        component_cache=SimpleNamespace(\\n            all_types_dict={\\n                \\\"custom\\\": {\\n                    \\\"CustomCurrent\\\": {\\n                        \\\"display_name\\\": \\\"Custom Current\\\",\\n                    }\\n                }\\n            }\\n        )\\n    )\\n    monkeypatch.setitem(sys.modules, \\\"lfx.interface.components\\\", fake_components_module)\\n\\n    report = migrate_flow_payload(payload, table=table)\\n\\n    assert report.rewritten_count == 0\\n    assert report.errors == []\\n    [record] = report.records\\n    assert record.outcome == \\\"known_current_component\\\"\\n    assert payload[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"type\\\"] == \\\"CustomCurrent\\\"\\n\\n\\n@pytest.mark.unit\\ndef test_unmapped_reference_emits_typed_error_with_suggestion(table: MigrationTable) -> None:\\n    # A near-miss on an existing entry: should produce a close-match hint.\\n    payload = _payload(_node(\\\"x\\\", \\\"OpenAIEmbedding\\\"))  # missing trailing 's'\\n    report = migrate_flow_payload(payload, table=table)\\n    assert report.rewritten_count == 0\\n    [record] = report.records\\n    assert record.outcome == \\\"unmapped\\\"\\n    assert record.error is not None\\n    assert record.error.code == \\\"component-not-found-with-hint\\\"\\n    assert \\\"OpenAIEmbeddings\\\" in record.error.hint\\n    # Flow load should NOT crash; node retains its original type.\\n    assert payload[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"type\\\"] == \\\"OpenAIEmbedding\\\"\\n\\n\\n@pytest.mark.unit\\ndef test_unmapped_with_no_close_match_falls_back_to_generic_hint(table: MigrationTable) -> None:\\n    payload = _payload(_node(\\\"x\\\", \\\"TotallyUnrelatedSymbol\\\"))\\n    report = migrate_flow_payload(payload, table=table)\\n    [record] = report.records\\n    assert record.outcome == \\\"unmapped\\\"\\n    assert record.error is not None\\n    assert \\\"No close match\\\" in record.error.hint\\n\\n\\n@pytest.mark.unit\\ndef test_cross_bucket_ambiguity_emits_component_name_ambiguous() -> None:\\n    \\\"\\\"\\\"Two buckets matching the same string -> ``component-name-ambiguous``.\\\"\\\"\\\"\\n    # Build two entries that share a literal string across buckets.  We use\\n    # ``model_construct`` to bypass the table-level uniqueness check; the\\n    # entries themselves are individually valid.\\n    e_bare = MigrationEntry(\\n        bare_class_name=\\\"ConflictedName\\\",\\n        target=\\\"ext:bundle_a:ConflictedName@official\\\",\\n        added_in=\\\"1.10.0\\\",\\n    )\\n    # Build the import_path entry such that its import_path equals the bare\\n    # name above.  The per-entry validator requires at least one dot in the\\n    # import path, so we cheat by mutating the frozen instance's slot after\\n    # construction; the table-level uniqueness check is bypassed via\\n    # ``model_construct``.\\n    e_imp = MigrationEntry(\\n        import_path=\\\"x.ConflictedName\\\",\\n        target=\\\"ext:bundle_b:ConflictedName@official\\\",\\n        added_in=\\\"1.10.0\\\",\\n    )\\n    object.__setattr__(e_imp, \\\"import_path\\\", \\\"ConflictedName\\\")\\n\\n    table = MigrationTable.model_construct(schema_version=1, entries=[e_bare, e_imp])\\n    payload = _payload(_node(\\\"z\\\", \\\"ConflictedName\\\"))\\n    report = migrate_flow_payload(payload, table=table)\\n    [record] = report.records\\n    assert record.outcome == \\\"ambiguous\\\"\\n    assert record.error is not None\\n    assert record.error.code == \\\"component-name-ambiguous\\\"\\n    # Original node value is left intact -- we never silently load into\\n    # the wrong bundle.\\n    assert payload[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"type\\\"] == \\\"ConflictedName\\\"\\n\\n\\n@pytest.mark.unit\\ndef test_ambiguous_bare_name_surfaces_component_name_ambiguous() -> None:\\n    \\\"\\\"\\\"A bare name registered as ambiguous emits the typed code, not \\\"not-found\\\".\\n\\n    Without this code path, an ambiguous bare class (e.g. ``MergeDataComponent``\\n    living in both ``processing`` and ``deactivated``) would have no\\n    auto-rewrite entry (CI rejects ambiguous bare-name entries) and would\\n    fall through to ``component-not-found-with-hint``, which loses the\\n    \\\"you have to choose\\\" semantics.\\n    \\\"\\\"\\\"\\n    table = MigrationTable(\\n        schema_version=1,\\n        entries=[],\\n        ambiguous_bare_names=[\\n            AmbiguousBareName(\\n                name=\\\"MergeDataComponent\\\",\\n                candidates=[\\n                    \\\"ext:processing:MergeDataComponent@official\\\",\\n                    \\\"ext:deactivated:MergeDataComponent@official\\\",\\n                ],\\n                added_in=\\\"1.10.0\\\",\\n            ),\\n        ],\\n    )\\n\\n    payload = _payload(_node(\\\"n1\\\", \\\"MergeDataComponent\\\"))\\n    report = migrate_flow_payload(payload, table=table, known_current_types={\\\"MergeDataComponent\\\"})\\n\\n    [record] = report.records\\n    assert record.outcome == \\\"ambiguous\\\"\\n    assert record.error is not None\\n    assert record.error.code == \\\"component-name-ambiguous\\\"\\n    # Both candidate targets must appear in the message verbatim so the\\n    # operator can pick one.\\n    assert \\\"ext:processing:MergeDataComponent@official\\\" in record.error.message\\n    assert \\\"ext:deactivated:MergeDataComponent@official\\\" in record.error.message\\n    # Original node value is left intact -- we never silently load into the\\n    # wrong bundle.\\n    assert payload[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"type\\\"] == \\\"MergeDataComponent\\\"\\n\\n\\n@pytest.mark.unit\\ndef test_unambiguous_bare_name_still_rewrites_with_ambiguous_list_present() -> None:\\n    \\\"\\\"\\\"A bare name in entries wins over the ambiguity list of *other* names.\\n\\n    Regression guard: the ambiguity check must not short-circuit the\\n    happy-path rewrite for an unrelated bare name.\\n    \\\"\\\"\\\"\\n    table = MigrationTable(\\n        schema_version=1,\\n        entries=[\\n            MigrationEntry(\\n                bare_class_name=\\\"OpenAIEmbeddings\\\",\\n                target=\\\"ext:openai:OpenAIEmbeddings@official\\\",\\n                added_in=\\\"1.10.0\\\",\\n            ),\\n        ],\\n        ambiguous_bare_names=[\\n            AmbiguousBareName(\\n                name=\\\"MergeDataComponent\\\",\\n                candidates=[\\n                    \\\"ext:processing:MergeDataComponent@official\\\",\\n                    \\\"ext:deactivated:MergeDataComponent@official\\\",\\n                ],\\n                added_in=\\\"1.10.0\\\",\\n            ),\\n        ],\\n    )\\n\\n    payload = _payload(_node(\\\"n1\\\", \\\"OpenAIEmbeddings\\\"))\\n    report = migrate_flow_payload(payload, table=table)\\n\\n    assert report.rewritten_count == 1\\n    assert payload[\\\"data\\\"][\\\"nodes\\\"][0][\\\"data\\\"][\\\"type\\\"] == \\\"ext:openai:OpenAIEmbeddings@official\\\"\\n\\n\\n@pytest.mark.unit\\ndef test_payload_without_data_wrapper(table: MigrationTable) -> None:\\n    \\\"\\\"\\\"``Graph.from_payload`` accepts both shapes; the rewriter must too.\\\"\\\"\\\"\\n    payload = {\\\"nodes\\\": [_node(\\\"x\\\", \\\"OpenAIEmbeddings\\\")], \\\"edges\\\": []}\\n    report = migrate_flow_payload(payload, table=table)\\n    assert report.rewritten_count == 1\\n    assert payload[\\\"nodes\\\"][0][\\\"data\\\"][\\\"type\\\"] == \\\"ext:openai:OpenAIEmbeddings@official\\\"\\n\\n\\n@pytest.mark.unit\\ndef test_malformed_node_skipped_silently(table: MigrationTable) -> None:\\n    \\\"\\\"\\\"Note nodes / non-component shapes have no ``data.type`` -- skip them.\\\"\\\"\\\"\\n    payload = {\\n        \\\"data\\\": {\\n            \\\"nodes\\\": [\\n                \\\"not a dict\\\",\\n                {\\\"id\\\": \\\"x\\\", \\\"type\\\": \\\"noteNode\\\"},  # no data\\n                {\\\"id\\\": \\\"y\\\", \\\"data\\\": \\\"not a dict\\\"},\\n                {\\\"id\\\": \\\"z\\\", \\\"data\\\": {\\\"id\\\": \\\"z\\\"}},  # no type\\n                _node(\\\"ok\\\", \\\"OpenAIEmbeddings\\\"),\\n            ],\\n            \\\"edges\\\": [],\\n        }\\n    }\\n    report = migrate_flow_payload(payload, table=table)\\n    # Only the 'ok' node was visited.\\n    assert len(report.records) == 1\\n    assert report.records[0].outcome == \\\"rewritten\\\"\\n\\n\\n@pytest.mark.unit\\ndef test_non_dict_payload_raises_type_error(table: MigrationTable) -> None:\\n    with pytest.raises(TypeError):\\n        migrate_flow_payload([], table=table)  # type: ignore[arg-type]\\n\\n\\n@pytest.mark.unit\\ndef test_idempotent_when_run_twice(table: MigrationTable) -> None:\\n    payload = _payload(_node(\\\"x\\\", \\\"OpenAIEmbeddings\\\"))\\n    first = migrate_flow_payload(payload, table=table)\\n    second = migrate_flow_payload(payload, table=table)\\n    assert first.rewritten_count == 1\\n    assert second.rewritten_count == 0\\n    assert second.records[0].outcome == \\\"already_canonical\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/migration/test_router_trust_script.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7827b99b7726ac51076cc81472e654d0ea19a6857e1068f99317aca065ff899c\",\"content\":\"\\\"\\\"\\\"Smoke tests for scripts/migrate/check_router_trust.py.\\n\\nExercises the script as a black-box subprocess so the test catches\\nSystemExit / argparse drift the same way CI would.\\n\\nThe router-trust invariant per the Bundle Separation Developer Guide\\n(section 4): install / uninstall / registry mutation routes must not\\nappear under ``/api/v1/extensions/**``; the trust boundary is pip\\ninstall, not a runtime endpoint.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport subprocess\\nimport sys\\nfrom pathlib import Path\\nfrom textwrap import dedent\\n\\nimport pytest\\n\\nREPO_ROOT = Path(__file__).resolve().parents[6]\\nSCRIPT = REPO_ROOT / \\\"scripts\\\" / \\\"migrate\\\" / \\\"check_router_trust.py\\\"\\n\\n\\ndef _run(*paths: Path) -> subprocess.CompletedProcess[str]:\\n    return subprocess.run(  # noqa: S603 - test harness invoking our own script\\n        [sys.executable, str(SCRIPT), \\\"--paths\\\", *map(str, paths)],\\n        capture_output=True,\\n        text=True,\\n        check=False,\\n    )\\n\\n\\ndef test_clean_extensions_module_passes(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A module with only the reload route must pass.\\\"\\\"\\\"\\n    src = tmp_path / \\\"extensions.py\\\"\\n    src.write_text(\\n        dedent(\\n            \\\"\\\"\\\"\\n            from fastapi import APIRouter\\n            router = APIRouter(prefix=\\\"/extensions\\\")\\n\\n            @router.post(\\\"/{extension_id}/bundles/{bundle_name}/reload\\\")\\n            async def reload_extension_bundle(extension_id: str, bundle_name: str) -> dict:\\n                return {}\\n            \\\"\\\"\\\",\\n        ).strip(),\\n        encoding=\\\"utf-8\\\",\\n    )\\n\\n    result = _run(src)\\n    assert result.returncode == 0, result.stderr\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"path\\\", \\\"func\\\", \\\"expected_token\\\"),\\n    [\\n        (\\\"/install\\\", \\\"install_extension\\\", \\\"install\\\"),\\n        (\\\"/uninstall\\\", \\\"uninstall_extension\\\", \\\"uninstall\\\"),\\n        (\\\"/registry/add\\\", \\\"registry_add\\\", \\\"registry_add\\\"),\\n        (\\\"/registry/remove\\\", \\\"registry_remove\\\", \\\"registry_remove\\\"),\\n    ],\\n)\\ndef test_forbidden_route_fails(tmp_path: Path, path: str, func: str, expected_token: str) -> None:\\n    \\\"\\\"\\\"Each forbidden verb is caught.\\\"\\\"\\\"\\n    src = tmp_path / \\\"extensions.py\\\"\\n    src.write_text(\\n        dedent(\\n            f\\\"\\\"\\\"\\n            from fastapi import APIRouter\\n            router = APIRouter(prefix=\\\"/extensions\\\")\\n\\n            @router.post(\\\"{{extension_id}}{path}\\\")\\n            async def {func}(extension_id: str) -> dict:\\n                return {{}}\\n            \\\"\\\"\\\",\\n        ).strip(),\\n        encoding=\\\"utf-8\\\",\\n    )\\n\\n    result = _run(src)\\n    assert result.returncode == 1, result.stdout\\n    assert expected_token in result.stderr\\n\\n\\ndef test_typed_error_code_namespace_is_allowlisted(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"``installed-extension-immutable`` is a typed error code, not a route.\\n\\n    Strings containing the allowlisted substring must not trip the guard.\\n    \\\"\\\"\\\"\\n    src = tmp_path / \\\"extensions.py\\\"\\n    src.write_text(\\n        dedent(\\n            \\\"\\\"\\\"\\n            from fastapi import APIRouter\\n            router = APIRouter(prefix=\\\"/extensions\\\")\\n\\n            @router.post(\\\"/{extension_id}/bundles/{bundle_name}/reload\\\")\\n            async def reload_extension_bundle(extension_id: str, bundle_name: str) -> dict:\\n                # This handler raises 'installed-extension-immutable' when the\\n                # caller tries to mutate an installed Bundle.\\n                return {\\\"code\\\": \\\"installed-extension-immutable\\\"}\\n            \\\"\\\"\\\",\\n        ).strip(),\\n        encoding=\\\"utf-8\\\",\\n    )\\n\\n    result = _run(src)\\n    assert result.returncode == 0, result.stderr\\n\\n\\ndef test_real_extensions_module_passes() -> None:\\n    \\\"\\\"\\\"The shipped src/backend/.../v1/extensions.py must pass the guard.\\\"\\\"\\\"\\n    real_module = REPO_ROOT / \\\"src\\\" / \\\"backend\\\" / \\\"base\\\" / \\\"langflow\\\" / \\\"api\\\" / \\\"v1\\\" / \\\"extensions.py\\\"\\n    if not real_module.exists():\\n        pytest.skip(\\\"real extensions.py not present in this checkout\\\")\\n\\n    result = _run(real_module)\\n    assert result.returncode == 0, result.stderr\\n\\n\\n# ---------------------------------------------------------------------------\\n# Cross-file resolution\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_split_router_pattern_is_caught(tmp_path: Path, monkeypatch) -> None:\\n    \\\"\\\"\\\"A forbidden handler in module A must be caught when module B mounts it under /extensions.\\n\\n    This is the reviewer's reproducer: the child file declares a router\\n    with no /extensions prefix; a separate parent file calls\\n    ``include_router(child, prefix=\\\"/extensions\\\")``.  A purely\\n    file-scoped scan would let the forbidden ``/install`` handler in the\\n    child module slip through; the cross-file resolver must catch it.\\n    \\\"\\\"\\\"\\n    # Build a synthetic project with two package roots so the script can\\n    # resolve ``from child.api import router`` to a real file on disk.\\n    pkg = tmp_path / \\\"src\\\"\\n    pkg.mkdir()\\n    (pkg / \\\"child\\\").mkdir()\\n    (pkg / \\\"child\\\" / \\\"__init__.py\\\").write_text(\\\"\\\", encoding=\\\"utf-8\\\")\\n    (pkg / \\\"child\\\" / \\\"api.py\\\").write_text(\\n        dedent(\\n            \\\"\\\"\\\"\\n            from fastapi import APIRouter\\n\\n            router = APIRouter()\\n\\n            @router.post(\\\"/install\\\")\\n            async def install_extension():\\n                pass\\n            \\\"\\\"\\\",\\n        ).strip(),\\n        encoding=\\\"utf-8\\\",\\n    )\\n    (pkg / \\\"parent\\\").mkdir()\\n    (pkg / \\\"parent\\\" / \\\"__init__.py\\\").write_text(\\\"\\\", encoding=\\\"utf-8\\\")\\n    (pkg / \\\"parent\\\" / \\\"main.py\\\").write_text(\\n        dedent(\\n            \\\"\\\"\\\"\\n            from fastapi import APIRouter\\n            from child.api import router as child_router\\n\\n            app_router = APIRouter(prefix=\\\"/v1\\\")\\n            app_router.include_router(child_router, prefix=\\\"/extensions\\\")\\n            \\\"\\\"\\\",\\n        ).strip(),\\n        encoding=\\\"utf-8\\\",\\n    )\\n\\n    # Run the script in a subprocess with PYTHONPATH pointing at our pkg\\n    # so its module resolution finds the synthetic project.\\n    import os\\n\\n    env = os.environ.copy()\\n    env[\\\"PYTHONPATH\\\"] = str(pkg)\\n    # Patch MODULE_ROOTS via an env-var hook in the script?  Instead, since\\n    # the script reads MODULE_ROOTS from a module constant, we exercise the\\n    # API directly here rather than spawning a subprocess.\\n    monkeypatch.syspath_prepend(str(REPO_ROOT / \\\"scripts\\\" / \\\"migrate\\\"))\\n    import importlib\\n\\n    guard = importlib.import_module(\\\"check_router_trust\\\")\\n    monkeypatch.setattr(guard, \\\"MODULE_ROOTS\\\", (pkg,))\\n\\n    file_info_map = {\\n        pkg / \\\"child\\\" / \\\"api.py\\\": guard.parse_file(pkg / \\\"child\\\" / \\\"api.py\\\"),\\n        pkg / \\\"parent\\\" / \\\"main.py\\\": guard.parse_file(pkg / \\\"parent\\\" / \\\"main.py\\\"),\\n    }\\n    in_scope = guard.compute_in_scope(file_info_map)\\n    violations = guard.scan_in_scope(file_info_map, in_scope)\\n\\n    assert any(\\\"install\\\" in v for v in violations), (\\n        f\\\"split-router pattern was not caught.  in_scope={in_scope!r}, violations={violations!r}\\\"\\n    )\\n\\n\\ndef test_transitive_include_router_chain_is_caught(tmp_path: Path, monkeypatch) -> None:\\n    \\\"\\\"\\\"Three-hop chain: leaf has the forbidden route; root mounts under /extensions.\\n\\n    Topology:\\n        leaf.py      defines ``leaf_router`` (no prefix) with @leaf_router.post(\\\"/uninstall\\\")\\n        middle.py    defines ``mid_router`` (no prefix) and does\\n                     ``mid_router.include_router(leaf_router)``\\n        root.py      defines ``app`` (or any router) and does\\n                     ``app.include_router(mid_router, prefix=\\\"/extensions\\\")``\\n\\n    The resolver must chase the chain in both directions: ``mid_router``\\n    becomes in-scope because root mounts it under /extensions, and\\n    ``leaf_router`` becomes in-scope because mid_router (now in scope)\\n    mounts it (no /extensions prefix on the inner mount).\\n    \\\"\\\"\\\"\\n    pkg = tmp_path / \\\"src\\\"\\n    pkg.mkdir()\\n    (pkg / \\\"leaf.py\\\").write_text(\\n        dedent(\\n            \\\"\\\"\\\"\\n            from fastapi import APIRouter\\n\\n            leaf_router = APIRouter()\\n\\n            @leaf_router.post(\\\"/uninstall\\\")\\n            async def uninstall_handler():\\n                pass\\n            \\\"\\\"\\\",\\n        ).strip(),\\n        encoding=\\\"utf-8\\\",\\n    )\\n    (pkg / \\\"middle.py\\\").write_text(\\n        dedent(\\n            \\\"\\\"\\\"\\n            from fastapi import APIRouter\\n            from leaf import leaf_router\\n\\n            mid_router = APIRouter()\\n            mid_router.include_router(leaf_router)\\n            \\\"\\\"\\\",\\n        ).strip(),\\n        encoding=\\\"utf-8\\\",\\n    )\\n    (pkg / \\\"root.py\\\").write_text(\\n        dedent(\\n            \\\"\\\"\\\"\\n            from fastapi import APIRouter\\n            from middle import mid_router\\n\\n            app_router = APIRouter(prefix=\\\"/v1\\\")\\n            app_router.include_router(mid_router, prefix=\\\"/extensions\\\")\\n            \\\"\\\"\\\",\\n        ).strip(),\\n        encoding=\\\"utf-8\\\",\\n    )\\n\\n    monkeypatch.syspath_prepend(str(REPO_ROOT / \\\"scripts\\\" / \\\"migrate\\\"))\\n    import importlib\\n\\n    guard = importlib.import_module(\\\"check_router_trust\\\")\\n    monkeypatch.setattr(guard, \\\"MODULE_ROOTS\\\", (pkg,))\\n\\n    paths = [pkg / \\\"leaf.py\\\", pkg / \\\"middle.py\\\", pkg / \\\"root.py\\\"]\\n    file_info_map = {p: guard.parse_file(p) for p in paths}\\n\\n    in_scope = guard.compute_in_scope(file_info_map)\\n    violations = guard.scan_in_scope(file_info_map, in_scope)\\n\\n    # Both mid_router and leaf_router should be in scope after iteration.\\n    in_scope_var_names = {v for _, v in in_scope}\\n    assert \\\"mid_router\\\" in in_scope_var_names\\n    assert \\\"leaf_router\\\" in in_scope_var_names\\n    assert any(\\\"uninstall\\\" in v for v in violations), f\\\"transitive chain not caught.  violations={violations!r}\\\"\\n\\n\\ndef test_module_attribute_import_is_caught(tmp_path: Path, monkeypatch) -> None:\\n    \\\"\\\"\\\"``import child.api`` then ``include_router(child.api.router, prefix=\\\"/extensions\\\")``.\\n\\n    The earlier resolver only recognised ``ast.Name`` arguments to\\n    ``include_router``; a dotted attribute reference was a bypass.  The\\n    parser now flattens any ``Name``/``Attribute`` chain and the\\n    resolver follows ``import x.y`` bindings back to the source file.\\n    \\\"\\\"\\\"\\n    pkg = tmp_path / \\\"src\\\"\\n    pkg.mkdir()\\n    (pkg / \\\"child\\\").mkdir()\\n    (pkg / \\\"child\\\" / \\\"__init__.py\\\").write_text(\\\"\\\", encoding=\\\"utf-8\\\")\\n    (pkg / \\\"child\\\" / \\\"api.py\\\").write_text(\\n        dedent(\\n            \\\"\\\"\\\"\\n            from fastapi import APIRouter\\n\\n            router = APIRouter()\\n\\n            @router.post(\\\"/install\\\")\\n            async def install_extension():\\n                pass\\n            \\\"\\\"\\\",\\n        ).strip(),\\n        encoding=\\\"utf-8\\\",\\n    )\\n    (pkg / \\\"main.py\\\").write_text(\\n        dedent(\\n            \\\"\\\"\\\"\\n            from fastapi import APIRouter\\n            import child.api\\n\\n            app_router = APIRouter(prefix=\\\"/v1\\\")\\n            app_router.include_router(child.api.router, prefix=\\\"/extensions\\\")\\n            \\\"\\\"\\\",\\n        ).strip(),\\n        encoding=\\\"utf-8\\\",\\n    )\\n\\n    monkeypatch.syspath_prepend(str(REPO_ROOT / \\\"scripts\\\" / \\\"migrate\\\"))\\n    import importlib\\n\\n    guard = importlib.import_module(\\\"check_router_trust\\\")\\n    monkeypatch.setattr(guard, \\\"MODULE_ROOTS\\\", (pkg,))\\n\\n    file_info_map = {\\n        pkg / \\\"child\\\" / \\\"api.py\\\": guard.parse_file(pkg / \\\"child\\\" / \\\"api.py\\\"),\\n        pkg / \\\"main.py\\\": guard.parse_file(pkg / \\\"main.py\\\"),\\n    }\\n    in_scope = guard.compute_in_scope(file_info_map)\\n    violations = guard.scan_in_scope(file_info_map, in_scope)\\n\\n    assert any(\\\"install\\\" in v for v in violations), (\\n        f\\\"module-attribute include target not caught.  in_scope={in_scope!r}, violations={violations!r}\\\"\\n    )\\n\\n\\ndef test_module_asname_import_is_caught(tmp_path: Path, monkeypatch) -> None:\\n    \\\"\\\"\\\"``import child.api as child_api`` then ``include_router(child_api.router, ...)``.\\n\\n    Distinct case from plain ``import child.api`` because Python binds\\n    ``child_api`` as the alias instead of ``child``; the resolver has to\\n    treat the alias as the entry point and walk the imported module\\n    path from there.\\n    \\\"\\\"\\\"\\n    pkg = tmp_path / \\\"src\\\"\\n    pkg.mkdir()\\n    (pkg / \\\"child\\\").mkdir()\\n    (pkg / \\\"child\\\" / \\\"__init__.py\\\").write_text(\\\"\\\", encoding=\\\"utf-8\\\")\\n    (pkg / \\\"child\\\" / \\\"api.py\\\").write_text(\\n        dedent(\\n            \\\"\\\"\\\"\\n            from fastapi import APIRouter\\n\\n            router = APIRouter()\\n\\n            @router.post(\\\"/uninstall\\\")\\n            async def uninstall_handler():\\n                pass\\n            \\\"\\\"\\\",\\n        ).strip(),\\n        encoding=\\\"utf-8\\\",\\n    )\\n    (pkg / \\\"main.py\\\").write_text(\\n        dedent(\\n            \\\"\\\"\\\"\\n            from fastapi import APIRouter\\n            import child.api as child_api\\n\\n            app_router = APIRouter(prefix=\\\"/v1\\\")\\n            app_router.include_router(child_api.router, prefix=\\\"/extensions\\\")\\n            \\\"\\\"\\\",\\n        ).strip(),\\n        encoding=\\\"utf-8\\\",\\n    )\\n\\n    monkeypatch.syspath_prepend(str(REPO_ROOT / \\\"scripts\\\" / \\\"migrate\\\"))\\n    import importlib\\n\\n    guard = importlib.import_module(\\\"check_router_trust\\\")\\n    monkeypatch.setattr(guard, \\\"MODULE_ROOTS\\\", (pkg,))\\n\\n    file_info_map = {\\n        pkg / \\\"child\\\" / \\\"api.py\\\": guard.parse_file(pkg / \\\"child\\\" / \\\"api.py\\\"),\\n        pkg / \\\"main.py\\\": guard.parse_file(pkg / \\\"main.py\\\"),\\n    }\\n    in_scope = guard.compute_in_scope(file_info_map)\\n    violations = guard.scan_in_scope(file_info_map, in_scope)\\n\\n    assert any(\\\"uninstall\\\" in v for v in violations), (\\n        f\\\"asname include target not caught.  in_scope={in_scope!r}, violations={violations!r}\\\"\\n    )\\n\\n\\ndef test_relative_import_inside_package_init_is_caught(tmp_path: Path, monkeypatch) -> None:\\n    \\\"\\\"\\\"``from .child import router`` in ``pkg/__init__.py`` resolves to ``pkg.child``.\\n\\n    The earlier resolver computed the relative-import anchor by stripping\\n    a \\\"file\\\" segment from the dotted path; for ``__init__.py`` files\\n    there is no file segment and Python's ``level=1`` already anchors at\\n    the package itself, so the resolver walked one segment too far and\\n    produced an unresolvable bare module name.\\n\\n    Regression for [reviewer's reproducer]:\\n        pkg/__init__.py: from .child import router; include_router(..., prefix=\\\"/extensions\\\")\\n        pkg/child.py:    @router.post(\\\"/install\\\")\\n    \\\"\\\"\\\"\\n    pkg_root = tmp_path / \\\"src\\\"\\n    pkg_root.mkdir()\\n    pkg = pkg_root / \\\"pkg\\\"\\n    pkg.mkdir()\\n    (pkg / \\\"__init__.py\\\").write_text(\\n        dedent(\\n            \\\"\\\"\\\"\\n            from fastapi import APIRouter\\n            from .child import router as child_router\\n\\n            app_router = APIRouter(prefix=\\\"/v1\\\")\\n            app_router.include_router(child_router, prefix=\\\"/extensions\\\")\\n            \\\"\\\"\\\",\\n        ).strip(),\\n        encoding=\\\"utf-8\\\",\\n    )\\n    (pkg / \\\"child.py\\\").write_text(\\n        dedent(\\n            \\\"\\\"\\\"\\n            from fastapi import APIRouter\\n\\n            router = APIRouter()\\n\\n            @router.post(\\\"/install\\\")\\n            async def install_extension():\\n                pass\\n            \\\"\\\"\\\",\\n        ).strip(),\\n        encoding=\\\"utf-8\\\",\\n    )\\n\\n    monkeypatch.syspath_prepend(str(REPO_ROOT / \\\"scripts\\\" / \\\"migrate\\\"))\\n    import importlib\\n\\n    guard = importlib.import_module(\\\"check_router_trust\\\")\\n    monkeypatch.setattr(guard, \\\"MODULE_ROOTS\\\", (pkg_root,))\\n\\n    file_info_map = {\\n        pkg / \\\"__init__.py\\\": guard.parse_file(pkg / \\\"__init__.py\\\"),\\n        pkg / \\\"child.py\\\": guard.parse_file(pkg / \\\"child.py\\\"),\\n    }\\n    init_imports = file_info_map[pkg / \\\"__init__.py\\\"].imports\\n    assert init_imports[\\\"child_router\\\"].module == \\\"pkg.child\\\", (\\n        f\\\"relative import in __init__.py resolved incorrectly: {init_imports!r}\\\"\\n    )\\n\\n    in_scope = guard.compute_in_scope(file_info_map)\\n    violations = guard.scan_in_scope(file_info_map, in_scope)\\n\\n    assert any(\\\"install\\\" in v for v in violations), (\\n        f\\\"relative-from-init bypass not caught.  in_scope={in_scope!r}, violations={violations!r}\\\"\\n    )\\n\\n\\ndef test_unrelated_install_route_not_flagged(tmp_path: Path, monkeypatch) -> None:\\n    \\\"\\\"\\\"A handler named ``install`` on a router never mounted under /extensions is fine.\\n\\n    The guard must not be a generic ban on the word \\\"install\\\" -- only routes\\n    reachable from /api/v1/extensions/** are forbidden.\\n    \\\"\\\"\\\"\\n    pkg = tmp_path / \\\"src\\\"\\n    pkg.mkdir()\\n    (pkg / \\\"elsewhere.py\\\").write_text(\\n        dedent(\\n            \\\"\\\"\\\"\\n            from fastapi import APIRouter\\n\\n            elsewhere_router = APIRouter(prefix=\\\"/marketplace\\\")\\n\\n            @elsewhere_router.post(\\\"/install\\\")\\n            async def marketplace_install():\\n                pass\\n            \\\"\\\"\\\",\\n        ).strip(),\\n        encoding=\\\"utf-8\\\",\\n    )\\n\\n    monkeypatch.syspath_prepend(str(REPO_ROOT / \\\"scripts\\\" / \\\"migrate\\\"))\\n    import importlib\\n\\n    guard = importlib.import_module(\\\"check_router_trust\\\")\\n    monkeypatch.setattr(guard, \\\"MODULE_ROOTS\\\", (pkg,))\\n\\n    file_info_map = {pkg / \\\"elsewhere.py\\\": guard.parse_file(pkg / \\\"elsewhere.py\\\")}\\n    in_scope = guard.compute_in_scope(file_info_map)\\n    violations = guard.scan_in_scope(file_info_map, in_scope)\\n\\n    assert in_scope == set()\\n    assert violations == []\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/migration/test_schema.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2b14bf1389e13aec838da32d224e043fa1e4b3db74ffcac366088509d784f325\",\"content\":\"\\\"\\\"\\\"Schema-level invariants for the migration table.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport pytest\\nfrom lfx.extension.migration.schema import (\\n    MIGRATION_SCHEMA_VERSION,\\n    AmbiguousBareName,\\n    MigrationEntry,\\n    MigrationTable,\\n)\\nfrom pydantic import ValidationError\\n\\n\\n@pytest.mark.unit\\ndef test_entry_requires_exactly_one_legacy_form() -> None:\\n    with pytest.raises(ValidationError):\\n        MigrationEntry(target=\\\"ext:openai:OpenAIEmbeddings@official\\\", added_in=\\\"1.10.0\\\")\\n\\n\\n@pytest.mark.unit\\ndef test_entry_rejects_two_legacy_forms() -> None:\\n    with pytest.raises(ValidationError):\\n        MigrationEntry(\\n            bare_class_name=\\\"OpenAIEmbeddings\\\",\\n            import_path=\\\"langflow.components.openai.OpenAIEmbeddings\\\",\\n            target=\\\"ext:openai:OpenAIEmbeddings@official\\\",\\n            added_in=\\\"1.10.0\\\",\\n        )\\n\\n\\n@pytest.mark.unit\\ndef test_entry_target_must_be_canonical() -> None:\\n    with pytest.raises(ValidationError):\\n        MigrationEntry(\\n            bare_class_name=\\\"OpenAIEmbeddings\\\",\\n            target=\\\"OpenAIEmbeddings\\\",  # not namespaced\\n            added_in=\\\"1.10.0\\\",\\n        )\\n    with pytest.raises(ValidationError):\\n        MigrationEntry(\\n            bare_class_name=\\\"OpenAIEmbeddings\\\",\\n            target=\\\"ext:openai:OpenAIEmbeddings@bogus\\\",  # bad slot\\n            added_in=\\\"1.10.0\\\",\\n        )\\n\\n\\n@pytest.mark.unit\\ndef test_entry_legacy_form_kind_property() -> None:\\n    bare = MigrationEntry(\\n        bare_class_name=\\\"X\\\",\\n        target=\\\"ext:bundle_b:X@official\\\",\\n        added_in=\\\"1\\\",\\n    )\\n    assert bare.legacy_form_kind == \\\"bare_class_name\\\"\\n    assert bare.legacy_value == \\\"X\\\"\\n\\n    imp = MigrationEntry(\\n        import_path=\\\"x.y.X\\\",\\n        target=\\\"ext:bundle_b:X@official\\\",\\n        added_in=\\\"1\\\",\\n    )\\n    assert imp.legacy_form_kind == \\\"import_path\\\"\\n    assert imp.legacy_value == \\\"x.y.X\\\"\\n\\n    legacy = MigrationEntry(\\n        legacy_slot=\\\"ext:bundle_b:X@old\\\",\\n        target=\\\"ext:bundle_b:X@official\\\",\\n        added_in=\\\"1\\\",\\n    )\\n    assert legacy.legacy_form_kind == \\\"legacy_slot\\\"\\n    assert legacy.legacy_value == \\\"ext:bundle_b:X@old\\\"\\n\\n\\n@pytest.mark.unit\\ndef test_table_rejects_unsupported_schema_version() -> None:\\n    with pytest.raises(ValidationError):\\n        MigrationTable(schema_version=MIGRATION_SCHEMA_VERSION + 1, entries=[])\\n\\n\\n@pytest.mark.unit\\ndef test_table_rejects_duplicate_legacy_value() -> None:\\n    e1 = MigrationEntry(\\n        bare_class_name=\\\"X\\\",\\n        target=\\\"ext:bundle_a:X@official\\\",\\n        added_in=\\\"1\\\",\\n    )\\n    e2 = MigrationEntry(\\n        bare_class_name=\\\"X\\\",\\n        target=\\\"ext:bundle_b:X@official\\\",\\n        added_in=\\\"1\\\",\\n    )\\n    with pytest.raises(ValidationError):\\n        MigrationTable(schema_version=1, entries=[e1, e2])\\n\\n\\n@pytest.mark.unit\\ndef test_table_lookup_helpers() -> None:\\n    bare = MigrationEntry(\\n        bare_class_name=\\\"MergeDataComponent\\\",\\n        target=\\\"ext:utilities:MergeDataComponent@official\\\",\\n        added_in=\\\"1.10.0\\\",\\n    )\\n    imp = MigrationEntry(\\n        import_path=\\\"langflow.components.utilities.MergeDataComponent\\\",\\n        target=\\\"ext:utilities:MergeDataComponent@official\\\",\\n        added_in=\\\"1.10.0\\\",\\n    )\\n    legacy = MigrationEntry(\\n        legacy_slot=\\\"ext:utilities:MergeDataComponent@official-pre-a\\\",\\n        target=\\\"ext:utilities:MergeDataComponent@official\\\",\\n        added_in=\\\"1.10.0\\\",\\n    )\\n    table = MigrationTable(schema_version=1, entries=[bare, imp, legacy])\\n    assert table.lookup_bare(\\\"MergeDataComponent\\\") is bare\\n    assert table.lookup_bare(\\\"Unknown\\\") is None\\n    assert table.lookup_import_path(\\\"langflow.components.utilities.MergeDataComponent\\\") is imp\\n    assert table.lookup_legacy_slot(\\\"ext:utilities:MergeDataComponent@official-pre-a\\\") is legacy\\n    assert sorted(table.all_known_legacy_values()) == sorted(\\n        [\\n            \\\"MergeDataComponent\\\",\\n            \\\"langflow.components.utilities.MergeDataComponent\\\",\\n            \\\"ext:utilities:MergeDataComponent@official-pre-a\\\",\\n        ]\\n    )\\n\\n\\n@pytest.mark.unit\\ndef test_ambiguous_bare_name_requires_at_least_two_candidates() -> None:\\n    with pytest.raises(ValidationError):\\n        AmbiguousBareName(\\n            name=\\\"MergeDataComponent\\\",\\n            candidates=[\\\"ext:processing:MergeDataComponent@official\\\"],\\n        )\\n\\n\\n@pytest.mark.unit\\ndef test_ambiguous_bare_name_rejects_non_canonical_candidate() -> None:\\n    with pytest.raises(ValidationError):\\n        AmbiguousBareName(\\n            name=\\\"MergeDataComponent\\\",\\n            candidates=[\\n                \\\"ext:processing:MergeDataComponent@official\\\",\\n                \\\"MergeDataComponent\\\",  # not canonical\\n            ],\\n        )\\n\\n\\n@pytest.mark.unit\\ndef test_ambiguous_bare_name_rejects_duplicate_candidates() -> None:\\n    with pytest.raises(ValidationError):\\n        AmbiguousBareName(\\n            name=\\\"MergeDataComponent\\\",\\n            candidates=[\\n                \\\"ext:processing:MergeDataComponent@official\\\",\\n                \\\"ext:processing:MergeDataComponent@official\\\",\\n            ],\\n        )\\n\\n\\n@pytest.mark.unit\\ndef test_table_rejects_collision_between_entries_and_ambiguous_bare_names() -> None:\\n    \\\"\\\"\\\"A bare name cannot be both auto-rewrite and ambiguous.\\n\\n    The auto-rewrite would silently win, so the table validator must\\n    reject the contradiction at load time.\\n    \\\"\\\"\\\"\\n    auto = MigrationEntry(\\n        bare_class_name=\\\"MergeDataComponent\\\",\\n        target=\\\"ext:processing:MergeDataComponent@official\\\",\\n        added_in=\\\"1.10.0\\\",\\n    )\\n    ambig = AmbiguousBareName(\\n        name=\\\"MergeDataComponent\\\",\\n        candidates=[\\n            \\\"ext:processing:MergeDataComponent@official\\\",\\n            \\\"ext:deactivated:MergeDataComponent@official\\\",\\n        ],\\n        added_in=\\\"1.10.0\\\",\\n    )\\n    with pytest.raises(ValidationError):\\n        MigrationTable(\\n            schema_version=1,\\n            entries=[auto],\\n            ambiguous_bare_names=[ambig],\\n        )\\n\\n\\n@pytest.mark.unit\\ndef test_table_rejects_duplicate_ambiguous_bare_names() -> None:\\n    a1 = AmbiguousBareName(\\n        name=\\\"MergeDataComponent\\\",\\n        candidates=[\\n            \\\"ext:processing:MergeDataComponent@official\\\",\\n            \\\"ext:deactivated:MergeDataComponent@official\\\",\\n        ],\\n        added_in=\\\"1.10.0\\\",\\n    )\\n    a2 = AmbiguousBareName(\\n        name=\\\"MergeDataComponent\\\",\\n        candidates=[\\n            \\\"ext:processing:MergeDataComponent@official\\\",\\n            \\\"ext:other:MergeDataComponent@official\\\",\\n        ],\\n        added_in=\\\"1.10.0\\\",\\n    )\\n    with pytest.raises(ValidationError):\\n        MigrationTable(schema_version=1, entries=[], ambiguous_bare_names=[a1, a2])\\n\\n\\n@pytest.mark.unit\\ndef test_table_lookup_ambiguous_bare() -> None:\\n    ambig = AmbiguousBareName(\\n        name=\\\"MergeDataComponent\\\",\\n        candidates=[\\n            \\\"ext:processing:MergeDataComponent@official\\\",\\n            \\\"ext:deactivated:MergeDataComponent@official\\\",\\n        ],\\n        added_in=\\\"1.10.0\\\",\\n    )\\n    table = MigrationTable(schema_version=1, entries=[], ambiguous_bare_names=[ambig])\\n    assert table.lookup_ambiguous_bare(\\\"MergeDataComponent\\\") is ambig\\n    assert table.lookup_ambiguous_bare(\\\"Unknown\\\") is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/test_cli.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"23460711df6f31223e4feeb4adab62fcddc67cd0a34e33e2637208f7ee1a288d\",\"content\":\"\\\"\\\"\\\"End-to-end CLI tests for ``lfx extension validate`` and ``lfx extension schema``.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom typing import TYPE_CHECKING\\n\\nimport pytest\\nfrom lfx.__main__ import app\\nfrom typer.testing import CliRunner\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n_BASE_MANIFEST = {\\n    \\\"id\\\": \\\"lfx-openai\\\",\\n    \\\"version\\\": \\\"1.2.3\\\",\\n    \\\"name\\\": \\\"OpenAI Bundle\\\",\\n    \\\"lfx\\\": {\\\"compat\\\": [\\\"1\\\"]},\\n    \\\"bundles\\\": [{\\\"name\\\": \\\"openai\\\", \\\"path\\\": \\\"openai\\\"}],\\n}\\n\\n\\n_COMPONENT_SRC = (\\n    \\\"class Component:\\\\n\\\"\\n    \\\"    pass\\\\n\\\"\\n    \\\"\\\\n\\\"\\n    \\\"class OpenAIThing(Component):\\\\n\\\"\\n    \\\"    display_name = 'X'\\\\n\\\"\\n    \\\"    def build(self):\\\\n\\\"\\n    \\\"        return None\\\\n\\\"\\n)\\n\\n\\n@pytest.fixture\\ndef runner() -> CliRunner:\\n    # ``mix_stderr=False`` is the historical signature; newer click versions\\n    # emit a deprecation and changed the default behavior.  We accept either.\\n    try:\\n        return CliRunner(mix_stderr=False)  # type: ignore[call-arg]\\n    except TypeError:\\n        return CliRunner()\\n\\n\\n@pytest.fixture\\ndef good_extension(tmp_path: Path) -> Path:\\n    (tmp_path / \\\"extension.json\\\").write_text(json.dumps(_BASE_MANIFEST), encoding=\\\"utf-8\\\")\\n    bundle = tmp_path / \\\"openai\\\"\\n    bundle.mkdir()\\n    (bundle / \\\"text.py\\\").write_text(_COMPONENT_SRC, encoding=\\\"utf-8\\\")\\n    return tmp_path\\n\\n\\ndef test_validate_returns_zero_on_success(runner: CliRunner, good_extension: Path) -> None:\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"validate\\\", str(good_extension)])\\n    assert result.exit_code == 0\\n    assert \\\"ok\\\" in result.stdout.lower()\\n\\n\\ndef test_validate_returns_nonzero_on_failure(runner: CliRunner, tmp_path: Path) -> None:\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"validate\\\", str(tmp_path)])\\n    assert result.exit_code == 1\\n    # Errors render to stderr per the design.\\n    assert \\\"manifest-not-found\\\" in result.stderr\\n\\n\\ndef test_validate_json_output(runner: CliRunner, good_extension: Path) -> None:\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"validate\\\", str(good_extension), \\\"--format\\\", \\\"json\\\"])\\n    assert result.exit_code == 0\\n    payload = json.loads(result.stdout)\\n    assert payload[\\\"ok\\\"] is True\\n    assert payload[\\\"manifest\\\"][\\\"id\\\"] == \\\"lfx-openai\\\"\\n    assert payload[\\\"bundle_files_scanned\\\"] == 1\\n    assert payload[\\\"errors\\\"] == []\\n\\n\\ndef test_validate_json_output_failure(runner: CliRunner, tmp_path: Path) -> None:\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"validate\\\", str(tmp_path), \\\"--format\\\", \\\"json\\\"])\\n    assert result.exit_code == 1\\n    payload = json.loads(result.stdout)\\n    assert payload[\\\"ok\\\"] is False\\n    assert any(e[\\\"code\\\"] == \\\"manifest-not-found\\\" for e in payload[\\\"errors\\\"])\\n\\n\\ndef test_schema_command_writes_to_stdout(runner: CliRunner) -> None:\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"schema\\\"])\\n    assert result.exit_code == 0\\n    payload = json.loads(result.stdout)\\n    assert payload[\\\"$id\\\"].endswith(\\\"/extension/v1.json\\\")\\n\\n\\ndef test_schema_command_writes_to_file(runner: CliRunner, tmp_path: Path) -> None:\\n    out = tmp_path / \\\"schema.json\\\"\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"schema\\\", \\\"-o\\\", str(out)])\\n    assert result.exit_code == 0\\n    assert out.exists()\\n    parsed = json.loads(out.read_text(encoding=\\\"utf-8\\\"))\\n    assert parsed[\\\"$id\\\"].endswith(\\\"/extension/v1.json\\\")\\n\\n\\ndef test_extension_app_help_smoke(runner: CliRunner) -> None:\\n    \\\"\\\"\\\"Ensure the sub-app is mounted and the help renders.\\\"\\\"\\\"\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"--help\\\"])\\n    assert result.exit_code == 0\\n    assert \\\"validate\\\" in result.stdout\\n    assert \\\"schema\\\" in result.stdout\\n    # Authoring commands also appear in help.\\n    assert \\\"init\\\" in result.stdout\\n    assert \\\"dev\\\" in result.stdout\\n\\n\\n# ---------------------------------------------------------------------------\\n# init\\n# ---------------------------------------------------------------------------\\n\\n\\n@pytest.fixture\\ndef isolated_dev_registry(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:\\n    \\\"\\\"\\\"Force the dev registry under a tmp_path subdir so tests don't leak.\\n\\n    Reused by the ``dev`` command tests below; defined here so the same\\n    fixture name is available in both sections.\\n    \\\"\\\"\\\"\\n    state_dir = tmp_path / \\\"_dev_state\\\"\\n    state_dir.mkdir()\\n    monkeypatch.setenv(\\\"LANGFLOW_DEV_EXTENSIONS_DIR\\\", str(state_dir))\\n    return state_dir\\n\\n\\ndef test_init_then_validate_passes_clean(runner: CliRunner, tmp_path: Path) -> None:\\n    \\\"\\\"\\\"AC #1: ``extension init my-ext && extension validate ./my-ext`` is clean.\\\"\\\"\\\"\\n    target = tmp_path / \\\"my-ext\\\"\\n    init_result = runner.invoke(app, [\\\"extension\\\", \\\"init\\\", str(target)])\\n    assert init_result.exit_code == 0, init_result.stderr or init_result.stdout\\n\\n    validate_result = runner.invoke(app, [\\\"extension\\\", \\\"validate\\\", str(target)])\\n    assert validate_result.exit_code == 0, validate_result.stderr or validate_result.stdout\\n    assert \\\"ok\\\" in validate_result.stdout.lower()\\n\\n\\ndef test_init_full_template_fails_cleanly(runner: CliRunner, tmp_path: Path) -> None:\\n    \\\"\\\"\\\"AC #3: ``--template full`` emits typed error and exits non-zero.\\\"\\\"\\\"\\n    target = tmp_path / \\\"my-ext\\\"\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"init\\\", str(target), \\\"--template\\\", \\\"full\\\"])\\n    assert result.exit_code == 1\\n    assert \\\"template-deferred-in-this-milestone\\\" in result.stderr\\n    # Nothing scaffolded.\\n    assert not target.exists() or not any(target.iterdir())\\n\\n\\ndef test_init_refuses_existing_non_empty_directory(runner: CliRunner, tmp_path: Path) -> None:\\n    target = tmp_path / \\\"my-ext\\\"\\n    target.mkdir()\\n    (target / \\\"existing.txt\\\").write_text(\\\"hi\\\", encoding=\\\"utf-8\\\")\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"init\\\", str(target)])\\n    assert result.exit_code == 1\\n    assert \\\"extension-target-exists\\\" in result.stderr\\n    # Existing file untouched.\\n    assert (target / \\\"existing.txt\\\").read_text(encoding=\\\"utf-8\\\") == \\\"hi\\\"\\n\\n\\ndef test_init_accepts_explicit_id_and_name(runner: CliRunner, tmp_path: Path) -> None:\\n    target = tmp_path / \\\"anything-here\\\"\\n    result = runner.invoke(\\n        app,\\n        [\\n            \\\"extension\\\",\\n            \\\"init\\\",\\n            str(target),\\n            \\\"--id\\\",\\n            \\\"custom-id\\\",\\n            \\\"--name\\\",\\n            \\\"My Custom Extension\\\",\\n        ],\\n    )\\n    assert result.exit_code == 0, result.stderr or result.stdout\\n    payload = json.loads((target / \\\"extension.json\\\").read_text(encoding=\\\"utf-8\\\"))\\n    assert payload[\\\"id\\\"] == \\\"custom-id\\\"\\n    assert payload[\\\"name\\\"] == \\\"My Custom Extension\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# dev\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _scaffold_via_cli(runner: CliRunner, tmp_path: Path, name: str = \\\"my-ext\\\") -> Path:\\n    target = tmp_path / name\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"init\\\", str(target)])\\n    assert result.exit_code == 0, result.stderr or result.stdout\\n    return target\\n\\n\\ndef test_dev_skip_launch_registers_extension(\\n    runner: CliRunner,\\n    tmp_path: Path,\\n    isolated_dev_registry: Path,\\n) -> None:\\n    \\\"\\\"\\\"``extension dev --skip-launch`` registers the path and exits cleanly.\\\"\\\"\\\"\\n    target = _scaffold_via_cli(runner, tmp_path)\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"dev\\\", str(target), \\\"--skip-launch\\\"])\\n    assert result.exit_code == 0, result.stderr or result.stdout\\n    assert \\\"Registered dev extension\\\" in result.stdout\\n    # State file written under the isolated dir.\\n    state_file = isolated_dev_registry / \\\"dev_extensions.json\\\"\\n    assert state_file.is_file()\\n    payload = json.loads(state_file.read_text(encoding=\\\"utf-8\\\"))\\n    assert payload[\\\"extensions\\\"][0][\\\"path\\\"] == str(target.resolve())\\n\\n\\ndef test_dev_aborts_on_invalid_extension(\\n    runner: CliRunner,\\n    tmp_path: Path,\\n    isolated_dev_registry: Path,\\n) -> None:\\n    \\\"\\\"\\\"A directory missing a manifest is rejected before registration.\\\"\\\"\\\"\\n    bogus = tmp_path / \\\"bogus\\\"\\n    bogus.mkdir()\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"dev\\\", str(bogus), \\\"--skip-launch\\\"])\\n    assert result.exit_code == 1\\n    assert \\\"manifest-not-found\\\" in result.stderr\\n    # Nothing registered.\\n    state_file = isolated_dev_registry / \\\"dev_extensions.json\\\"\\n    assert not state_file.is_file() or json.loads(state_file.read_text(encoding=\\\"utf-8\\\"))[\\\"extensions\\\"] == []\\n\\n\\ndef test_dev_skip_validate_registers_anyway(\\n    runner: CliRunner,\\n    tmp_path: Path,\\n    isolated_dev_registry: Path,\\n) -> None:\\n    \\\"\\\"\\\"``--skip-validate`` lets the author register a known-broken manifest.\\n\\n    Useful when the author wants to see the loader's runtime error rather\\n    than the static one; tested here to confirm the flag short-circuits\\n    the pre-flight pass.\\n    \\\"\\\"\\\"\\n    target = _scaffold_via_cli(runner, tmp_path)\\n    # Break the manifest so validate would fail.\\n    (target / \\\"extension.json\\\").write_text(\\\"{ not json }\\\", encoding=\\\"utf-8\\\")\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"dev\\\", str(target), \\\"--skip-validate\\\", \\\"--skip-launch\\\"])\\n    assert result.exit_code == 0, result.stderr or result.stdout\\n    state_file = isolated_dev_registry / \\\"dev_extensions.json\\\"\\n    assert state_file.is_file()\\n\\n\\n@pytest.mark.usefixtures(\\\"isolated_dev_registry\\\")\\ndef test_dev_refuses_non_directory(\\n    runner: CliRunner,\\n    tmp_path: Path,\\n) -> None:\\n    bogus = tmp_path / \\\"not-a-dir\\\"\\n    bogus.write_text(\\\"file\\\", encoding=\\\"utf-8\\\")\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"dev\\\", str(bogus), \\\"--skip-launch\\\"])\\n    assert result.exit_code == 1\\n    assert \\\"not a directory\\\" in (result.stderr or result.stdout)\\n\\n\\n# ---------------------------------------------------------------------------\\n# dev launch env: contract for the env vars handed to ``langflow run``\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_dev_launch_env_enables_reload_and_eager_loading() -> None:\\n    \\\"\\\"\\\"The launched langflow inherits flags that make 'edit -> Reload' work.\\n\\n    Without ``LANGFLOW_ENABLE_EXTENSION_RELOAD=true`` the backend reload\\n    handler returns 404 (the runtime guard reads\\n    ``settings.enable_extension_reload``) AND the ``/config`` payload\\n    reports the flag as off, which keeps the packaged frontend from\\n    showing the Reload button.  Without ``LANGFLOW_LAZY_LOAD_COMPONENTS=false``\\n    dev components miss the palette's 5-second budget.\\n    \\\"\\\"\\\"\\n    from lfx.cli._extension_commands import _build_dev_launch_env\\n\\n    env = _build_dev_launch_env({})\\n\\n    assert env[\\\"LANGFLOW_LAZY_LOAD_COMPONENTS\\\"] == \\\"false\\\"\\n    assert env[\\\"LANGFLOW_ENABLE_EXTENSION_RELOAD\\\"] == \\\"true\\\"\\n\\n\\ndef test_dev_launch_env_overrides_author_lazy_loading() -> None:\\n    \\\"\\\"\\\"``LANGFLOW_LAZY_LOAD_COMPONENTS=true`` in the author shell must not win.\\n\\n    The dev workflow always wants eager loading; an author whose shell\\n    exports lazy loading for normal langflow use should not silently\\n    lose dev components from the palette.\\n    \\\"\\\"\\\"\\n    from lfx.cli._extension_commands import _build_dev_launch_env\\n\\n    env = _build_dev_launch_env({\\\"LANGFLOW_LAZY_LOAD_COMPONENTS\\\": \\\"true\\\"})\\n    assert env[\\\"LANGFLOW_LAZY_LOAD_COMPONENTS\\\"] == \\\"false\\\"\\n\\n\\ndef test_dev_launch_env_respects_author_reload_off_path() -> None:\\n    \\\"\\\"\\\"An author testing the off path can pre-export the disable flag.\\n\\n    The reload flag uses setdefault so an explicit ``=false`` exported\\n    in the shell survives the helper's defaulting.\\n    \\\"\\\"\\\"\\n    from lfx.cli._extension_commands import _build_dev_launch_env\\n\\n    env = _build_dev_launch_env({\\\"LANGFLOW_ENABLE_EXTENSION_RELOAD\\\": \\\"false\\\"})\\n    assert env[\\\"LANGFLOW_ENABLE_EXTENSION_RELOAD\\\"] == \\\"false\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# extension reload -- argument validation\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_reload_with_neither_id_nor_all_exits_2(runner: CliRunner) -> None:\\n    \\\"\\\"\\\"No positional id AND no ``--all`` is a usage error.\\\"\\\"\\\"\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"reload\\\"])\\n    assert result.exit_code == 2\\n    msg = result.stderr or result.stdout\\n    # The error message should mention both alternatives so the user\\n    # knows what to do next.\\n    assert \\\"--all\\\" in msg\\n    assert \\\"extension id\\\" in msg\\n\\n\\ndef test_reload_all_rejects_extra_args(runner: CliRunner) -> None:\\n    \\\"\\\"\\\"``--all`` is mutually exclusive with an explicit id / bundle name.\\\"\\\"\\\"\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"reload\\\", \\\"--all\\\", \\\"lfx-pilot\\\"])\\n    assert result.exit_code == 2\\n    msg = result.stderr or result.stdout\\n    assert \\\"--all\\\" in msg\\n\\n\\ndef test_reload_id_not_in_local_discovery_errors_clean(runner: CliRunner, monkeypatch: pytest.MonkeyPatch) -> None:\\n    \\\"\\\"\\\"Error cleanly when the extension is not locally installed.\\n\\n    With --bundle omitted, the CLI exits 1 with a typed message rather\\n    than POSTing with a guessed bundle name.\\n    \\\"\\\"\\\"\\n    # Force discovery to return nothing.\\n    from lfx.cli import _extension_commands as commands\\n\\n    monkeypatch.setattr(\\n        \\\"lfx.extension.discover_all_extensions\\\",\\n        lambda: ([], []),\\n    )\\n    # Defensive: prevent the module-cached reference if any.\\n    monkeypatch.setattr(\\n        commands,\\n        \\\"_post_reload\\\",\\n        lambda **_kwargs: pytest.fail(\\\"should not POST when discovery fails\\\"),\\n    )\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"reload\\\", \\\"lfx-not-installed\\\"])\\n    assert result.exit_code == 1\\n    msg = result.stderr or result.stdout\\n    assert \\\"lfx-not-installed\\\" in msg\\n    assert \\\"--bundle\\\" in msg\\n\\n\\ndef test_reload_multi_bundle_extension_requires_explicit_bundle(\\n    runner: CliRunner,\\n    tmp_path: Path,\\n    monkeypatch: pytest.MonkeyPatch,\\n) -> None:\\n    seed = tmp_path / \\\"seed\\\"\\n    extension = seed / \\\"lfx_datastax\\\"\\n    extension.mkdir(parents=True)\\n    manifest = {\\n        **_BASE_MANIFEST,\\n        \\\"id\\\": \\\"lfx-datastax\\\",\\n        \\\"bundles\\\": [\\n            {\\\"name\\\": \\\"datastax\\\", \\\"path\\\": \\\"datastax\\\"},\\n            {\\\"name\\\": \\\"cassandra\\\", \\\"path\\\": \\\"cassandra\\\"},\\n        ],\\n    }\\n    for bundle in manifest[\\\"bundles\\\"]:\\n        (extension / bundle[\\\"path\\\"]).mkdir()\\n    (extension / \\\"extension.json\\\").write_text(json.dumps(manifest), encoding=\\\"utf-8\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_SEED_DIR\\\", str(seed))\\n    monkeypatch.setattr(\\n        \\\"lfx.cli._extension_commands._post_reload\\\",\\n        lambda **_kwargs: pytest.fail(\\\"should not POST an ambiguous bundle\\\"),\\n    )\\n\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"reload\\\", \\\"lfx-datastax\\\"])\\n\\n    assert result.exit_code == 1\\n    message = result.stderr or result.stdout\\n    assert \\\"cassandra, datastax\\\" in message\\n    assert \\\"--bundle\\\" in message\\n\\n\\ndef test_reload_all_posts_every_bundle_in_multi_bundle_extension(\\n    runner: CliRunner,\\n    tmp_path: Path,\\n    monkeypatch: pytest.MonkeyPatch,\\n) -> None:\\n    from lfx.cli._extension_reload_client import ReloadHttpResponse\\n\\n    seed = tmp_path / \\\"seed\\\"\\n    extension = seed / \\\"lfx_datastax\\\"\\n    extension.mkdir(parents=True)\\n    manifest = {\\n        **_BASE_MANIFEST,\\n        \\\"id\\\": \\\"lfx-datastax\\\",\\n        \\\"bundles\\\": [\\n            {\\\"name\\\": \\\"datastax\\\", \\\"path\\\": \\\"datastax\\\"},\\n            {\\\"name\\\": \\\"cassandra\\\", \\\"path\\\": \\\"cassandra\\\"},\\n        ],\\n    }\\n    for bundle in manifest[\\\"bundles\\\"]:\\n        (extension / bundle[\\\"path\\\"]).mkdir()\\n    (extension / \\\"extension.json\\\").write_text(json.dumps(manifest), encoding=\\\"utf-8\\\")\\n    monkeypatch.setenv(\\\"LANGFLOW_SEED_DIR\\\", str(seed))\\n    posted: list[tuple[str, str]] = []\\n\\n    def _record_post(**kwargs: str | None) -> ReloadHttpResponse:\\n        posted.append((str(kwargs[\\\"extension_id\\\"]), str(kwargs[\\\"bundle_name\\\"])))\\n        return ReloadHttpResponse(status=200, ok=True, payload={\\\"ok\\\": True})\\n\\n    monkeypatch.setattr(\\\"lfx.cli._extension_commands._post_reload\\\", _record_post)\\n\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"reload\\\", \\\"--all\\\", \\\"--format\\\", \\\"json\\\"])\\n\\n    assert result.exit_code == 0, result.stderr or result.stdout\\n    assert posted == [(\\\"lfx-datastax\\\", \\\"datastax\\\"), (\\\"lfx-datastax\\\", \\\"cassandra\\\")]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/test_cli_list.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"263829a61da4718ee4ac93168eaed89b80ccaa6f5003679f4b74063df43dcdff\",\"content\":\"\\\"\\\"\\\"End-to-end CLI tests for ``lfx extension list``.\\n\\nThe list command reads from the live importlib metadata + the\\nseed-directory environment.  We override the seed directory through the\\n``--seed-dir`` flag and avoid touching ``importlib.metadata`` because the\\nunit tests for :mod:`lfx.extension.discovery` already exercise the\\ninstalled-distribution scan with a fake iterator.\\n\\nA separate end-to-end suite (``test_e2e_install.py``) builds real wheels\\nand invokes ``pip install`` to cover the genuine production install\\npath.  This file pins the CLI surface contract; the e2e suite pins the\\ndistribution-discovery contract.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom typing import TYPE_CHECKING\\n\\nimport pytest\\nfrom lfx.__main__ import app\\nfrom typer.testing import CliRunner\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n\\n@pytest.fixture\\ndef runner() -> CliRunner:\\n    try:\\n        return CliRunner(mix_stderr=False)  # type: ignore[call-arg]\\n    except TypeError:\\n        return CliRunner()\\n\\n\\ndef _manifest(extension_id: str, bundle_name: str, version: str = \\\"1.0.0\\\") -> dict[str, object]:\\n    return {\\n        \\\"id\\\": extension_id,\\n        \\\"version\\\": version,\\n        \\\"name\\\": f\\\"{extension_id} bundle\\\",\\n        \\\"lfx\\\": {\\\"compat\\\": [\\\"1\\\"]},\\n        \\\"bundles\\\": [{\\\"name\\\": bundle_name, \\\"path\\\": bundle_name}],\\n    }\\n\\n\\ndef _seed_subdir(seed_root: Path, extension_id: str, bundle_name: str, version: str = \\\"1.0.0\\\") -> None:\\n    sub = seed_root / extension_id.replace(\\\"-\\\", \\\"_\\\")\\n    sub.mkdir(parents=True, exist_ok=True)\\n    (sub / bundle_name).mkdir(exist_ok=True)\\n    (sub / \\\"extension.json\\\").write_text(\\n        json.dumps(_manifest(extension_id, bundle_name, version)),\\n        encoding=\\\"utf-8\\\",\\n    )\\n\\n\\ndef _seed_multi_bundle_subdir(seed_root: Path) -> None:\\n    sub = seed_root / \\\"lfx_datastax\\\"\\n    sub.mkdir(parents=True)\\n    manifest = _manifest(\\\"lfx-datastax\\\", \\\"datastax\\\")\\n    manifest[\\\"bundles\\\"].append({\\\"name\\\": \\\"cassandra\\\", \\\"path\\\": \\\"cassandra\\\"})  # type: ignore[union-attr]\\n    for bundle in manifest[\\\"bundles\\\"]:  # type: ignore[union-attr]\\n        (sub / bundle[\\\"path\\\"]).mkdir()  # type: ignore[index]\\n    (sub / \\\"extension.json\\\").write_text(json.dumps(manifest), encoding=\\\"utf-8\\\")\\n\\n\\ndef test_list_text_output_with_three_seed_bundles(runner: CliRunner, tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Acceptance: three seed bundles all show at @official.\\\"\\\"\\\"\\n    seed = tmp_path / \\\"seed\\\"\\n    seed.mkdir()\\n    for index, bundle in enumerate((\\\"openai\\\", \\\"anthropic\\\", \\\"qdrant\\\")):\\n        _seed_subdir(seed, f\\\"lfx-{bundle}\\\", bundle, version=f\\\"1.{index}.0\\\")\\n\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"list\\\", \\\"--seed-dir\\\", str(seed)])\\n\\n    assert result.exit_code == 0, result.stderr\\n    stdout = result.stdout\\n    # Header is present.\\n    assert \\\"ID\\\" in stdout\\n    assert \\\"VERSION\\\" in stdout\\n    assert \\\"BUNDLE\\\" in stdout\\n    assert \\\"SLOT\\\" in stdout\\n    # All three Extensions render at @official.\\n    for bundle in (\\\"lfx-openai\\\", \\\"lfx-anthropic\\\", \\\"lfx-qdrant\\\"):\\n        assert bundle in stdout\\n    assert stdout.count(\\\"@official\\\") >= 3\\n\\n\\ndef test_list_json_output_with_three_seed_bundles(runner: CliRunner, tmp_path: Path) -> None:\\n    seed = tmp_path / \\\"seed\\\"\\n    seed.mkdir()\\n    for bundle in (\\\"openai\\\", \\\"anthropic\\\", \\\"qdrant\\\"):\\n        _seed_subdir(seed, f\\\"lfx-{bundle}\\\", bundle)\\n\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"list\\\", \\\"--seed-dir\\\", str(seed), \\\"--format\\\", \\\"json\\\"])\\n\\n    assert result.exit_code == 0, result.stderr\\n    payload = json.loads(result.stdout)\\n    assert payload[\\\"errors\\\"] == []\\n    ids = sorted(ext[\\\"id\\\"] for ext in payload[\\\"extensions\\\"])\\n    assert ids == [\\\"lfx-anthropic\\\", \\\"lfx-openai\\\", \\\"lfx-qdrant\\\"]\\n    for ext in payload[\\\"extensions\\\"]:\\n        assert ext[\\\"slot\\\"] == \\\"@official\\\"\\n        assert ext[\\\"source_kind\\\"] == \\\"seed\\\"\\n        assert ext[\\\"auto_update\\\"] is False\\n        assert ext[\\\"load_status\\\"] == \\\"discovered\\\"\\n\\n\\ndef test_list_surfaces_every_bundle_from_one_extension(runner: CliRunner, tmp_path: Path) -> None:\\n    seed = tmp_path / \\\"seed\\\"\\n    seed.mkdir()\\n    _seed_multi_bundle_subdir(seed)\\n\\n    text_result = runner.invoke(app, [\\\"extension\\\", \\\"list\\\", \\\"--seed-dir\\\", str(seed)])\\n    json_result = runner.invoke(app, [\\\"extension\\\", \\\"list\\\", \\\"--seed-dir\\\", str(seed), \\\"--format\\\", \\\"json\\\"])\\n\\n    assert text_result.exit_code == 0, text_result.stderr\\n    assert \\\"datastax, cassandra\\\" in text_result.stdout\\n    assert json_result.exit_code == 0, json_result.stderr\\n    extension = next(item for item in json.loads(json_result.stdout)[\\\"extensions\\\"] if item[\\\"id\\\"] == \\\"lfx-datastax\\\")\\n    assert extension[\\\"bundle\\\"] == \\\"datastax\\\"\\n    assert extension[\\\"bundles\\\"] == [\\\"datastax\\\", \\\"cassandra\\\"]\\n\\n\\ndef test_list_empty_when_no_extensions(runner: CliRunner, tmp_path: Path) -> None:\\n    \\\"\\\"\\\"An empty seed dir + no installed Extensions emits a helpful message.\\n\\n    Note: The current process may have other distributions on the path;\\n    we cannot fully isolate ``importlib.metadata.distributions()``\\n    without monkeypatching, which the CLI surface intentionally does not\\n    expose.  We use ``--seed-dir`` to point at an empty directory and\\n    accept that some pre-existing site-packages distributions may show\\n    up; we only check that the seed pass produced nothing.\\n    \\\"\\\"\\\"\\n    empty = tmp_path / \\\"empty_seed\\\"\\n    empty.mkdir()\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"list\\\", \\\"--seed-dir\\\", str(empty), \\\"--format\\\", \\\"json\\\"])\\n    assert result.exit_code == 0, result.stderr\\n    payload = json.loads(result.stdout)\\n    # The seed pass yielded zero entries.\\n    assert all(ext[\\\"source_kind\\\"] != \\\"seed\\\" for ext in payload[\\\"extensions\\\"])\\n\\n\\ndef test_list_reports_seed_directory_not_found(runner: CliRunner, tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Configured but missing seed dir produces a typed error and non-zero exit.\\\"\\\"\\\"\\n    missing = tmp_path / \\\"does_not_exist\\\"\\n\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"list\\\", \\\"--seed-dir\\\", str(missing)])\\n    assert result.exit_code == 1\\n    assert \\\"seed-directory-not-found\\\" in result.stderr\\n\\n\\ndef test_list_reports_malformed_manifest(runner: CliRunner, tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A malformed seed-directory manifest surfaces ``manifest-invalid``.\\\"\\\"\\\"\\n    seed = tmp_path / \\\"seed\\\"\\n    bad = seed / \\\"lfx_broken\\\"\\n    bad.mkdir(parents=True)\\n    (bad / \\\"extension.json\\\").write_text(\\\"{ not json\\\", encoding=\\\"utf-8\\\")\\n    # Healthy neighbour to confirm partial output still works.\\n    _seed_subdir(seed, \\\"lfx-openai\\\", \\\"openai\\\")\\n\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"list\\\", \\\"--seed-dir\\\", str(seed)])\\n    assert result.exit_code == 1\\n    assert \\\"lfx-openai\\\" in result.stdout\\n    assert \\\"manifest-invalid\\\" in result.stderr\\n\\n\\ndef test_list_rejects_invalid_format(runner: CliRunner, tmp_path: Path) -> None:\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"list\\\", \\\"--seed-dir\\\", str(tmp_path), \\\"--format\\\", \\\"yaml\\\"])\\n    assert result.exit_code == 2\\n    assert \\\"Invalid --format\\\" in result.stderr\\n\\n\\ndef test_list_appears_in_extension_help(runner: CliRunner) -> None:\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"--help\\\"])\\n    assert result.exit_code == 0\\n    assert \\\"list\\\" in result.stdout\\n\\n\\ndef test_list_text_output_includes_interpreter_info(runner: CliRunner, tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Operators hit the wrong-venv footgun when ``lfx`` and ``langflow run`` diverge.\\n\\n    Printing the interpreter at the top of the listing turns \\\"my bundle didn't\\n    install\\\" into a one-glance fix.\\n    \\\"\\\"\\\"\\n    import sys\\n\\n    seed = tmp_path / \\\"seed\\\"\\n    seed.mkdir()\\n    _seed_subdir(seed, \\\"lfx-openai\\\", \\\"openai\\\")\\n\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"list\\\", \\\"--seed-dir\\\", str(seed)])\\n    assert result.exit_code == 0, result.stderr\\n    assert \\\"python:\\\" in result.stdout\\n    assert sys.executable in result.stdout\\n    assert \\\"sys.prefix:\\\" in result.stdout\\n\\n\\ndef test_list_json_output_includes_interpreter_info(runner: CliRunner, tmp_path: Path) -> None:\\n    import sys\\n\\n    empty = tmp_path / \\\"empty_seed\\\"\\n    empty.mkdir()\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"list\\\", \\\"--seed-dir\\\", str(empty), \\\"--format\\\", \\\"json\\\"])\\n    assert result.exit_code == 0, result.stderr\\n    payload = json.loads(result.stdout)\\n    assert payload[\\\"interpreter\\\"][\\\"executable\\\"] == sys.executable\\n    assert payload[\\\"interpreter\\\"][\\\"prefix\\\"] == sys.prefix\\n\\n\\ndef test_list_exits_zero_when_only_warning_is_seed_bundle_shadowed(\\n    runner: CliRunner, tmp_path: Path, monkeypatch: pytest.MonkeyPatch\\n) -> None:\\n    \\\"\\\"\\\"``seed-bundle-shadowed`` is a warning, not a discovery failure.\\n\\n    Any CI script doing ``lfx extension list && ...`` would otherwise break\\n    the moment an operator pip-installs a bundle that also ships in a seed\\n    directory.  The warning still appears on stderr; the exit code stays 0.\\n    \\\"\\\"\\\"\\n    from lfx.extension.errors import ExtensionError\\n\\n    seed = tmp_path / \\\"seed\\\"\\n    seed.mkdir()\\n    _seed_subdir(seed, \\\"lfx-openai\\\", \\\"openai\\\")\\n\\n    real_discover_all = __import__(\\\"lfx.extension\\\", fromlist=[\\\"discover_all_extensions\\\"]).discover_all_extensions\\n\\n    def _shadowed_discovery(seed_dir_env: str | None = None):\\n        extensions, errors = real_discover_all(seed_dir_env=seed_dir_env)\\n        errors = [\\n            *errors,\\n            ExtensionError(\\n                code=\\\"seed-bundle-shadowed\\\",\\n                message=\\\"seed bundle 'openai' is shadowed by an installed Extension of the same name\\\",\\n                location=str(seed / \\\"lfx_openai\\\"),\\n                content=\\\"openai\\\",\\n                hint=\\\"remove the seed copy or uninstall the pip distribution\\\",\\n            ),\\n        ]\\n        return extensions, errors\\n\\n    # The CLI command imports ``discover_all_extensions`` from ``lfx.extension``\\n    # at call time, so patching that name suffices.\\n    monkeypatch.setattr(\\\"lfx.extension.discover_all_extensions\\\", _shadowed_discovery)\\n\\n    result = runner.invoke(app, [\\\"extension\\\", \\\"list\\\", \\\"--seed-dir\\\", str(seed)])\\n    assert result.exit_code == 0, result.stderr\\n    assert \\\"seed-bundle-shadowed\\\" in result.stderr\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/test_components_cache_integration.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"165a08572111f7d789725d355784f17c05370a828bb5af0b1318e48b61e2bd89\",\"content\":\"\\\"\\\"\\\"Integration tests for the Extension System -> /all cache wiring.\\n\\nVerifies that ``import_extension_components`` produces a dict shaped like\\n``{bundle_name: {class_name: template}}`` with ``extension``, ``bundle``,\\nand ``extension_version`` populated -- the AC for ``/api/v1/all``\\nvisibility.\\n\\nThe toy Component classes used by the loader's other test fixtures don't\\ninherit from the real ``lfx.custom.custom_component.component.Component``\\nbase, so ``create_component_template`` fails on them. We exercise that\\n\\\"skip on template-build failure\\\" path AND patch the template-builder for a\\npositive assertion that the fields are stamped onto the produced template.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport hashlib\\nimport os\\nfrom threading import Event, Thread\\nfrom types import SimpleNamespace\\nfrom typing import TYPE_CHECKING, Any\\nfrom unittest.mock import AsyncMock, patch\\n\\nimport pytest\\nfrom lfx.interface.components import (\\n    _decorate_template_with_extension,\\n    import_extension_components,\\n)\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n\\nclass _FakeSettings:\\n    components_path: list[str]\\n\\n\\nclass _FakeSettingsService:\\n    def __init__(self, components_path: list[str] | None = None) -> None:\\n        self.settings = _FakeSettings()\\n        self.settings.components_path = components_path or []\\n\\n\\ndef _stub_template(*_args, **_kwargs) -> tuple[dict[str, Any], object]:\\n    \\\"\\\"\\\"Stand-in for ``create_component_template`` that returns a minimal dict.\\n\\n    Mirrors the shape downstream consumers depend on: a ``display_name``\\n    plus the field set the cache merges. The instance is unused by the\\n    decorator, so a sentinel object is sufficient.\\n    \\\"\\\"\\\"\\n    return ({\\\"display_name\\\": \\\"Stub\\\", \\\"type\\\": \\\"stub\\\", \\\"template\\\": {}}, object())\\n\\n\\n@pytest.mark.asyncio\\nasync def test_component_cache_initialization_is_single_flight_and_atomic() -> None:\\n    \\\"\\\"\\\"Concurrent callers share one load and never observe a partial registry.\\\"\\\"\\\"\\n    from lfx.interface import components as components_module\\n\\n    cache = components_module.ComponentCache()\\n    cache.type_to_code = {\\\"StaleComponent\\\": \\\"# stale trusted code\\\"}\\n    settings_service = SimpleNamespace(settings=SimpleNamespace())\\n    trusted_code = \\\"# trusted ChatInput code\\\"\\n    code_hash = hashlib.sha256(trusted_code.encode()).hexdigest()[:12]\\n    builtins = {\\n        \\\"components\\\": {\\n            \\\"input_output\\\": {\\n                \\\"ChatInput\\\": {\\n                    \\\"display_name\\\": \\\"Chat Input\\\",\\n                    \\\"metadata\\\": {\\\"code_hash\\\": code_hash},\\n                    \\\"template\\\": {\\\"_type\\\": \\\"Component\\\", \\\"code\\\": {\\\"value\\\": trusted_code}},\\n                }\\n            }\\n        }\\n    }\\n    load_started = asyncio.Event()\\n    release_load = asyncio.Event()\\n\\n    async def load_builtins(*_args, **_kwargs):\\n        load_started.set()\\n        await release_load.wait()\\n        return builtins\\n\\n    with (\\n        patch.object(components_module, \\\"component_cache\\\", cache),\\n        patch.object(components_module, \\\"import_langflow_components\\\", new=AsyncMock(side_effect=load_builtins)) as load,\\n        patch.object(components_module, \\\"_determine_loading_strategy\\\", new=AsyncMock(return_value={})),\\n        patch.object(components_module, \\\"import_extension_components\\\", new=AsyncMock(return_value={})),\\n    ):\\n        leader = asyncio.create_task(components_module.get_and_cache_all_types_dict(settings_service))\\n        await asyncio.wait_for(load_started.wait(), timeout=2)\\n        follower = asyncio.create_task(components_module.get_and_cache_all_types_dict(settings_service))\\n        await asyncio.sleep(0)\\n\\n        with cache.state_lock:\\n            assert cache.all_types_dict is None\\n            assert not cache.all_types_ready\\n            assert cache.type_to_current_hash is None\\n            assert cache.code_by_hash is None\\n            assert cache.type_to_code is None\\n            assert cache.component_identity_index is None\\n        assert not follower.done()\\n\\n        release_load.set()\\n        leader_result, follower_result = await asyncio.wait_for(asyncio.gather(leader, follower), timeout=2)\\n\\n    assert load.await_count == 1\\n    assert leader_result is follower_result\\n    assert leader_result is cache.all_types_dict\\n    assert cache.all_types_ready\\n    assert cache.type_to_current_hash == {\\\"ChatInput\\\": {code_hash}, \\\"Chat Input\\\": {code_hash}}\\n    assert cache.code_by_hash == {code_hash: trusted_code}\\n    assert cache.type_to_code == {\\\"ChatInput\\\": trusted_code, \\\"Chat Input\\\": trusted_code}\\n    assert cache.component_identity_index is not None\\n    assert cache.component_identity_index.resolve(\\\"Chat Input\\\") == frozenset({\\\"ChatInput\\\"})\\n\\n\\n@pytest.mark.asyncio\\nasync def test_cancelled_initiating_caller_does_not_cancel_shared_initialization() -> None:\\n    \\\"\\\"\\\"Cancelling the caller that elected initialization must not strand followers.\\\"\\\"\\\"\\n    from lfx.interface import components as components_module\\n\\n    cache = components_module.ComponentCache()\\n    settings_service = SimpleNamespace(settings=SimpleNamespace())\\n    builtins = {\\n        \\\"components\\\": {\\n            \\\"input_output\\\": {\\n                \\\"ChatInput\\\": {\\n                    \\\"display_name\\\": \\\"Chat Input\\\",\\n                    \\\"template\\\": {\\\"_type\\\": \\\"Component\\\"},\\n                }\\n            }\\n        }\\n    }\\n    load_started = asyncio.Event()\\n    release_load = asyncio.Event()\\n\\n    async def load_builtins(*_args, **_kwargs):\\n        load_started.set()\\n        await release_load.wait()\\n        return builtins\\n\\n    with (\\n        patch.object(components_module, \\\"component_cache\\\", cache),\\n        patch.object(components_module, \\\"import_langflow_components\\\", new=AsyncMock(side_effect=load_builtins)) as load,\\n        patch.object(components_module, \\\"_determine_loading_strategy\\\", new=AsyncMock(return_value={})),\\n        patch.object(components_module, \\\"import_extension_components\\\", new=AsyncMock(return_value={})),\\n    ):\\n        initiating_caller = asyncio.create_task(components_module.get_and_cache_all_types_dict(settings_service))\\n        await asyncio.wait_for(load_started.wait(), timeout=2)\\n        follower = asyncio.create_task(components_module.get_and_cache_all_types_dict(settings_service))\\n        await asyncio.sleep(0)\\n\\n        with cache.state_lock:\\n            initialization_task = cache.initialization_task\\n            initialization_future = cache.initialization_future\\n        assert initialization_task is not None\\n        assert initialization_task is not initiating_caller\\n        assert initialization_future is not None\\n\\n        initiating_caller.cancel()\\n        with pytest.raises(asyncio.CancelledError):\\n            await initiating_caller\\n\\n        assert not initialization_task.done()\\n        assert not initialization_future.cancelled()\\n        assert not follower.done()\\n\\n        release_load.set()\\n        follower_result = await asyncio.wait_for(follower, timeout=2)\\n\\n    load.assert_awaited_once_with(settings_service, None)\\n    assert follower_result is cache.all_types_dict\\n    assert cache.all_types_ready\\n    assert cache.initialization_future is None\\n    assert cache.initialization_task is None\\n\\n\\n@pytest.mark.asyncio\\nasync def test_failed_background_initialization_cleans_state_and_can_retry() -> None:\\n    \\\"\\\"\\\"Initializer failure reaches its caller and leaves no stale single-flight state.\\\"\\\"\\\"\\n    from lfx.interface import components as components_module\\n\\n    cache = components_module.ComponentCache()\\n    settings_service = SimpleNamespace(settings=SimpleNamespace())\\n    builtins = {\\\"components\\\": {}}\\n\\n    with (\\n        patch.object(components_module, \\\"component_cache\\\", cache),\\n        patch.object(\\n            components_module,\\n            \\\"import_langflow_components\\\",\\n            new=AsyncMock(side_effect=[RuntimeError(\\\"component import failed\\\"), builtins]),\\n        ) as load,\\n        patch.object(components_module, \\\"_determine_loading_strategy\\\", new=AsyncMock(return_value={})),\\n        patch.object(components_module, \\\"import_extension_components\\\", new=AsyncMock(return_value={})),\\n    ):\\n        with pytest.raises(RuntimeError, match=\\\"component import failed\\\"):\\n            await components_module.get_and_cache_all_types_dict(settings_service)\\n\\n        with cache.state_lock:\\n            assert cache.initialization_future is None\\n            assert cache.initialization_task is None\\n            assert not cache.pending_bundle_updates\\n\\n        assert await components_module.get_and_cache_all_types_dict(settings_service) == {}\\n\\n    assert load.await_count == 2\\n    assert cache.all_types_ready\\n\\n\\n@pytest.mark.asyncio\\nasync def test_cancelled_background_initialization_cleans_shared_state() -> None:\\n    \\\"\\\"\\\"Explicit initializer cancellation wakes waiters and clears retry state.\\\"\\\"\\\"\\n    from lfx.interface import components as components_module\\n\\n    cache = components_module.ComponentCache()\\n    settings_service = SimpleNamespace(settings=SimpleNamespace())\\n    load_started = asyncio.Event()\\n\\n    async def load_builtins(*_args, **_kwargs):\\n        load_started.set()\\n        await asyncio.Event().wait()\\n\\n    with (\\n        patch.object(components_module, \\\"component_cache\\\", cache),\\n        patch.object(components_module, \\\"import_langflow_components\\\", new=AsyncMock(side_effect=load_builtins)),\\n    ):\\n        caller = asyncio.create_task(components_module.get_and_cache_all_types_dict(settings_service))\\n        await asyncio.wait_for(load_started.wait(), timeout=2)\\n        with cache.state_lock:\\n            initialization_task = cache.initialization_task\\n        assert initialization_task is not None\\n\\n        initialization_task.cancel()\\n        with pytest.raises(asyncio.CancelledError):\\n            await asyncio.wait_for(caller, timeout=2)\\n\\n    with cache.state_lock:\\n        assert cache.initialization_future is None\\n        assert cache.initialization_task is None\\n        assert not cache.pending_bundle_updates\\n\\n\\n@pytest.mark.asyncio\\nasync def test_reload_completed_during_initialization_wins_at_atomic_publication(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A post-swap reload cannot be overwritten by stale in-flight discovery.\\\"\\\"\\\"\\n    from lfx.extension.bundle_registry import BundleRecord\\n    from lfx.extension.loader._types import LoadedComponent\\n    from lfx.interface import components as components_module\\n\\n    cache = components_module.ComponentCache()\\n    settings_service = SimpleNamespace(settings=SimpleNamespace())\\n    stale_id = \\\"ext:delta:OldThing@official\\\"\\n    current_id = \\\"ext:delta:DeltaThing@official\\\"\\n    stale_extension = {\\n        \\\"delta\\\": {\\n            stale_id: {\\n                \\\"name\\\": \\\"OldThing\\\",\\n                \\\"display_name\\\": \\\"Old Thing\\\",\\n                \\\"template\\\": {\\\"_type\\\": \\\"Component\\\"},\\n            }\\n        }\\n    }\\n    stale_discovery_ready = asyncio.Event()\\n    release_discovery = asyncio.Event()\\n\\n    async def load_stale_extension(_settings_service):\\n        stale_discovery_ready.set()\\n        await release_discovery.wait()\\n        return stale_extension\\n\\n    class _DeltaThing:\\n        display_name = \\\"Delta\\\"\\n\\n        def build(self) -> None:\\n            return None\\n\\n    record = BundleRecord(\\n        bundle=\\\"delta\\\",\\n        extension_id=\\\"lfx-delta\\\",\\n        extension_version=\\\"1.0.0\\\",\\n        slot=\\\"official\\\",\\n        components=(\\n            LoadedComponent(\\n                extension_id=\\\"lfx-delta\\\",\\n                extension_version=\\\"1.0.0\\\",\\n                bundle=\\\"delta\\\",\\n                class_name=\\\"DeltaThing\\\",\\n                slot=\\\"official\\\",\\n                klass=_DeltaThing,\\n                module_name=\\\"_lfx_ext.official.delta.thing\\\",\\n                file_path=tmp_path / \\\"thing.py\\\",\\n                distribution=None,\\n            ),\\n        ),\\n    )\\n\\n    with (\\n        patch.object(components_module, \\\"component_cache\\\", cache),\\n        patch.object(\\n            components_module,\\n            \\\"import_langflow_components\\\",\\n            new=AsyncMock(return_value={\\\"components\\\": {}}),\\n        ),\\n        patch.object(components_module, \\\"_determine_loading_strategy\\\", new=AsyncMock(return_value={})),\\n        patch.object(\\n            components_module,\\n            \\\"import_extension_components\\\",\\n            new=AsyncMock(side_effect=load_stale_extension),\\n        ),\\n        patch.object(components_module, \\\"create_component_template\\\", side_effect=_stub_template),\\n    ):\\n        initialization = asyncio.create_task(components_module.get_and_cache_all_types_dict(settings_service))\\n        await asyncio.wait_for(stale_discovery_ready.wait(), timeout=2)\\n\\n        components_module.refresh_bundle_cache_from_record(record)\\n        with cache.state_lock:\\n            assert current_id in cache.pending_bundle_updates[\\\"delta\\\"]\\n            assert cache.all_types_dict is None\\n\\n        release_discovery.set()\\n        result = await asyncio.wait_for(initialization, timeout=2)\\n\\n    assert current_id in result[\\\"delta\\\"]\\n    assert stale_id not in result[\\\"delta\\\"]\\n    assert result is cache.all_types_dict\\n    assert cache.component_identity_index is not None\\n    assert cache.component_identity_index.resolve(\\\"DeltaThing\\\") == frozenset({current_id})\\n\\n\\ndef test_decorate_template_stamps_required_fields() -> None:\\n    \\\"\\\"\\\"The AC fields land on the template dict as top-level keys.\\\"\\\"\\\"\\n    template = {\\\"display_name\\\": \\\"X\\\"}\\n    decorated = _decorate_template_with_extension(\\n        template,\\n        extension_id=\\\"lfx-pilot\\\",\\n        bundle=\\\"pilot\\\",\\n        extension_version=\\\"1.2.3\\\",\\n        namespaced_id=\\\"ext:pilot:PilotThing@official\\\",\\n    )\\n    assert decorated[\\\"extension\\\"] == \\\"lfx-pilot\\\"\\n    assert decorated[\\\"bundle\\\"] == \\\"pilot\\\"\\n    assert decorated[\\\"extension_version\\\"] == \\\"1.2.3\\\"\\n    assert decorated[\\\"namespaced_id\\\"] == \\\"ext:pilot:PilotThing@official\\\"\\n    # Existing keys are preserved.\\n    assert decorated[\\\"display_name\\\"] == \\\"X\\\"\\n\\n\\ndef test_decorate_template_stamps_legacy_name() -> None:\\n    \\\"\\\"\\\"``legacy_name`` lands as ``template[\\\"name\\\"]``.\\n\\n    It is the bridge both alias maps (frontend getTemplateAliases, lfx\\n    component_aliases) use to resolve pre-move node types like ``AstraDB``\\n    whose saved ``type`` is the component's ``name`` attribute, not its\\n    class name.\\n    \\\"\\\"\\\"\\n    decorated = _decorate_template_with_extension(\\n        {\\\"display_name\\\": \\\"X\\\"},\\n        extension_id=\\\"lfx-pilot\\\",\\n        bundle=\\\"pilot\\\",\\n        extension_version=\\\"1.2.3\\\",\\n        namespaced_id=\\\"ext:pilot:PilotThing@official\\\",\\n        legacy_name=\\\"AstraDB\\\",\\n    )\\n    assert decorated[\\\"name\\\"] == \\\"AstraDB\\\"\\n\\n\\ndef test_decorate_template_never_overrides_existing_name() -> None:\\n    decorated = _decorate_template_with_extension(\\n        {\\\"display_name\\\": \\\"X\\\", \\\"name\\\": \\\"Original\\\"},\\n        extension_id=\\\"lfx-pilot\\\",\\n        bundle=\\\"pilot\\\",\\n        extension_version=\\\"1.2.3\\\",\\n        namespaced_id=\\\"ext:pilot:PilotThing@official\\\",\\n        legacy_name=\\\"AstraDB\\\",\\n    )\\n    assert decorated[\\\"name\\\"] == \\\"Original\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_import_extension_components_returns_empty_when_nothing_to_load() -> None:\\n    \\\"\\\"\\\"No installed extensions and no inline paths -> empty mapping.\\\"\\\"\\\"\\n    settings_service = _FakeSettingsService(components_path=[])\\n    result = await import_extension_components(settings_service)\\n    assert result == {}\\n\\n\\n@pytest.mark.asyncio\\nasync def test_inline_bundle_components_decorated_with_extension_metadata(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"End-to-end: an inline bundle directory produces decorated templates.\\n\\n    Uses a stubbed ``create_component_template`` so the test doesn't\\n    require the real heavyweight Component base. The loader's discovery\\n    layer is exercised for real.\\n    \\\"\\\"\\\"\\n    parent = tmp_path / \\\"components_root\\\"\\n    bundle_dir = parent / \\\"alpha\\\"\\n    bundle_dir.mkdir(parents=True)\\n    (bundle_dir / \\\"thing.py\\\").write_text(\\n        \\\"class Component:\\\\n    pass\\\\n\\\"\\n        \\\"class AlphaThing(Component):\\\\n\\\"\\n        \\\"    display_name = 'Alpha'\\\\n\\\"\\n        \\\"    def build(self):\\\\n        return None\\\\n\\\",\\n        encoding=\\\"utf-8\\\",\\n    )\\n\\n    settings_service = _FakeSettingsService(components_path=[str(parent)])\\n\\n    with patch(\\\"lfx.interface.components.create_component_template\\\", side_effect=_stub_template):\\n        result = await import_extension_components(settings_service)\\n\\n    assert \\\"alpha\\\" in result\\n    # AC: components are registered under ``ext:<bundle>:<Class>@<slot>``,\\n    # NOT under the bare class name.\\n    expected_id = \\\"ext:alpha:AlphaThing@extra\\\"\\n    assert expected_id in result[\\\"alpha\\\"], (\\n        f\\\"Expected namespaced ID {expected_id!r} as dict key; got {list(result['alpha'])}\\\"\\n    )\\n    assert \\\"AlphaThing\\\" not in result[\\\"alpha\\\"], (\\n        \\\"Bare class name must NOT be the registry key (would collide with built-in IDs)\\\"\\n    )\\n    template = result[\\\"alpha\\\"][expected_id]\\n    assert template[\\\"bundle\\\"] == \\\"alpha\\\"\\n    assert template[\\\"extension\\\"]  # id derived from bundle.json or default\\n    assert template[\\\"extension_version\\\"]  # default \\\"0.0.0\\\" when no bundle.json\\n    assert template[\\\"namespaced_id\\\"] == expected_id\\n    # The legacy in-tree identity (name attr falling back to class name) is\\n    # carried in the template value so saved flows' node types still resolve.\\n    assert template[\\\"name\\\"] == \\\"AlphaThing\\\"\\n    # The source file's stem is the *other* key the legacy custom scanner can use\\n    # for this component: lazy metadata loading never imports the file, so it names\\n    # the entry after the file. Carried so the cache merge can retire that stub.\\n    assert template[\\\"legacy_module\\\"] == \\\"thing\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_template_failure_skips_component_without_aborting_bundle(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A class that fails to instantiate / template doesn't abort the bundle.\\n\\n    The toy ``Component`` base in the source file lacks the heavyweight\\n    machinery that ``create_component_template`` needs, so the real builder\\n    raises -- this is the \\\"skip with logged warning\\\" path. We let it run\\n    without the stub to verify the defensive try/except.\\n    \\\"\\\"\\\"\\n    parent = tmp_path / \\\"components_root\\\"\\n    bundle_dir = parent / \\\"alpha\\\"\\n    bundle_dir.mkdir(parents=True)\\n    (bundle_dir / \\\"thing.py\\\").write_text(\\n        \\\"class Component:\\\\n    pass\\\\n\\\"\\n        \\\"class AlphaThing(Component):\\\\n\\\"\\n        \\\"    display_name = 'Alpha'\\\\n\\\"\\n        \\\"    def build(self):\\\\n        return None\\\\n\\\",\\n        encoding=\\\"utf-8\\\",\\n    )\\n\\n    settings_service = _FakeSettingsService(components_path=[str(parent)])\\n    # No patch: real create_component_template will raise for the toy class.\\n    result = await import_extension_components(settings_service)\\n    # Bundle is registered, but no class survives template build.\\n    assert result == {} or result.get(\\\"alpha\\\") == {}\\n\\n\\n@pytest.mark.asyncio\\nasync def test_components_path_empty_string_does_not_crash(monkeypatch) -> None:\\n    \\\"\\\"\\\"Pathsep parsing edge case: empty segments don't break the inline walk.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_COMPONENTS_PATH\\\", os.pathsep)\\n    settings_service = _FakeSettingsService(components_path=[])\\n    # No patch needed -- there's nothing to load.\\n    result = await import_extension_components(settings_service)\\n    assert result == {}\\n\\n\\n@pytest.mark.asyncio\\nasync def test_seed_directory_bundle_loads_at_official_slot(tmp_path: Path, monkeypatch) -> None:\\n    \\\"\\\"\\\"A subdirectory under ``$LANGFLOW_SEED_DIR`` registers at @official.\\n\\n    This is the second production-install source documented in the\\n    deployment guide.  Without the startup wiring, an operator who copies\\n    bundles into ``/opt/langflow/bundles/`` (the Mode B/C alternative to\\n    ``pip install``) sees the docs say it works while no components actually\\n    appear in the palette.\\n    \\\"\\\"\\\"\\n    import json\\n\\n    from lfx.extension.bundle_registry import BundleRegistry\\n\\n    seed_root = tmp_path / \\\"seed-bundles\\\"\\n    extension_root = seed_root / \\\"lfx-pilot\\\"\\n    bundle_dir = extension_root / \\\"components\\\"\\n    bundle_dir.mkdir(parents=True)\\n\\n    manifest = {\\n        \\\"id\\\": \\\"lfx-pilot\\\",\\n        \\\"version\\\": \\\"1.0.0\\\",\\n        \\\"name\\\": \\\"Pilot\\\",\\n        \\\"lfx\\\": {\\\"compat\\\": [\\\"1\\\"]},\\n        \\\"bundles\\\": [{\\\"name\\\": \\\"pilot\\\", \\\"path\\\": \\\"components\\\"}],\\n    }\\n    (extension_root / \\\"extension.json\\\").write_text(json.dumps(manifest), encoding=\\\"utf-8\\\")\\n    (bundle_dir / \\\"thing.py\\\").write_text(\\n        \\\"class Component:\\\\n    pass\\\\n\\\"\\n        \\\"class PilotThing(Component):\\\\n\\\"\\n        \\\"    display_name = 'Pilot'\\\\n\\\"\\n        \\\"    def build(self):\\\\n        return None\\\\n\\\",\\n        encoding=\\\"utf-8\\\",\\n    )\\n\\n    monkeypatch.setenv(\\\"LANGFLOW_SEED_DIR\\\", str(seed_root))\\n\\n    fresh_registry = BundleRegistry()\\n    settings_service = _FakeSettingsService(components_path=[])\\n\\n    with (\\n        patch(\\\"lfx.interface.components.create_component_template\\\", side_effect=_stub_template),\\n        patch(\\\"lfx.interface.components.get_default_registry\\\", return_value=fresh_registry),\\n    ):\\n        result = await import_extension_components(settings_service)\\n\\n    # Bundle is visible in /api/v1/all\\n    assert \\\"pilot\\\" in result, f\\\"seed bundle missing from cache; got {list(result)}\\\"\\n    expected_id = \\\"ext:pilot:PilotThing@official\\\"\\n    assert expected_id in result[\\\"pilot\\\"]\\n    template = result[\\\"pilot\\\"][expected_id]\\n    assert template[\\\"bundle\\\"] == \\\"pilot\\\"\\n    assert template[\\\"extension\\\"] == \\\"lfx-pilot\\\"\\n    # @official bundles live outside LANGFLOW_COMPONENTS_PATH, so the legacy custom\\n    # scanner never produces a copy of them -- carrying the file-stem alias here\\n    # could only evict an unrelated same-named custom component.\\n    assert \\\"legacy_module\\\" not in template\\n\\n    # Bundle is in the BundleRegistry so reload + the events pipeline can find it.\\n    record = fresh_registry.get_bundle(\\\"pilot\\\")\\n    assert record is not None\\n    assert record.slot == \\\"official\\\"\\n    assert record.extension_id == \\\"lfx-pilot\\\"\\n    assert \\\"PilotThing\\\" in record.class_names\\n\\n\\n@pytest.mark.asyncio\\nasync def test_seed_bundle_shadowed_by_installed_emits_typed_warning(tmp_path: Path, monkeypatch) -> None:\\n    \\\"\\\"\\\"When an installed pip dist shadows a same-named seed bundle, installed wins.\\n\\n    Per the deployment doc, installed pip distributions take precedence; the\\n    seed copy is dropped and a typed ``seed-bundle-shadowed`` warning\\n    is appended to the seed result so the diagnostics emitter surfaces the\\n    misconfiguration.  This test asserts both halves: installed wins in the\\n    BundleRegistry, AND the typed warning is attached to the seed result that\\n    flows through ``_emit_extension_diagnostics``.\\n    \\\"\\\"\\\"\\n    import json\\n\\n    from lfx.extension.bundle_registry import BundleRegistry\\n\\n    # Build a seed-directory bundle of the same name as the (faked) install.\\n    seed_root = tmp_path / \\\"seed-bundles\\\"\\n    extension_root = seed_root / \\\"lfx-pilot\\\"\\n    bundle_dir = extension_root / \\\"components\\\"\\n    bundle_dir.mkdir(parents=True)\\n    manifest = {\\n        \\\"id\\\": \\\"lfx-pilot\\\",\\n        \\\"version\\\": \\\"0.0.1-seed\\\",\\n        \\\"name\\\": \\\"Pilot (seed)\\\",\\n        \\\"lfx\\\": {\\\"compat\\\": [\\\"1\\\"]},\\n        \\\"bundles\\\": [{\\\"name\\\": \\\"pilot\\\", \\\"path\\\": \\\"components\\\"}],\\n    }\\n    (extension_root / \\\"extension.json\\\").write_text(json.dumps(manifest), encoding=\\\"utf-8\\\")\\n    (bundle_dir / \\\"thing.py\\\").write_text(\\n        \\\"class Component:\\\\n    pass\\\\n\\\"\\n        \\\"class PilotThing(Component):\\\\n\\\"\\n        \\\"    display_name = 'Seed Pilot'\\\\n\\\"\\n        \\\"    def build(self):\\\\n        return None\\\\n\\\",\\n        encoding=\\\"utf-8\\\",\\n    )\\n    monkeypatch.setenv(\\\"LANGFLOW_SEED_DIR\\\", str(seed_root))\\n\\n    # Build an installed-pkg LoadResult by hand (test seam: stub\\n    # load_installed_extensions to return a result for bundle \\\"pilot\\\").\\n    from lfx.extension.loader._types import LoadedComponent, LoadResult\\n\\n    class _Component:\\n        pass\\n\\n    class _InstalledPilotThing(_Component):\\n        display_name = \\\"Installed Pilot\\\"\\n\\n        def build(self) -> None:\\n            return None\\n\\n    installed_loaded = LoadedComponent(\\n        extension_id=\\\"lfx-pilot\\\",\\n        extension_version=\\\"2.0.0\\\",\\n        bundle=\\\"pilot\\\",\\n        class_name=\\\"PilotThing\\\",\\n        slot=\\\"official\\\",\\n        klass=_InstalledPilotThing,\\n        module_name=\\\"_lfx_ext.official.pilot.thing\\\",\\n        file_path=tmp_path / \\\"installed_thing.py\\\",\\n        distribution=\\\"lfx-pilot\\\",\\n    )\\n    installed_result = LoadResult(\\n        slot=\\\"official\\\",\\n        source_path=tmp_path / \\\"installed-extension\\\",\\n        distribution=\\\"lfx-pilot\\\",\\n    )\\n    installed_result.extension_id = \\\"lfx-pilot\\\"\\n    installed_result.extension_version = \\\"2.0.0\\\"\\n    installed_result.bundle = \\\"pilot\\\"\\n    installed_result.components = [installed_loaded]\\n\\n    fresh_registry = BundleRegistry()\\n    settings_service = _FakeSettingsService(components_path=[])\\n\\n    captured_diagnostics: list[list] = []\\n\\n    def _capture_diagnostics(results) -> None:\\n        captured_diagnostics.append(list(results))\\n\\n    with (\\n        patch(\\\"lfx.interface.components.create_component_template\\\", side_effect=_stub_template),\\n        patch(\\\"lfx.interface.components.get_default_registry\\\", return_value=fresh_registry),\\n        patch(\\\"lfx.interface.components.load_installed_extensions\\\", return_value=[installed_result]),\\n        patch(\\\"lfx.interface.components._emit_extension_diagnostics\\\", side_effect=_capture_diagnostics),\\n    ):\\n        await import_extension_components(settings_service)\\n\\n    # The installed copy is what registered.\\n    record = fresh_registry.get_bundle(\\\"pilot\\\")\\n    assert record is not None\\n    assert record.extension_version == \\\"2.0.0\\\", (\\n        \\\"installed bundle (v2.0.0) must win over seed-directory shadow (v0.0.1-seed)\\\"\\n    )\\n    assert record.distribution == \\\"lfx-pilot\\\"\\n\\n    # The seed result that ran through the diagnostics emitter carries the\\n    # typed shadowing warning so operators can see the misconfiguration.\\n    assert captured_diagnostics, \\\"diagnostics emitter was never called\\\"\\n    all_results = captured_diagnostics[0]\\n    shadow_codes = {warning.code for r in all_results for warning in r.warnings}\\n    assert \\\"seed-bundle-shadowed\\\" in shadow_codes, (\\n        f\\\"expected seed-bundle-shadowed in emitted diagnostics; got codes: {sorted(shadow_codes)}\\\"\\n    )\\n\\n\\n@pytest.mark.asyncio\\nasync def test_seed_bundle_shadows_dev_emits_generic_bundle_shadowed(tmp_path: Path, monkeypatch) -> None:\\n    \\\"\\\"\\\"A seed bundle silently shadowed a dev registration -- regression for the empty-deltas reload bug.\\n\\n    Reload reads ``live.source_path`` from the registry and walks that path on\\n    every call.  Before the cross-source dedup, the registry-population loop in\\n    :func:`import_extension_components` would silently overwrite earlier records\\n    with later ones (last-wins iteration order), so a stale dev registration\\n    pointing at a different filesystem location could clobber the seed record's\\n    ``source_path``.  Reload would then walk the dev path while the operator\\n    edits the seed copy on disk: 200 OK with empty deltas every time.\\n\\n    This test asserts both halves: the seed copy wins in the BundleRegistry\\n    AND the dev copy gets a typed ``bundle-shadowed`` warning naming both paths.\\n    \\\"\\\"\\\"\\n    import json\\n\\n    from lfx.extension.bundle_registry import BundleRegistry\\n    from lfx.extension.loader._types import LoadedComponent, LoadResult\\n\\n    # Real seed bundle on disk.\\n    seed_root = tmp_path / \\\"seed-bundles\\\"\\n    seed_extension_root = seed_root / \\\"lfx-pilot\\\"\\n    seed_bundle_dir = seed_extension_root / \\\"components\\\"\\n    seed_bundle_dir.mkdir(parents=True)\\n    manifest = {\\n        \\\"id\\\": \\\"lfx-pilot\\\",\\n        \\\"version\\\": \\\"1.0.0-seed\\\",\\n        \\\"name\\\": \\\"Pilot (seed)\\\",\\n        \\\"lfx\\\": {\\\"compat\\\": [\\\"1\\\"]},\\n        \\\"bundles\\\": [{\\\"name\\\": \\\"pilot\\\", \\\"path\\\": \\\"components\\\"}],\\n    }\\n    (seed_extension_root / \\\"extension.json\\\").write_text(json.dumps(manifest), encoding=\\\"utf-8\\\")\\n    (seed_bundle_dir / \\\"thing.py\\\").write_text(\\n        \\\"class Component:\\\\n    pass\\\\n\\\"\\n        \\\"class PilotThing(Component):\\\\n\\\"\\n        \\\"    display_name = 'Seed'\\\\n\\\"\\n        \\\"    def build(self):\\\\n        return None\\\\n\\\",\\n        encoding=\\\"utf-8\\\",\\n    )\\n    monkeypatch.setenv(\\\"LANGFLOW_SEED_DIR\\\", str(seed_root))\\n\\n    # Faked dev result for the same bundle name pointing at a totally\\n    # different path -- the stale registration that used to silently win.\\n    dev_path = tmp_path / \\\"stale-dev-checkout\\\"\\n    dev_path.mkdir()\\n\\n    class _Component:\\n        pass\\n\\n    class _DevPilotThing(_Component):\\n        display_name = \\\"Dev\\\"\\n\\n        def build(self) -> None:\\n            return None\\n\\n    dev_loaded = LoadedComponent(\\n        extension_id=\\\"lfx-pilot\\\",\\n        extension_version=\\\"9.9.9-dev\\\",\\n        bundle=\\\"pilot\\\",\\n        class_name=\\\"PilotThing\\\",\\n        slot=\\\"official\\\",\\n        klass=_DevPilotThing,\\n        module_name=\\\"_lfx_ext.official.pilot.thing\\\",\\n        file_path=dev_path / \\\"thing.py\\\",\\n        distribution=None,\\n    )\\n    dev_result = LoadResult(slot=\\\"official\\\", source_path=dev_path)\\n    dev_result.extension_id = \\\"lfx-pilot\\\"\\n    dev_result.extension_version = \\\"9.9.9-dev\\\"\\n    dev_result.bundle = \\\"pilot\\\"\\n    dev_result.components = [dev_loaded]\\n\\n    fresh_registry = BundleRegistry()\\n    settings_service = _FakeSettingsService(components_path=[])\\n\\n    captured_diagnostics: list[list] = []\\n\\n    def _capture_diagnostics(results) -> None:\\n        captured_diagnostics.append(list(results))\\n\\n    with (\\n        patch(\\\"lfx.interface.components.create_component_template\\\", side_effect=_stub_template),\\n        patch(\\\"lfx.interface.components.get_default_registry\\\", return_value=fresh_registry),\\n        patch(\\\"lfx.interface.components.load_dev_extensions\\\", return_value=[dev_result]),\\n        patch(\\\"lfx.interface.components._emit_extension_diagnostics\\\", side_effect=_capture_diagnostics),\\n    ):\\n        await import_extension_components(settings_service)\\n\\n    # Seed wins (higher precedence than dev).  The crucial assertion: the\\n    # registry's source_path is the seed path, NOT the stale dev path -- so\\n    # reload will walk the right directory and pick up on-disk edits.\\n    record = fresh_registry.get_bundle(\\\"pilot\\\")\\n    assert record is not None\\n    assert record.extension_version == \\\"1.0.0-seed\\\", \\\"seed bundle must win over dev shadow\\\"\\n    assert record.source_path is not None\\n    assert record.source_path.resolve() == seed_extension_root.resolve(), (\\n        f\\\"registry source_path={record.source_path} must point at the seed copy \\\"\\n        f\\\"at {seed_extension_root}, not the stale dev path {dev_path}; otherwise \\\"\\n        \\\"POST /reload silently no-ops on edits to the seed copy\\\"\\n    )\\n\\n    # The dev result that ran through the diagnostics emitter carries the\\n    # generic typed shadow warning naming both paths.\\n    assert captured_diagnostics, \\\"diagnostics emitter was never called\\\"\\n    all_results = captured_diagnostics[0]\\n    shadow_errors = [warning for r in all_results for warning in r.warnings if warning.code == \\\"bundle-shadowed\\\"]\\n    assert len(shadow_errors) == 1, (\\n        f\\\"expected exactly one bundle-shadowed warning; got {[w.code for r in all_results for w in r.warnings]}\\\"\\n    )\\n    msg = shadow_errors[0].message\\n    assert str(dev_path) in msg, msg\\n    assert str(seed_extension_root) in msg, msg\\n\\n\\n@pytest.mark.asyncio\\nasync def test_import_extension_components_populates_bundle_registry(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Startup wiring: discovered bundles must be installed in the BundleRegistry.\\n\\n    Without this, a real POST /api/v1/extensions/{id}/bundles/{name}/reload\\n    returns ``reload-bundle-not-installed`` for bundles that ARE visible in\\n    the palette, because the reload endpoint reads a separate registry that\\n    nothing populates.\\n    \\\"\\\"\\\"\\n    from lfx.extension.bundle_registry import BundleRegistry, get_default_registry\\n\\n    parent = tmp_path / \\\"components_root\\\"\\n    bundle_dir = parent / \\\"beta\\\"\\n    bundle_dir.mkdir(parents=True)\\n    (bundle_dir / \\\"thing.py\\\").write_text(\\n        \\\"class Component:\\\\n    pass\\\\n\\\"\\n        \\\"class BetaThing(Component):\\\\n\\\"\\n        \\\"    display_name = 'Beta'\\\\n\\\"\\n        \\\"    def build(self):\\\\n        return None\\\\n\\\",\\n        encoding=\\\"utf-8\\\",\\n    )\\n\\n    # Replace the process-default registry with a fresh one for this test\\n    # so we don't observe state from earlier tests in the suite.\\n    fresh_registry = BundleRegistry()\\n    settings_service = _FakeSettingsService(components_path=[str(parent)])\\n\\n    with (\\n        patch(\\\"lfx.interface.components.create_component_template\\\", side_effect=_stub_template),\\n        patch(\\\"lfx.interface.components.get_default_registry\\\", return_value=fresh_registry),\\n    ):\\n        await import_extension_components(settings_service)\\n\\n    record = fresh_registry.get_bundle(\\\"beta\\\")\\n    assert record is not None, \\\"bundle 'beta' must be registered after import\\\"\\n    assert record.bundle == \\\"beta\\\"\\n    assert record.slot == \\\"extra\\\"\\n    # The class should be visible in the registry too (so reload's diff works).\\n    assert \\\"BetaThing\\\" in record.class_names\\n\\n    # Sanity: get_default_registry() unmocked is also still callable.\\n    assert get_default_registry() is not None\\n\\n\\ndef test_post_swap_hook_refreshes_component_cache(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"After reload_bundle's Stage-3 swap, the component cache picks up the new class set.\\n\\n    Without the post-swap hook, ``component_cache.all_types_dict`` keeps the\\n    pre-reload templates and the palette / new-graph path stays stale until\\n    the next server restart.\\n    \\\"\\\"\\\"\\n    from lfx.extension.bundle_registry import BundleRecord\\n    from lfx.extension.loader._types import LoadedComponent\\n    from lfx.interface.components import (\\n        component_cache,\\n        refresh_bundle_cache_from_record,\\n    )\\n\\n    # Seed the cache with a placeholder pre-reload template for bundle 'gamma'.\\n    component_cache.all_types_dict = {\\\"gamma\\\": {\\\"old\\\": {\\\"display_name\\\": \\\"old\\\"}}}\\n    component_cache.all_types_ready = True\\n\\n    # Build a BundleRecord with a fake LoadedComponent.  We use the same\\n    # toy Component shim the other tests use; create_component_template\\n    # would fail on it, so patch the builder to return a stub.\\n    class _Component:\\n        pass\\n\\n    class _GammaThing(_Component):\\n        display_name = \\\"Gamma\\\"\\n\\n        def build(self) -> None:\\n            return None\\n\\n    loaded = LoadedComponent(\\n        extension_id=\\\"lfx-gamma\\\",\\n        extension_version=\\\"1.0.0\\\",\\n        bundle=\\\"gamma\\\",\\n        class_name=\\\"GammaThing\\\",\\n        slot=\\\"official\\\",\\n        klass=_GammaThing,\\n        module_name=\\\"_lfx_ext.official.gamma.thing\\\",\\n        file_path=tmp_path / \\\"thing.py\\\",\\n        distribution=None,\\n    )\\n    record = BundleRecord(\\n        bundle=\\\"gamma\\\",\\n        extension_id=\\\"lfx-gamma\\\",\\n        extension_version=\\\"1.0.0\\\",\\n        slot=\\\"official\\\",\\n        components=(loaded,),\\n    )\\n\\n    with patch(\\\"lfx.interface.components.create_component_template\\\", side_effect=_stub_template):\\n        refresh_bundle_cache_from_record(record)\\n\\n    assert \\\"gamma\\\" in component_cache.all_types_dict\\n    assert \\\"old\\\" not in component_cache.all_types_dict[\\\"gamma\\\"], (\\n        \\\"post-swap refresh must replace the pre-reload bundle dict, not merge\\\"\\n    )\\n    expected_id = \\\"ext:gamma:GammaThing@official\\\"\\n    assert expected_id in component_cache.all_types_dict[\\\"gamma\\\"]\\n\\n\\ndef test_post_swap_hook_noop_when_cache_not_built() -> None:\\n    \\\"\\\"\\\"If the cache hasn't been built yet, the hook must be a safe no-op.\\n\\n    The first ``get_and_cache_all_types_dict`` call will see the fresh\\n    registry entry and pick up the post-reload class set; we don't want\\n    the hook to crash on a None cache.\\n    \\\"\\\"\\\"\\n    from lfx.extension.bundle_registry import BundleRecord\\n    from lfx.interface.components import (\\n        component_cache,\\n        refresh_bundle_cache_from_record,\\n    )\\n\\n    component_cache.all_types_dict = None\\n    component_cache.all_types_ready = False\\n    record = BundleRecord(\\n        bundle=\\\"empty\\\",\\n        extension_id=\\\"lfx-empty\\\",\\n        extension_version=\\\"1.0.0\\\",\\n        slot=\\\"official\\\",\\n        components=(),\\n    )\\n    # Must not raise.\\n    refresh_bundle_cache_from_record(record)\\n    assert component_cache.all_types_dict is None\\n\\n\\ndef test_post_swap_hook_invalidates_hash_lookups(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"After reload, the precomputed hash lookups must be invalidated.\\n\\n    ``flow_validation.get_component_hash_lookups_for_validation`` only\\n    rebuilds the maps when both fields are None.  Without invalidation,\\n    flows running with custom components disabled keep validating against\\n    pre-reload class bodies and reject post-reload code as \\\"unrecognized\\\".\\n    \\\"\\\"\\\"\\n    from lfx.extension.bundle_registry import BundleRecord\\n    from lfx.extension.loader._types import LoadedComponent\\n    from lfx.interface.components import (\\n        component_cache,\\n        refresh_bundle_cache_from_record,\\n    )\\n\\n    component_cache.all_types_dict = {\\\"delta\\\": {\\\"old\\\": {\\\"display_name\\\": \\\"old\\\"}}}\\n    component_cache.all_types_ready = True\\n    component_cache.type_to_current_hash = {\\\"DeltaThing\\\": {\\\"abc123def456\\\"}}  # pragma: allowlist secret\\n    component_cache.all_known_hashes = {\\\"abc123def456\\\"}  # pragma: allowlist secret\\n    component_cache.type_to_code = {\\\"DeltaThing\\\": \\\"# stale trusted code\\\"}\\n    component_cache.component_identity_index = object()\\n\\n    class _Component:\\n        pass\\n\\n    class _DeltaThing(_Component):\\n        display_name = \\\"Delta\\\"\\n\\n        def build(self) -> None:\\n            return None\\n\\n    loaded = LoadedComponent(\\n        extension_id=\\\"lfx-delta\\\",\\n        extension_version=\\\"1.0.0\\\",\\n        bundle=\\\"delta\\\",\\n        class_name=\\\"DeltaThing\\\",\\n        slot=\\\"official\\\",\\n        klass=_DeltaThing,\\n        module_name=\\\"_lfx_ext.official.delta.thing\\\",\\n        file_path=tmp_path / \\\"thing.py\\\",\\n        distribution=None,\\n    )\\n    record = BundleRecord(\\n        bundle=\\\"delta\\\",\\n        extension_id=\\\"lfx-delta\\\",\\n        extension_version=\\\"1.0.0\\\",\\n        slot=\\\"official\\\",\\n        components=(loaded,),\\n    )\\n\\n    with patch(\\\"lfx.interface.components.create_component_template\\\", side_effect=_stub_template):\\n        refresh_bundle_cache_from_record(record)\\n\\n    assert component_cache.type_to_current_hash is None\\n    assert component_cache.all_known_hashes is None\\n    assert component_cache.type_to_code is None\\n    assert component_cache.component_identity_index is None\\n\\n\\ndef test_identity_index_read_cannot_publish_stale_state_after_reload(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A reader building the old index must linearize before reload invalidates it.\\\"\\\"\\\"\\n    from lfx.extension.bundle_registry import BundleRecord\\n    from lfx.extension.loader._types import LoadedComponent\\n    from lfx.interface import components as components_module\\n\\n    old_id = \\\"ext:delta:OldThing@official\\\"\\n    new_id = \\\"ext:delta:DeltaThing@official\\\"\\n    cache = components_module.ComponentCache()\\n    with cache.state_lock:\\n        cache.all_types_dict = {\\n            \\\"delta\\\": {\\n                old_id: {\\n                    \\\"name\\\": \\\"OldThing\\\",\\n                    \\\"display_name\\\": \\\"Old Thing\\\",\\n                    \\\"template\\\": {\\\"_type\\\": \\\"Component\\\"},\\n                }\\n            }\\n        }\\n        cache.all_types_ready = True\\n        cache.component_identity_index = None\\n\\n    class _DeltaThing:\\n        display_name = \\\"Delta\\\"\\n\\n        def build(self) -> None:\\n            return None\\n\\n    record = BundleRecord(\\n        bundle=\\\"delta\\\",\\n        extension_id=\\\"lfx-delta\\\",\\n        extension_version=\\\"1.0.0\\\",\\n        slot=\\\"official\\\",\\n        components=(\\n            LoadedComponent(\\n                extension_id=\\\"lfx-delta\\\",\\n                extension_version=\\\"1.0.0\\\",\\n                bundle=\\\"delta\\\",\\n                class_name=\\\"DeltaThing\\\",\\n                slot=\\\"official\\\",\\n                klass=_DeltaThing,\\n                module_name=\\\"_lfx_ext.official.delta.thing\\\",\\n                file_path=tmp_path / \\\"thing.py\\\",\\n                distribution=None,\\n            ),\\n        ),\\n    )\\n\\n    build_started = Event()\\n    release_build = Event()\\n    refresh_started = Event()\\n    refresh_finished = Event()\\n    reader_results = []\\n    thread_errors: list[Exception] = []\\n    real_build = components_module.build_component_identity_index\\n\\n    def delayed_build(all_types_dict):\\n        result = real_build(all_types_dict)\\n        build_started.set()\\n        if not release_build.wait(timeout=2):\\n            message = \\\"identity-index test did not release the reader\\\"\\n            raise TimeoutError(message)\\n        return result\\n\\n    def read_identity_index() -> None:\\n        try:\\n            reader_results.append(components_module.get_component_identity_index())\\n        except Exception as exc:\\n            thread_errors.append(exc)\\n\\n    def refresh_cache() -> None:\\n        refresh_started.set()\\n        try:\\n            components_module.refresh_bundle_cache_from_record(record)\\n        except Exception as exc:\\n            thread_errors.append(exc)\\n        finally:\\n            refresh_finished.set()\\n\\n    with (\\n        patch.object(components_module, \\\"component_cache\\\", cache),\\n        patch.object(components_module, \\\"build_component_identity_index\\\", side_effect=delayed_build),\\n        patch.object(components_module, \\\"create_component_template\\\", side_effect=_stub_template),\\n    ):\\n        reader = Thread(target=read_identity_index)\\n        reader.start()\\n        assert build_started.wait(timeout=2)\\n\\n        refresher = Thread(target=refresh_cache)\\n        refresher.start()\\n        assert refresh_started.wait(timeout=2)\\n        assert not refresh_finished.wait(timeout=0.1), \\\"reload published while an old index read held the state lock\\\"\\n\\n        release_build.set()\\n        reader.join(timeout=2)\\n        refresher.join(timeout=2)\\n        assert not reader.is_alive()\\n        assert not refresher.is_alive()\\n\\n        assert not thread_errors\\n        assert reader_results[0].resolve(\\\"OldThing\\\") == frozenset({old_id})\\n        assert cache.component_identity_index is None\\n\\n        current_index = components_module.get_component_identity_index()\\n        assert current_index is not None\\n        assert current_index.resolve(\\\"DeltaThing\\\") == frozenset({new_id})\\n        assert old_id not in current_index.canonical_keys\\n\\n\\ndef test_trusted_code_read_cannot_republish_stale_state_after_reload(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Lazy trusted-code construction linearizes before reload invalidation.\\\"\\\"\\\"\\n    from lfx.extension.bundle_registry import BundleRecord\\n    from lfx.extension.loader._types import LoadedComponent\\n    from lfx.interface import components as components_module\\n    from lfx.utils import flow_validation\\n\\n    cache = components_module.ComponentCache()\\n    old_id = \\\"ext:delta:OldThing@official\\\"\\n    new_id = \\\"ext:delta:DeltaThing@official\\\"\\n    old_code = \\\"# trusted old code\\\"\\n    new_code = \\\"# trusted new code\\\"\\n    old_hash = hashlib.sha256(old_code.encode()).hexdigest()[:12]\\n    new_hash = hashlib.sha256(new_code.encode()).hexdigest()[:12]\\n    with cache.state_lock:\\n        cache.all_types_dict = {\\n            \\\"delta\\\": {\\n                old_id: {\\n                    \\\"name\\\": \\\"OldThing\\\",\\n                    \\\"metadata\\\": {\\\"code_hash\\\": old_hash},\\n                    \\\"template\\\": {\\\"_type\\\": \\\"Component\\\", \\\"code\\\": {\\\"value\\\": old_code}},\\n                }\\n            }\\n        }\\n        cache.all_types_ready = True\\n        cache.code_by_hash = None\\n\\n    class _DeltaThing:\\n        display_name = \\\"Delta\\\"\\n\\n        def build(self) -> None:\\n            return None\\n\\n    record = BundleRecord(\\n        bundle=\\\"delta\\\",\\n        extension_id=\\\"lfx-delta\\\",\\n        extension_version=\\\"1.0.0\\\",\\n        slot=\\\"official\\\",\\n        components=(\\n            LoadedComponent(\\n                extension_id=\\\"lfx-delta\\\",\\n                extension_version=\\\"1.0.0\\\",\\n                bundle=\\\"delta\\\",\\n                class_name=\\\"DeltaThing\\\",\\n                slot=\\\"official\\\",\\n                klass=_DeltaThing,\\n                module_name=\\\"_lfx_ext.official.delta.thing\\\",\\n                file_path=tmp_path / \\\"thing.py\\\",\\n                distribution=None,\\n            ),\\n        ),\\n    )\\n\\n    def new_template(*_args, **_kwargs):\\n        return (\\n            {\\n                \\\"display_name\\\": \\\"Delta\\\",\\n                \\\"metadata\\\": {\\\"code_hash\\\": new_hash},\\n                \\\"template\\\": {\\\"_type\\\": \\\"Component\\\", \\\"code\\\": {\\\"value\\\": new_code}},\\n            },\\n            object(),\\n        )\\n\\n    build_started = Event()\\n    release_build = Event()\\n    refresh_started = Event()\\n    refresh_finished = Event()\\n    reader_results: list[str | None] = []\\n    thread_errors: list[Exception] = []\\n    real_collect = flow_validation.collect_code_by_hash\\n\\n    def delayed_collect(all_types_dict):\\n        result = real_collect(all_types_dict)\\n        build_started.set()\\n        if not release_build.wait(timeout=2):\\n            message = \\\"trusted-code test did not release the reader\\\"\\n            raise TimeoutError(message)\\n        return result\\n\\n    def read_trusted_code() -> None:\\n        try:\\n            reader_results.append(flow_validation.get_trusted_code_for_validation(old_code))\\n        except Exception as exc:\\n            thread_errors.append(exc)\\n\\n    def refresh_cache() -> None:\\n        refresh_started.set()\\n        try:\\n            components_module.refresh_bundle_cache_from_record(record)\\n        except Exception as exc:\\n            thread_errors.append(exc)\\n        finally:\\n            refresh_finished.set()\\n\\n    with (\\n        patch.object(components_module, \\\"component_cache\\\", cache),\\n        patch.object(flow_validation, \\\"collect_code_by_hash\\\", side_effect=delayed_collect),\\n        patch.object(components_module, \\\"create_component_template\\\", side_effect=new_template),\\n    ):\\n        reader = Thread(target=read_trusted_code)\\n        reader.start()\\n        assert build_started.wait(timeout=2)\\n\\n        refresher = Thread(target=refresh_cache)\\n        refresher.start()\\n        assert refresh_started.wait(timeout=2)\\n        assert not refresh_finished.wait(timeout=0.1), \\\"reload passed a trusted-code read holding the state lock\\\"\\n\\n        release_build.set()\\n        reader.join(timeout=2)\\n        refresher.join(timeout=2)\\n        assert not reader.is_alive()\\n        assert not refresher.is_alive()\\n\\n        assert cache.code_by_hash is None\\n        assert flow_validation.get_trusted_code_for_validation(new_code) == new_code\\n        assert flow_validation.get_trusted_code_for_validation(old_code) is None\\n\\n    assert not thread_errors\\n    assert reader_results == [old_code]\\n    assert cache.all_types_dict is not None\\n    assert new_id in cache.all_types_dict[\\\"delta\\\"]\\n\\n\\ndef test_refresh_cache_preserves_entry_on_total_failure(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Total template failure preserves the previous cache entry and raises.\\n\\n    Refuse to overwrite the previous cache entry with ``{}``; raise so the\\n    hook layer can surface the failure on ``ReloadResult.warnings``.\\n    Regression guard for the empty-palette-after-reload bug: the prior code\\n    silently logged a warning per failed component, then unconditionally\\n    wrote an empty dict to ``component_cache.all_types_dict[bundle]``.\\n    \\\"\\\"\\\"\\n    from lfx.extension.bundle_registry import BundleRecord\\n    from lfx.extension.loader._types import LoadedComponent\\n    from lfx.interface.components import (\\n        component_cache,\\n        refresh_bundle_cache_from_record,\\n    )\\n\\n    pre_existing = {\\\"ext:zeta:OldThing@official\\\": {\\\"display_name\\\": \\\"old\\\", \\\"extension\\\": \\\"lfx-zeta\\\"}}\\n    component_cache.all_types_dict = {\\\"zeta\\\": dict(pre_existing)}\\n    component_cache.all_types_ready = True\\n\\n    class _Component:\\n        pass\\n\\n    class _ZetaThing(_Component):\\n        display_name = \\\"Zeta\\\"\\n\\n        def build(self) -> None:\\n            return None\\n\\n    loaded = LoadedComponent(\\n        extension_id=\\\"lfx-zeta\\\",\\n        extension_version=\\\"1.0.0\\\",\\n        bundle=\\\"zeta\\\",\\n        class_name=\\\"ZetaThing\\\",\\n        slot=\\\"official\\\",\\n        klass=_ZetaThing,\\n        module_name=\\\"_lfx_ext.official.zeta.thing\\\",\\n        file_path=tmp_path / \\\"thing.py\\\",\\n        distribution=None,\\n    )\\n    record = BundleRecord(\\n        bundle=\\\"zeta\\\",\\n        extension_id=\\\"lfx-zeta\\\",\\n        extension_version=\\\"1.0.0\\\",\\n        slot=\\\"official\\\",\\n        components=(loaded,),\\n    )\\n\\n    def _always_raises(*_args, **_kwargs):\\n        msg = \\\"synthetic template failure\\\"\\n        raise RuntimeError(msg)\\n\\n    with (\\n        patch(\\\"lfx.interface.components.create_component_template\\\", side_effect=_always_raises),\\n        pytest.raises(RuntimeError, match=\\\"every component in bundle 'zeta' failed to template\\\"),\\n    ):\\n        refresh_bundle_cache_from_record(record)\\n\\n    # Pre-existing cache entry untouched -- the palette continues to show\\n    # the pre-reload component set instead of going dark.\\n    assert component_cache.all_types_dict[\\\"zeta\\\"] == pre_existing\\n\\n\\ndef test_refresh_cache_writes_partial_on_partial_failure(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"One passing + one failing component commits a partial cache entry.\\n\\n    Palette is \\\"less broken\\\" than pre-reload; the bundle dict must not be\\n    empty (otherwise the total-failure guard would have raised).\\n    \\\"\\\"\\\"\\n    from lfx.extension.bundle_registry import BundleRecord\\n    from lfx.extension.loader._types import LoadedComponent\\n    from lfx.interface.components import (\\n        component_cache,\\n        refresh_bundle_cache_from_record,\\n    )\\n\\n    component_cache.all_types_dict = {\\\"eta\\\": {}}\\n    component_cache.all_types_ready = True\\n\\n    class _Component:\\n        pass\\n\\n    class _Good(_Component):\\n        display_name = \\\"Good\\\"\\n\\n        def build(self) -> None:\\n            return None\\n\\n    class _Bad(_Component):\\n        display_name = \\\"Bad\\\"\\n\\n        def build(self) -> None:\\n            return None\\n\\n    good = LoadedComponent(\\n        extension_id=\\\"lfx-eta\\\",\\n        extension_version=\\\"1.0.0\\\",\\n        bundle=\\\"eta\\\",\\n        class_name=\\\"Good\\\",\\n        slot=\\\"official\\\",\\n        klass=_Good,\\n        module_name=\\\"_lfx_ext.official.eta.good\\\",\\n        file_path=tmp_path / \\\"good.py\\\",\\n        distribution=None,\\n    )\\n    bad = LoadedComponent(\\n        extension_id=\\\"lfx-eta\\\",\\n        extension_version=\\\"1.0.0\\\",\\n        bundle=\\\"eta\\\",\\n        class_name=\\\"Bad\\\",\\n        slot=\\\"official\\\",\\n        klass=_Bad,\\n        module_name=\\\"_lfx_ext.official.eta.bad\\\",\\n        file_path=tmp_path / \\\"bad.py\\\",\\n        distribution=None,\\n    )\\n    record = BundleRecord(\\n        bundle=\\\"eta\\\",\\n        extension_id=\\\"lfx-eta\\\",\\n        extension_version=\\\"1.0.0\\\",\\n        slot=\\\"official\\\",\\n        components=(good, bad),\\n    )\\n\\n    def _template(component_extractor, module_name=None):  # noqa: ARG001\\n        if isinstance(component_extractor, _Bad):\\n            msg = \\\"synthetic per-component failure\\\"\\n            raise RuntimeError(msg)  # noqa: TRY004\\n        return _stub_template()\\n\\n    with patch(\\\"lfx.interface.components.create_component_template\\\", side_effect=_template):\\n        refresh_bundle_cache_from_record(record)\\n\\n    bundle_dict = component_cache.all_types_dict[\\\"eta\\\"]\\n    assert \\\"ext:eta:Good@official\\\" in bundle_dict\\n    assert \\\"ext:eta:Bad@official\\\" not in bundle_dict\\n\\n\\n@pytest.mark.asyncio\\nasync def test_dev_extension_components_loaded_via_official_slot(\\n    tmp_path: Path,\\n    monkeypatch: pytest.MonkeyPatch,\\n) -> None:\\n    \\\"\\\"\\\"Dev extensions registered via ``lfx extension dev`` must enter the @official pathway.\\n\\n    Earlier wiring appended their bundle directories to LANGFLOW_COMPONENTS_PATH,\\n    causing them to fall back to legacy custom-component loading without\\n    extension metadata or BundleRegistry entries.  Now they share the same\\n    pathway as installed extensions.\\n    \\\"\\\"\\\"\\n    import json\\n\\n    from lfx.extension import register_dev_extension\\n    from lfx.extension.bundle_registry import BundleRegistry\\n\\n    # Build a manifest-shipping extension on disk.\\n    ext_root = tmp_path / \\\"my-ext\\\"\\n    ext_root.mkdir()\\n    bundle_dir = ext_root / \\\"components\\\"\\n    bundle_dir.mkdir()\\n    (bundle_dir / \\\"thing.py\\\").write_text(\\n        \\\"class Component:\\\\n    pass\\\\n\\\"\\n        \\\"class DevThing(Component):\\\\n\\\"\\n        \\\"    display_name = 'Dev'\\\\n\\\"\\n        \\\"    def build(self):\\\\n        return None\\\\n\\\",\\n        encoding=\\\"utf-8\\\",\\n    )\\n    (ext_root / \\\"extension.json\\\").write_text(\\n        json.dumps(\\n            {\\n                \\\"id\\\": \\\"lfx-dev-fixture\\\",\\n                \\\"version\\\": \\\"0.1.0\\\",\\n                \\\"name\\\": \\\"Dev Fixture\\\",\\n                \\\"lfx\\\": {\\\"compat\\\": [\\\"1\\\"]},\\n                \\\"bundles\\\": [{\\\"name\\\": \\\"devbundle\\\", \\\"path\\\": \\\"components\\\"}],\\n            }\\n        ),\\n        encoding=\\\"utf-8\\\",\\n    )\\n\\n    # Point the dev registry at an isolated state file via env var so the\\n    # test does not pollute the user's real cache dir.\\n    monkeypatch.setenv(\\\"LANGFLOW_DEV_EXTENSIONS_DIR\\\", str(tmp_path / \\\"registry\\\"))\\n    register_dev_extension(ext_root)\\n\\n    fresh_registry = BundleRegistry()\\n    settings_service = _FakeSettingsService(components_path=[])\\n\\n    with (\\n        patch(\\\"lfx.interface.components.create_component_template\\\", side_effect=_stub_template),\\n        patch(\\\"lfx.interface.components.get_default_registry\\\", return_value=fresh_registry),\\n    ):\\n        result = await import_extension_components(settings_service)\\n\\n    assert \\\"devbundle\\\" in result\\n    record = fresh_registry.get_bundle(\\\"devbundle\\\")\\n    assert record is not None\\n    assert record.slot == \\\"official\\\"\\n    assert \\\"DevThing\\\" in record.class_names\\n    expected_id = \\\"ext:devbundle:DevThing@official\\\"\\n    assert expected_id in result[\\\"devbundle\\\"]\\n    assert result[\\\"devbundle\\\"][expected_id][\\\"extension\\\"] == \\\"lfx-dev-fixture\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/test_components_path_settings.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6c5e46b814238d076ff05c0099b0823ebea109d4bb6e8cfd28163f764d3b8350\",\"content\":\"\\\"\\\"\\\"Tests for the LANGFLOW_COMPONENTS_PATH pathsep-split behavior in settings.\\n\\nThe extension loader requires that ``LANGFLOW_COMPONENTS_PATH=/path/A:/path/B``\\nis parsed as two component paths rather than treated as one literal\\nnon-existent path.  This test exercises the validator directly so it works\\nwithout spinning up the full settings service.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport os\\nfrom typing import TYPE_CHECKING\\n\\nfrom lfx.constants import BASE_COMPONENTS_PATH\\nfrom lfx.services.settings.base import Settings\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n\\ndef test_pathsep_separated_paths_are_split(monkeypatch, tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Two-entry env var produces two components-path entries.\\\"\\\"\\\"\\n    path_a = tmp_path / \\\"a\\\"\\n    path_b = tmp_path / \\\"b\\\"\\n    path_a.mkdir()\\n    path_b.mkdir()\\n    env = f\\\"{path_a}{os.pathsep}{path_b}\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_COMPONENTS_PATH\\\", env)\\n\\n    result = Settings.set_components_path([])\\n    assert str(path_a) in result\\n    assert str(path_b) in result\\n\\n\\ndef test_walk_order_matches_user_declared_order(monkeypatch, tmp_path: Path) -> None:\\n    \\\"\\\"\\\"User-declared path order is preserved across the pathsep split.\\\"\\\"\\\"\\n    path_a = tmp_path / \\\"first\\\"\\n    path_b = tmp_path / \\\"second\\\"\\n    path_a.mkdir()\\n    path_b.mkdir()\\n    monkeypatch.setenv(\\\"LANGFLOW_COMPONENTS_PATH\\\", f\\\"{path_a}{os.pathsep}{path_b}\\\")\\n\\n    result = Settings.set_components_path([])\\n    # The base components path is appended only when value would be empty,\\n    # so with explicit env paths the order under test is exactly user order.\\n    indices = [result.index(str(path_a)), result.index(str(path_b))]\\n    assert indices == sorted(indices)\\n\\n\\ndef test_non_existent_segments_are_skipped(monkeypatch, tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Pathsep entries that don't exist on disk are silently skipped.\\\"\\\"\\\"\\n    real = tmp_path / \\\"real\\\"\\n    real.mkdir()\\n    bogus = tmp_path / \\\"does-not-exist\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_COMPONENTS_PATH\\\", f\\\"{real}{os.pathsep}{bogus}\\\")\\n\\n    result = Settings.set_components_path([])\\n    assert str(real) in result\\n    assert str(bogus) not in result\\n\\n\\ndef test_empty_segments_are_ignored(monkeypatch, tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Trailing pathsep producing an empty segment doesn't crash.\\\"\\\"\\\"\\n    real = tmp_path / \\\"real\\\"\\n    real.mkdir()\\n    monkeypatch.setenv(\\\"LANGFLOW_COMPONENTS_PATH\\\", f\\\"{real}{os.pathsep}\\\")\\n\\n    result = Settings.set_components_path([])\\n    assert str(real) in result\\n\\n\\ndef test_unset_env_falls_back_to_base(monkeypatch) -> None:\\n    \\\"\\\"\\\"No env var -> the base components path is the only entry.\\\"\\\"\\\"\\n    monkeypatch.delenv(\\\"LANGFLOW_COMPONENTS_PATH\\\", raising=False)\\n    result = Settings.set_components_path([])\\n    assert result == [BASE_COMPONENTS_PATH]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/test_dev_registry.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6e322b54d3295edf12aa16d7a4f5cbe1950ac477ea0abf959f878214c9e5720f\",\"content\":\"\\\"\\\"\\\"Tests for ``lfx.extension.dev_registry``.\\n\\nCoverage:\\n    - register / list / unregister round-trip\\n    - re-register refreshes timestamp without duplicating\\n    - registering a non-directory raises FileNotFoundError up front\\n    - state file format is schema-versioned and human-readable\\n    - load_dev_extensions surfaces local-extension-missing for vanished paths\\n    - dev_extension_component_paths returns bundle dirs callable feeds to\\n      ``components_path`` discovery\\n    - state_dir override env var is respected (test seam)\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom typing import TYPE_CHECKING\\n\\nimport pytest\\nfrom lfx.extension import (\\n    BASIC_TEMPLATE,\\n    InitOptions,\\n    dev_extension_component_paths,\\n    init_extension,\\n    list_dev_extensions,\\n    load_dev_extensions,\\n    register_dev_extension,\\n    state_file_path,\\n    unregister_dev_extension,\\n)\\nfrom lfx.extension.init_template import (\\n    derive_bundle_name,\\n    derive_display_name,\\n    derive_extension_id,\\n)\\n\\nif TYPE_CHECKING:\\n    from pathlib import Path\\n\\n\\n@pytest.fixture(autouse=True)\\ndef isolated_state_dir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:\\n    \\\"\\\"\\\"Point the dev registry at a per-test directory.\\n\\n    The registry would otherwise persist across tests under the user\\n    cache dir; this fixture isolates each test by forcing\\n    ``LANGFLOW_DEV_EXTENSIONS_DIR`` to a tmp_path subdirectory.\\n    \\\"\\\"\\\"\\n    state_dir = tmp_path / \\\"_state\\\"\\n    state_dir.mkdir()\\n    monkeypatch.setenv(\\\"LANGFLOW_DEV_EXTENSIONS_DIR\\\", str(state_dir))\\n    return state_dir\\n\\n\\ndef _scaffold(tmp_path: Path, name: str = \\\"my-ext\\\") -> Path:\\n    target = tmp_path / name\\n    eid = derive_extension_id(target.name)\\n    options = InitOptions(\\n        target=target,\\n        extension_id=eid,\\n        bundle_name=derive_bundle_name(eid),\\n        display_name=derive_display_name(eid),\\n        template=BASIC_TEMPLATE,\\n    )\\n    init_extension(options)\\n    return target\\n\\n\\ndef _add_bundle(extension_dir: Path, bundle_name: str) -> None:\\n    manifest_path = extension_dir / \\\"extension.json\\\"\\n    manifest = json.loads(manifest_path.read_text(encoding=\\\"utf-8\\\"))\\n    manifest[\\\"bundles\\\"].append(\\n        {\\n            \\\"name\\\": bundle_name,\\n            \\\"path\\\": f\\\"components/{bundle_name}\\\",\\n            \\\"display_name\\\": bundle_name.title(),\\n        }\\n    )\\n    manifest_path.write_text(json.dumps(manifest), encoding=\\\"utf-8\\\")\\n    bundle_dir = extension_dir / \\\"components\\\" / bundle_name\\n    bundle_dir.mkdir(parents=True)\\n    (bundle_dir / \\\"__init__.py\\\").write_text(\\\"\\\", encoding=\\\"utf-8\\\")\\n    (bundle_dir / \\\"secondary.py\\\").write_text(\\n        \\\"from lfx.custom import Component\\\\n\\\\nclass SecondaryComponent(Component):\\\\n    display_name = 'Secondary'\\\\n\\\",\\n        encoding=\\\"utf-8\\\",\\n    )\\n\\n\\n# ---------------------------------------------------------------------------\\n# state_file_path / register / list\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_state_file_lives_under_isolated_dir(isolated_state_dir: Path) -> None:\\n    path = state_file_path()\\n    assert path == isolated_state_dir / \\\"dev_extensions.json\\\"\\n\\n\\ndef test_register_and_list(tmp_path: Path) -> None:\\n    extension_dir = _scaffold(tmp_path)\\n    entry = register_dev_extension(extension_dir)\\n    assert entry.path == extension_dir.resolve()\\n    assert entry.registered_at  # ISO-8601 string\\n\\n    entries = list_dev_extensions()\\n    assert [e.path for e in entries] == [extension_dir.resolve()]\\n\\n\\ndef test_register_is_idempotent_and_refreshes_timestamp(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:\\n    extension_dir = _scaffold(tmp_path)\\n    first = register_dev_extension(extension_dir)\\n    # Force a different timestamp by patching the clock\\n    import lfx.extension.dev_registry as dr\\n\\n    monkeypatch.setattr(dr, \\\"_utcnow_iso\\\", lambda: \\\"2099-01-01T00:00:00Z\\\")\\n    second = register_dev_extension(extension_dir)\\n    assert second.path == first.path\\n    assert second.registered_at == \\\"2099-01-01T00:00:00Z\\\"\\n\\n    # Still exactly one entry in the registry.\\n    entries = list_dev_extensions()\\n    assert len(entries) == 1\\n\\n\\ndef test_register_refuses_non_directory(tmp_path: Path) -> None:\\n    bogus = tmp_path / \\\"does-not-exist\\\"\\n    with pytest.raises(FileNotFoundError):\\n        register_dev_extension(bogus)\\n\\n\\ndef test_register_resolves_relative_paths(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:\\n    extension_dir = _scaffold(tmp_path)\\n    monkeypatch.chdir(tmp_path)\\n    relative = extension_dir.name  # e.g. \\\"my-ext\\\"\\n    entry = register_dev_extension(relative)\\n    assert entry.path == extension_dir.resolve()\\n    assert entry.path.is_absolute()\\n\\n\\n# ---------------------------------------------------------------------------\\n# unregister\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_unregister_removes_existing_entry(tmp_path: Path) -> None:\\n    extension_dir = _scaffold(tmp_path)\\n    register_dev_extension(extension_dir)\\n    removed = unregister_dev_extension(extension_dir)\\n    assert removed is True\\n    assert list_dev_extensions() == []\\n\\n\\ndef test_unregister_returns_false_for_unknown_path(tmp_path: Path) -> None:\\n    bogus = tmp_path / \\\"never-registered\\\"\\n    bogus.mkdir()\\n    removed = unregister_dev_extension(bogus)\\n    assert removed is False\\n\\n\\n# ---------------------------------------------------------------------------\\n# State file format\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_state_file_is_versioned_json(tmp_path: Path) -> None:\\n    extension_dir = _scaffold(tmp_path)\\n    register_dev_extension(extension_dir)\\n    payload = json.loads(state_file_path().read_text(encoding=\\\"utf-8\\\"))\\n    assert payload[\\\"version\\\"] == 1\\n    assert isinstance(payload[\\\"extensions\\\"], list)\\n    assert payload[\\\"extensions\\\"][0][\\\"path\\\"] == str(extension_dir.resolve())\\n\\n\\ndef test_malformed_state_file_treated_as_empty() -> None:\\n    # Pre-populate the (autouse-isolated) state dir with garbage, then read it.\\n    state_file_path().parent.mkdir(parents=True, exist_ok=True)\\n    state_file_path().write_text(\\\"not valid json\\\", encoding=\\\"utf-8\\\")\\n    assert list_dev_extensions() == []\\n\\n\\ndef test_missing_state_file_yields_empty_list() -> None:\\n    assert list_dev_extensions() == []\\n\\n\\n# ---------------------------------------------------------------------------\\n# load_dev_extensions\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_load_dev_extensions_returns_loaded_components(tmp_path: Path) -> None:\\n    extension_dir = _scaffold(tmp_path)\\n    register_dev_extension(extension_dir)\\n    results = load_dev_extensions()\\n    assert len(results) == 1\\n    result = results[0]\\n    assert result.ok, result.errors\\n    assert result.extension_id == \\\"my-ext\\\"\\n    assert any(c.class_name == \\\"MyExtHelloComponent\\\" for c in result.components)\\n\\n\\ndef test_load_dev_extensions_loads_every_manifest_bundle(tmp_path: Path) -> None:\\n    extension_dir = _scaffold(tmp_path)\\n    _add_bundle(extension_dir, \\\"secondary\\\")\\n    register_dev_extension(extension_dir)\\n\\n    results = load_dev_extensions()\\n\\n    assert [result.bundle for result in results] == [\\\"my_ext\\\", \\\"secondary\\\"]\\n    assert all(result.ok for result in results)\\n    assert all(result.components for result in results)\\n\\n\\ndef test_load_dev_extensions_surfaces_missing_directory(tmp_path: Path) -> None:\\n    extension_dir = _scaffold(tmp_path)\\n    register_dev_extension(extension_dir)\\n    # Move the directory out from under the registry.\\n    relocated = tmp_path / \\\"moved-away\\\"\\n    extension_dir.rename(relocated)\\n\\n    results = load_dev_extensions()\\n    assert len(results) == 1\\n    result = results[0]\\n    # AC #5: typed warning, not a crash.\\n    codes = [w.code for w in result.warnings]\\n    assert codes == [\\\"local-extension-missing\\\"]\\n    assert result.components == []\\n\\n\\ndef test_load_dev_extensions_after_directory_returns_recovers(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"If a missing path reappears, the next load picks it up cleanly.\\\"\\\"\\\"\\n    extension_dir = _scaffold(tmp_path)\\n    register_dev_extension(extension_dir)\\n    relocated = tmp_path / \\\"moved-away\\\"\\n    extension_dir.rename(relocated)\\n    # First load -> warning\\n    assert any(w.code == \\\"local-extension-missing\\\" for r in load_dev_extensions() for w in r.warnings)\\n    # Move back\\n    relocated.rename(extension_dir)\\n    # Second load -> warning gone\\n    results = load_dev_extensions()\\n    assert all(not r.warnings for r in results)\\n    assert results[0].ok\\n\\n\\n# ---------------------------------------------------------------------------\\n# dev_extension_component_paths\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_dev_extension_component_paths_returns_bundle_dir(tmp_path: Path) -> None:\\n    extension_dir = _scaffold(tmp_path)\\n    register_dev_extension(extension_dir)\\n    paths, errors = dev_extension_component_paths()\\n    assert errors == []\\n    assert len(paths) == 1\\n    # Resolved path should point inside the extension's components dir.\\n    assert paths[0].is_relative_to(extension_dir.resolve())\\n\\n\\ndef test_dev_extension_component_paths_returns_every_bundle_dir(tmp_path: Path) -> None:\\n    extension_dir = _scaffold(tmp_path)\\n    _add_bundle(extension_dir, \\\"secondary\\\")\\n    register_dev_extension(extension_dir)\\n\\n    paths, errors = dev_extension_component_paths()\\n\\n    assert errors == []\\n    assert {path.name for path in paths} == {\\\"my_ext\\\", \\\"secondary\\\"}\\n\\n\\ndef test_dev_extension_component_paths_surfaces_missing_dir(tmp_path: Path) -> None:\\n    extension_dir = _scaffold(tmp_path)\\n    register_dev_extension(extension_dir)\\n    extension_dir.rename(tmp_path / \\\"moved\\\")\\n    paths, errors = dev_extension_component_paths()\\n    assert paths == []\\n    codes = [e.code for e in errors]\\n    assert \\\"local-extension-missing\\\" in codes\\n\\n\\ndef test_dev_extension_component_paths_forwards_all_warnings(\\n    tmp_path: Path,\\n    monkeypatch: pytest.MonkeyPatch,\\n) -> None:\\n    \\\"\\\"\\\"A duplicate-component-name warning must reach the caller.\\n\\n    Previously the helper only forwarded ``local-extension-missing``,\\n    silently dropping every other warning code.  This test pins the new\\n    \\\"forward everything\\\" contract so a duplicate-component-name (or any\\n    future code) shows up in the lifespan hook's logs.\\n    \\\"\\\"\\\"\\n    extension_dir = _scaffold(tmp_path)\\n    register_dev_extension(extension_dir)\\n\\n    # Stub load_dev_extensions to inject a synthetic warning of a\\n    # different code, simulating what a future loader pass might emit.\\n    from lfx.extension import dev_registry as dr\\n    from lfx.extension.errors import ExtensionError\\n    from lfx.extension.loader._types import LoadResult\\n\\n    fake = LoadResult(\\n        slot=\\\"official\\\",\\n        source_path=extension_dir,\\n        extension_id=\\\"my-ext\\\",\\n        bundle=\\\"my_ext\\\",\\n    )\\n    fake.warnings.append(\\n        ExtensionError(\\n            code=\\\"duplicate-component-name\\\",\\n            message=\\\"synthetic\\\",\\n            location=\\\"my_ext\\\",\\n            content=\\\"HelloComponent\\\",\\n            hint=\\\"rename\\\",\\n        )\\n    )\\n    monkeypatch.setattr(dr, \\\"load_dev_extensions\\\", lambda *_, **__: [fake])\\n\\n    _paths, errors = dev_extension_component_paths()\\n    codes = [e.code for e in errors]\\n    # The non-missing-dir warning is forwarded, not silently dropped.\\n    assert \\\"duplicate-component-name\\\" in codes\\n\\n\\ndef test_dev_extension_component_paths_defends_against_missing_source_path(\\n    tmp_path: Path,\\n    monkeypatch: pytest.MonkeyPatch,\\n) -> None:\\n    \\\"\\\"\\\"A LoadResult with components but no source_path is a contract bug.\\n\\n    The helper used to silently drop such results, hiding the problem.\\n    Now it surfaces a typed local-extension-missing error and skips the\\n    extension explicitly.\\n    \\\"\\\"\\\"\\n    extension_dir = _scaffold(tmp_path)\\n    register_dev_extension(extension_dir)\\n\\n    from lfx.extension import dev_registry as dr\\n    from lfx.extension.loader._types import LoadResult\\n\\n    # Build a LoadResult that's structurally invalid: components present,\\n    # source_path None.\\n    fake = LoadResult(\\n        slot=\\\"official\\\",\\n        source_path=None,\\n        extension_id=\\\"my-ext\\\",\\n        bundle=\\\"my_ext\\\",\\n    )\\n    # Borrow the component the real loader produced.\\n    real_results = dr.load_dev_extensions()\\n    real_components = real_results[0].components\\n    fake.components.extend(real_components)\\n    monkeypatch.setattr(dr, \\\"load_dev_extensions\\\", lambda *_, **__: [fake])\\n\\n    paths, errors = dev_extension_component_paths()\\n    assert paths == []\\n    codes = [e.code for e in errors]\\n    assert \\\"local-extension-missing\\\" in codes\\n\\n\\ndef test_dev_extension_component_paths_uses_relative_depth_for_bundle_root(\\n    tmp_path: Path,\\n) -> None:\\n    \\\"\\\"\\\"The shallowest-ancestor-under-source_root algorithm picks the right dir.\\n\\n    With a bundle laid out at ``my-ext/components/my_ext/`` and a real\\n    component at ``my-ext/components/my_ext/hello.py``, the returned\\n    bundle path must be the components/my_ext directory, NOT something\\n    higher up (which would cause the existing palette discovery to miss\\n    sub-modules) and NOT the file's parent directly (it happens to be\\n    the same here, but the algorithm should be correct).\\n    \\\"\\\"\\\"\\n    extension_dir = _scaffold(tmp_path)\\n    register_dev_extension(extension_dir)\\n    paths, errors = dev_extension_component_paths()\\n    assert errors == []\\n    assert len(paths) == 1\\n    bundle_root = paths[0]\\n    # Path resolves to <ext>/components/my_ext (the bundle dir).\\n    assert bundle_root.name == \\\"my_ext\\\"\\n    assert bundle_root.parent.name == \\\"components\\\"\\n    assert bundle_root.is_relative_to(extension_dir.resolve())\\n\\n\\n# ---------------------------------------------------------------------------\\n# Override env var\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_state_dir_env_var_takes_precedence(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:\\n    override = tmp_path / \\\"custom\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_DEV_EXTENSIONS_DIR\\\", str(override))\\n    assert state_file_path().parent == override\\n    # The override is honored even when LANGFLOW_CONFIG_DIR is also set.\\n    monkeypatch.setenv(\\\"LANGFLOW_CONFIG_DIR\\\", str(tmp_path / \\\"ignore-me\\\"))\\n    assert state_file_path().parent == override\\n\\n\\ndef test_config_dir_fallback(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:\\n    monkeypatch.delenv(\\\"LANGFLOW_DEV_EXTENSIONS_DIR\\\", raising=False)\\n    cfg = tmp_path / \\\"cfg\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_CONFIG_DIR\\\", str(cfg))\\n    assert state_file_path() == cfg / \\\"extensions\\\" / \\\"dev_extensions.json\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/test_discovery.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2463d5ee4f753f725fe623fee1beb5c5e1c7b2ad065f1486ccbc5272076d10e5\",\"content\":\"\\\"\\\"\\\"Discovery tests for installed-distribution + seed-directory sources.\\n\\nTwo integration pieces:\\n\\n    * Three \\\"installed\\\" distributions surfaced via a fake\\n      ``importlib.metadata.distributions()`` iterator -- mirrors the\\n      ``pip install`` path without paying the cost of building real\\n      wheels in the unit-test pipeline. ``test_e2e_install.py`` covers\\n      the genuine ``pip install`` path; this file pins the in-process\\n      contract.\\n\\n    * A seed directory with three bundle subdirectories.\\n\\nPlus per-failure coverage: malformed manifests surface typed errors\\nwithout aborting the scan, and explicitly-configured-but-missing seed\\nroots emit ``seed-directory-not-found``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nimport os\\nfrom importlib import metadata as importlib_metadata\\nfrom pathlib import Path\\n\\nimport pytest\\nfrom lfx.extension.discovery import (\\n    DEFAULT_SEED_DIR,\\n    SEED_DIR_ENV_VAR,\\n    canonicalize_distribution,\\n    discover_all_extensions,\\n    discover_installed_extensions,\\n    discover_seed_extensions,\\n)\\nfrom lfx.extension.manifest import ManifestSource\\n\\n# ---------------------------------------------------------------------------\\n# Manifest helpers\\n# ---------------------------------------------------------------------------\\n\\n_BUNDLE_NAMES = (\\\"openai\\\", \\\"anthropic\\\", \\\"qdrant\\\")\\n\\n\\ndef _manifest(extension_id: str, bundle_name: str, version: str = \\\"1.0.0\\\") -> dict[str, object]:\\n    \\\"\\\"\\\"Build a minimal v0 manifest dict.  Bundle path is the bundle name.\\\"\\\"\\\"\\n    return {\\n        \\\"id\\\": extension_id,\\n        \\\"version\\\": version,\\n        \\\"name\\\": f\\\"{extension_id} bundle\\\",\\n        \\\"lfx\\\": {\\\"compat\\\": [\\\"1\\\"]},\\n        \\\"bundles\\\": [{\\\"name\\\": bundle_name, \\\"path\\\": bundle_name}],\\n    }\\n\\n\\ndef _write_extension_json(root: Path, manifest: dict[str, object]) -> Path:\\n    root.mkdir(parents=True, exist_ok=True)\\n    for bundle in manifest[\\\"bundles\\\"]:  # type: ignore[union-attr]\\n        (root / bundle[\\\"path\\\"]).mkdir(parents=True, exist_ok=True)  # type: ignore[index]\\n    (root / \\\"extension.json\\\").write_text(json.dumps(manifest), encoding=\\\"utf-8\\\")\\n    return root / \\\"extension.json\\\"\\n\\n\\ndef _write_pyproject_extension(root: Path, manifest: dict[str, object]) -> Path:\\n    \\\"\\\"\\\"Drop a pyproject.toml that declares ``[tool.langflow.extension]``.\\n\\n    Used to confirm the loader accepts both manifest forms; one of the\\n    three \\\"installed\\\" distributions in :func:`fake_installed_distributions`\\n    uses this form so we get coverage automatically.\\n    \\\"\\\"\\\"\\n    import sys\\n\\n    if sys.version_info >= (3, 11):\\n        import tomllib  # type: ignore[import-not-found]\\n    else:\\n        import tomli as tomllib  # type: ignore[import-not-found]  # noqa: F401\\n\\n    root.mkdir(parents=True, exist_ok=True)\\n    bundle_name = manifest[\\\"bundles\\\"][0][\\\"name\\\"]  # type: ignore[index]\\n    (root / bundle_name).mkdir(exist_ok=True)\\n    body = \\\"[tool.langflow.extension]\\\\n\\\"\\n    body += f'id = \\\"{manifest[\\\"id\\\"]}\\\"\\\\n'\\n    body += f'version = \\\"{manifest[\\\"version\\\"]}\\\"\\\\n'\\n    body += f'name = \\\"{manifest[\\\"name\\\"]}\\\"\\\\n'\\n    body += \\\"\\\\n\\\"\\n    body += \\\"[tool.langflow.extension.lfx]\\\\n\\\"\\n    body += 'compat = [\\\"1\\\"]\\\\n'\\n    body += \\\"\\\\n\\\"\\n    body += \\\"[[tool.langflow.extension.bundles]]\\\\n\\\"\\n    body += f'name = \\\"{bundle_name}\\\"\\\\n'\\n    body += f'path = \\\"{bundle_name}\\\"\\\\n'\\n    (root / \\\"pyproject.toml\\\").write_text(body, encoding=\\\"utf-8\\\")\\n    return root / \\\"pyproject.toml\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Fake importlib.metadata.Distribution\\n# ---------------------------------------------------------------------------\\n\\n\\nclass _FakeDistribution(importlib_metadata.Distribution):\\n    \\\"\\\"\\\"In-memory Distribution stub.\\n\\n    ``importlib.metadata.Distribution`` is an ABC; this minimal subclass\\n    satisfies the two abstract members the discovery code uses\\n    (``files`` and ``locate_file``) plus ``metadata`` for the canonical\\n    name lookup.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, *, name: str, root: Path, manifest_relative: str) -> None:\\n        self._name = name\\n        self._root = root\\n        self._manifest_relative = manifest_relative\\n\\n    @property\\n    def files(self) -> list[importlib_metadata.PackagePath]:  # type: ignore[override]\\n        path = importlib_metadata.PackagePath(self._manifest_relative)\\n        return [path]\\n\\n    def locate_file(self, path: object) -> Path:  # type: ignore[override]\\n        return self._root / Path(str(path))\\n\\n    def read_text(self, filename: str) -> str | None:  # type: ignore[override]\\n        if filename in {\\\"METADATA\\\", \\\"PKG-INFO\\\"}:\\n            return f\\\"Metadata-Version: 2.1\\\\nName: {self._name}\\\\nVersion: 1.0.0\\\\n\\\"\\n        return None\\n\\n    @property\\n    def metadata(self) -> object:  # type: ignore[override]\\n        # ``importlib.metadata.Distribution.metadata`` returns an\\n        # ``email.message.Message``; for our purposes a dict-like with\\n        # ``__getitem__`` is sufficient because the discovery code only\\n        # reads ``[\\\"Name\\\"]``.\\n        class _Stub(dict):\\n            pass\\n\\n        return _Stub({\\\"Name\\\": self._name})\\n\\n\\n# ---------------------------------------------------------------------------\\n# Fixtures\\n# ---------------------------------------------------------------------------\\n\\n\\n@pytest.fixture\\ndef fake_installed_distributions(tmp_path: Path) -> list[_FakeDistribution]:\\n    \\\"\\\"\\\"Stand up three in-memory distributions that ship valid manifests.\\n\\n    Two use ``extension.json``; one uses ``pyproject.toml`` so we exercise\\n    both manifest forms in a single integration sweep.\\n    \\\"\\\"\\\"\\n    dists: list[_FakeDistribution] = []\\n    for index, bundle in enumerate(_BUNDLE_NAMES):\\n        ext_root = tmp_path / f\\\"site-packages/lfx_{bundle}\\\"\\n        ext_id = f\\\"lfx-{bundle}\\\"\\n        manifest = _manifest(extension_id=ext_id, bundle_name=bundle, version=f\\\"1.{index}.0\\\")\\n        if index == 1:\\n            manifest_path = _write_pyproject_extension(ext_root, manifest)\\n            relative = \\\"pyproject.toml\\\"\\n        else:\\n            manifest_path = _write_extension_json(ext_root, manifest)\\n            relative = \\\"extension.json\\\"\\n        # sanity: file actually landed where we said it would.\\n        assert manifest_path.exists()\\n        dists.append(_FakeDistribution(name=ext_id, root=ext_root, manifest_relative=relative))\\n    return dists\\n\\n\\n@pytest.fixture\\ndef seed_dir_with_three_bundles(tmp_path: Path) -> Path:\\n    \\\"\\\"\\\"Build a seed directory containing three valid bundle subdirectories.\\\"\\\"\\\"\\n    seed = tmp_path / \\\"seed\\\"\\n    seed.mkdir()\\n    for index, bundle in enumerate(_BUNDLE_NAMES):\\n        sub = seed / f\\\"lfx_{bundle}\\\"\\n        manifest = _manifest(extension_id=f\\\"lfx-{bundle}\\\", bundle_name=bundle, version=f\\\"2.{index}.0\\\")\\n        _write_extension_json(sub, manifest)\\n    return seed\\n\\n\\n# ---------------------------------------------------------------------------\\n# Installed-distribution discovery\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_discover_installed_finds_three_distributions(\\n    fake_installed_distributions: list[_FakeDistribution],\\n) -> None:\\n    extensions, errors = discover_installed_extensions(distributions=fake_installed_distributions)\\n\\n    assert errors == []\\n    assert len(extensions) == 3\\n    ids = sorted(ext.extension_id for ext in extensions)\\n    assert ids == [\\\"lfx-anthropic\\\", \\\"lfx-openai\\\", \\\"lfx-qdrant\\\"]\\n    # Every installed Extension lives at @official by invariant.\\n    for ext in extensions:\\n        assert ext.source_kind == \\\"installed\\\"\\n        assert ext.slot == \\\"official\\\"\\n\\n\\ndef test_discover_installed_records_carry_manifest_source(\\n    fake_installed_distributions: list[_FakeDistribution],\\n) -> None:\\n    extensions, _ = discover_installed_extensions(distributions=fake_installed_distributions)\\n    for ext in extensions:\\n        assert isinstance(ext.manifest, ManifestSource)\\n        assert ext.manifest.path.exists()\\n        assert ext.extension_root == ext.manifest.path.parent\\n\\n\\ndef test_discover_installed_records_every_manifest_bundle(tmp_path: Path) -> None:\\n    root = tmp_path / \\\"site-packages\\\" / \\\"lfx_datastax\\\"\\n    manifest = _manifest(\\\"lfx-datastax\\\", \\\"datastax\\\")\\n    manifest[\\\"bundles\\\"].append({\\\"name\\\": \\\"cassandra\\\", \\\"path\\\": \\\"cassandra\\\"})  # type: ignore[union-attr]\\n    _write_extension_json(root, manifest)\\n    dist = _FakeDistribution(name=\\\"lfx-datastax\\\", root=root, manifest_relative=\\\"extension.json\\\")\\n\\n    extensions, errors = discover_installed_extensions(distributions=[dist])\\n\\n    assert errors == []\\n    assert len(extensions) == 1\\n    assert extensions[0].bundle_name == \\\"datastax\\\"\\n    assert extensions[0].bundle_names == (\\\"datastax\\\", \\\"cassandra\\\")\\n\\n\\ndef test_discover_installed_checks_every_bundle_path(\\n    tmp_path: Path,\\n    monkeypatch: pytest.MonkeyPatch,\\n) -> None:\\n    root = tmp_path / \\\"site-packages\\\" / \\\"lfx_datastax\\\"\\n    manifest = _manifest(\\\"lfx-datastax\\\", \\\"datastax\\\")\\n    manifest[\\\"bundles\\\"].append({\\\"name\\\": \\\"cassandra\\\", \\\"path\\\": \\\"cassandra\\\"})  # type: ignore[union-attr]\\n    _write_extension_json(root, manifest)\\n    dist = _FakeDistribution(name=\\\"lfx-datastax\\\", root=root, manifest_relative=\\\"extension.json\\\")\\n    checked: list[str] = []\\n\\n    def _record_check(_extension_root: Path, bundle: object) -> None:\\n        checked.append(bundle.name)  # type: ignore[attr-defined]\\n\\n    monkeypatch.setattr(\\\"lfx.extension.discovery._verify_bundle_path_safety\\\", _record_check)\\n\\n    extensions, errors = discover_installed_extensions(distributions=[dist])\\n\\n    assert errors == []\\n    assert len(extensions) == 1\\n    assert checked == [\\\"datastax\\\", \\\"cassandra\\\"]\\n\\n\\ndef test_discover_installed_accepts_pyproject_form(\\n    fake_installed_distributions: list[_FakeDistribution],\\n) -> None:\\n    extensions, _ = discover_installed_extensions(distributions=fake_installed_distributions)\\n    by_id = {ext.extension_id: ext for ext in extensions}\\n    # The middle distribution (anthropic) used pyproject.toml.\\n    assert by_id[\\\"lfx-anthropic\\\"].manifest.kind == \\\"pyproject.toml\\\"\\n    assert by_id[\\\"lfx-openai\\\"].manifest.kind == \\\"extension.json\\\"\\n\\n\\ndef test_discover_installed_skips_non_manifest_distributions(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A regular Python package with no manifest should be silently ignored.\\\"\\\"\\\"\\n    plain = tmp_path / \\\"site-packages/regular\\\"\\n    plain.mkdir(parents=True)\\n    (plain / \\\"regular.py\\\").write_text(\\\"# nothing to see here\\\\n\\\", encoding=\\\"utf-8\\\")\\n    dist = _FakeDistribution(name=\\\"regular\\\", root=plain, manifest_relative=\\\"regular.py\\\")\\n\\n    extensions, errors = discover_installed_extensions(distributions=[dist])\\n    assert extensions == []\\n    assert errors == []\\n\\n\\ndef test_discover_installed_emits_typed_error_on_malformed_manifest(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A malformed extension.json surfaces a typed error.\\n\\n    The scan continues and the rest of the dist iterator is unaffected.\\n    \\\"\\\"\\\"\\n    bad_root = tmp_path / \\\"site-packages/lfx_broken\\\"\\n    bad_root.mkdir(parents=True)\\n    (bad_root / \\\"extension.json\\\").write_text(\\\"{ this is not json\\\", encoding=\\\"utf-8\\\")\\n    bad = _FakeDistribution(name=\\\"lfx-broken\\\", root=bad_root, manifest_relative=\\\"extension.json\\\")\\n\\n    good_root = tmp_path / \\\"site-packages/lfx_openai\\\"\\n    _write_extension_json(good_root, _manifest(\\\"lfx-openai\\\", \\\"openai\\\"))\\n    good = _FakeDistribution(name=\\\"lfx-openai\\\", root=good_root, manifest_relative=\\\"extension.json\\\")\\n\\n    extensions, errors = discover_installed_extensions(distributions=[bad, good])\\n\\n    assert len(errors) == 1\\n    assert errors[0].code == \\\"manifest-unreadable\\\"\\n    assert \\\"lfx-broken\\\" in errors[0].content if errors[0].content else True\\n    assert len(extensions) == 1\\n    assert extensions[0].extension_id == \\\"lfx-openai\\\"\\n\\n\\ndef test_discover_installed_emits_typed_error_on_schema_failure(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A parseable but invalid manifest surfaces ``manifest-invalid``.\\\"\\\"\\\"\\n    root = tmp_path / \\\"site-packages/lfx_bad_schema\\\"\\n    root.mkdir(parents=True)\\n    # Missing ``lfx`` field -- pydantic will reject this.\\n    (root / \\\"extension.json\\\").write_text(\\n        json.dumps({\\\"id\\\": \\\"lfx-x\\\", \\\"version\\\": \\\"1.0.0\\\", \\\"name\\\": \\\"X\\\", \\\"bundles\\\": []}),\\n        encoding=\\\"utf-8\\\",\\n    )\\n    dist = _FakeDistribution(name=\\\"lfx-x\\\", root=root, manifest_relative=\\\"extension.json\\\")\\n\\n    extensions, errors = discover_installed_extensions(distributions=[dist])\\n    assert extensions == []\\n    assert len(errors) == 1\\n    assert errors[0].code == \\\"manifest-invalid\\\"\\n\\n\\ndef test_canonicalize_distribution_normalizes_per_pep503() -> None:\\n    assert canonicalize_distribution(\\\"LFX_OpenAI\\\") == \\\"lfx-openai\\\"\\n    assert canonicalize_distribution(\\\"lfx.openai\\\") == \\\"lfx-openai\\\"\\n    assert canonicalize_distribution(\\\"lfx--OpenAI\\\") == \\\"lfx-openai\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Editable install entry-point fallback\\n# ---------------------------------------------------------------------------\\n\\n\\nclass _EditableDistribution(importlib_metadata.Distribution):\\n    \\\"\\\"\\\"In-memory editable Distribution stub.\\n\\n    Mirrors what ``uv pip install -e`` / ``pip install -e`` produce: the\\n    distribution's ``files`` list contains only ``dist-info/`` entries\\n    (the actual source tree is reached via a ``.pth`` file rather than\\n    listed in RECORD), and the ``langflow.extensions`` entry-point is\\n    what the manifest discovery has to lean on.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, *, name: str, module_name: str) -> None:\\n        self._name = name\\n        self._module_name = module_name\\n\\n    @property\\n    def files(self) -> list[importlib_metadata.PackagePath]:  # type: ignore[override]\\n        # Editable installs only surface dist-info entries -- no\\n        # ``extension.json`` and no source ``pyproject.toml``.\\n        slug = self._name.replace(\\\"-\\\", \\\"_\\\")\\n        return [\\n            importlib_metadata.PackagePath(f\\\"{slug}-0.1.0.dist-info/METADATA\\\"),\\n            importlib_metadata.PackagePath(f\\\"{slug}-0.1.0.dist-info/RECORD\\\"),\\n            importlib_metadata.PackagePath(f\\\"_editable_impl_{slug}.pth\\\"),\\n        ]\\n\\n    def locate_file(self, path: object) -> Path:  # type: ignore[override]\\n        return Path(str(path))\\n\\n    def read_text(self, filename: str) -> str | None:  # type: ignore[override]\\n        if filename in {\\\"METADATA\\\", \\\"PKG-INFO\\\"}:\\n            return f\\\"Metadata-Version: 2.1\\\\nName: {self._name}\\\\nVersion: 1.0.0\\\\n\\\"\\n        return None\\n\\n    @property\\n    def metadata(self) -> object:  # type: ignore[override]\\n        class _Stub(dict):\\n            pass\\n\\n        return _Stub({\\\"Name\\\": self._name})\\n\\n    @property\\n    def entry_points(self) -> list[importlib_metadata.EntryPoint]:  # type: ignore[override]\\n        return [\\n            importlib_metadata.EntryPoint(\\n                name=self._name,\\n                value=self._module_name,\\n                group=\\\"langflow.extensions\\\",\\n            )\\n        ]\\n\\n\\ndef _make_editable_package(\\n    site_root: Path,\\n    *,\\n    module_name: str,\\n    manifest: dict[str, object],\\n) -> Path:\\n    \\\"\\\"\\\"Stand up a real importable package on disk with an ``extension.json``.\\\"\\\"\\\"\\n    pkg_dir = site_root / module_name\\n    bundle_name = manifest[\\\"bundles\\\"][0][\\\"name\\\"]  # type: ignore[index]\\n    (pkg_dir / bundle_name).mkdir(parents=True)\\n    (pkg_dir / \\\"__init__.py\\\").write_text(\\\"\\\", encoding=\\\"utf-8\\\")\\n    (pkg_dir / \\\"extension.json\\\").write_text(json.dumps(manifest), encoding=\\\"utf-8\\\")\\n    return pkg_dir\\n\\n\\ndef test_discover_installed_falls_back_to_entry_point_for_editable_install(\\n    tmp_path: Path,\\n    monkeypatch: pytest.MonkeyPatch,\\n) -> None:\\n    \\\"\\\"\\\"Editable installs are discovered via the ``langflow.extensions`` entry-point.\\n\\n    Reproduces the editable-install bug: ``dist.files`` only carries\\n    ``dist-info/`` entries, so the file-walk path finds no manifest.  The\\n    entry-point fallback resolves the package directory via\\n    :func:`importlib.util.find_spec` and locates ``extension.json`` there.\\n    \\\"\\\"\\\"\\n    site = tmp_path / \\\"src\\\"\\n    site.mkdir()\\n    _make_editable_package(\\n        site,\\n        module_name=\\\"lfx_editable_bundle\\\",\\n        manifest=_manifest(\\\"lfx-editable-bundle\\\", \\\"bundle\\\"),\\n    )\\n\\n    monkeypatch.syspath_prepend(str(site))\\n    # Drop any cached spec from a previous test invocation.\\n    import sys\\n\\n    sys.modules.pop(\\\"lfx_editable_bundle\\\", None)\\n\\n    dist = _EditableDistribution(\\n        name=\\\"lfx-editable-bundle\\\",\\n        module_name=\\\"lfx_editable_bundle\\\",\\n    )\\n\\n    extensions, errors = discover_installed_extensions(distributions=[dist])\\n\\n    assert errors == []\\n    assert len(extensions) == 1\\n    ext = extensions[0]\\n    assert ext.extension_id == \\\"lfx-editable-bundle\\\"\\n    assert ext.source_kind == \\\"installed\\\"\\n    assert ext.bundle_name == \\\"bundle\\\"\\n    assert ext.manifest.kind == \\\"extension.json\\\"\\n    assert ext.extension_root == site / \\\"lfx_editable_bundle\\\"\\n\\n\\ndef test_discover_installed_entry_point_fallback_handles_missing_module(\\n    tmp_path: Path,\\n    monkeypatch: pytest.MonkeyPatch,\\n) -> None:\\n    \\\"\\\"\\\"An entry-point pointing at an unimportable module yields no result, no crash.\\\"\\\"\\\"\\n    # No package on sys.path corresponds to ``lfx_nonexistent``.\\n    monkeypatch.syspath_prepend(str(tmp_path))\\n    import sys\\n\\n    sys.modules.pop(\\\"lfx_nonexistent_bundle\\\", None)\\n\\n    dist = _EditableDistribution(\\n        name=\\\"lfx-nonexistent-bundle\\\",\\n        module_name=\\\"lfx_nonexistent_bundle\\\",\\n    )\\n\\n    extensions, errors = discover_installed_extensions(distributions=[dist])\\n\\n    # Unresolvable entry-point is treated as \\\"no manifest here\\\", same as a\\n    # regular non-extension package -- no error, no record.\\n    assert extensions == []\\n    assert errors == []\\n\\n\\ndef test_discover_installed_entry_point_fallback_skipped_when_files_have_manifest(\\n    tmp_path: Path,\\n    monkeypatch: pytest.MonkeyPatch,\\n) -> None:\\n    \\\"\\\"\\\"When ``dist.files`` already exposes the manifest, the entry-point path is unused.\\n\\n    Guards the wheel-install codepath (the common case) from being\\n    accidentally rerouted through ``find_spec`` -- which would otherwise\\n    re-import every bundle package on every startup.\\n    \\\"\\\"\\\"\\n    site = tmp_path / \\\"site-packages/lfx_wheelish\\\"\\n    _write_extension_json(site, _manifest(\\\"lfx-wheelish\\\", \\\"wheelish\\\"))\\n    monkeypatch.syspath_prepend(str(tmp_path / \\\"site-packages\\\"))\\n\\n    # Sentinel: if find_spec is consulted, we'd notice.\\n    import importlib.util as _importlib_util\\n\\n    calls = {\\\"n\\\": 0}\\n    real_find_spec = _importlib_util.find_spec\\n\\n    def _tracking_find_spec(name: str, package: str | None = None) -> object:\\n        calls[\\\"n\\\"] += 1\\n        return real_find_spec(name, package)\\n\\n    monkeypatch.setattr(_importlib_util, \\\"find_spec\\\", _tracking_find_spec)\\n\\n    dist = _FakeDistribution(\\n        name=\\\"lfx-wheelish\\\",\\n        root=site,\\n        manifest_relative=\\\"extension.json\\\",\\n    )\\n    extensions, errors = discover_installed_extensions(distributions=[dist])\\n\\n    assert errors == []\\n    assert len(extensions) == 1\\n    assert calls[\\\"n\\\"] == 0, \\\"Wheel-install path should not consult find_spec\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# Seed-directory discovery\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_discover_seed_finds_three_subdirectories(seed_dir_with_three_bundles: Path) -> None:\\n    extensions, errors = discover_seed_extensions(seed_dir_env=str(seed_dir_with_three_bundles))\\n\\n    assert errors == []\\n    assert len(extensions) == 3\\n    for ext in extensions:\\n        assert ext.source_kind == \\\"seed\\\"\\n        assert ext.slot == \\\"official\\\"\\n        assert Path(ext.source).is_dir()\\n\\n\\ndef test_discover_seed_supports_pathsep_multiple_roots(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"``$LANGFLOW_SEED_DIR`` accepts multiple roots joined by ``os.pathsep``.\\\"\\\"\\\"\\n    root_a = tmp_path / \\\"a\\\"\\n    root_b = tmp_path / \\\"b\\\"\\n    root_a.mkdir()\\n    root_b.mkdir()\\n    _write_extension_json(root_a / \\\"lfx_openai\\\", _manifest(\\\"lfx-openai\\\", \\\"openai\\\"))\\n    _write_extension_json(root_b / \\\"lfx_anthropic\\\", _manifest(\\\"lfx-anthropic\\\", \\\"anthropic\\\"))\\n\\n    composite = f\\\"{root_a}{os.pathsep}{root_b}\\\"\\n    extensions, errors = discover_seed_extensions(seed_dir_env=composite)\\n\\n    assert errors == []\\n    assert {ext.extension_id for ext in extensions} == {\\\"lfx-openai\\\", \\\"lfx-anthropic\\\"}\\n\\n\\ndef test_discover_seed_surfaces_missing_configured_dir(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"An explicitly-configured but missing seed dir emits a typed error.\\\"\\\"\\\"\\n    missing = tmp_path / \\\"does_not_exist\\\"\\n    extensions, errors = discover_seed_extensions(seed_dir_env=str(missing))\\n\\n    assert extensions == []\\n    assert len(errors) == 1\\n    assert errors[0].code == \\\"seed-directory-not-found\\\"\\n\\n\\ndef test_discover_seed_silent_when_default_missing(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A non-existent default seed dir is silently skipped (Mode A laptop).\\\"\\\"\\\"\\n    extensions, errors = discover_seed_extensions(seed_dir_env=\\\"\\\", default=tmp_path / \\\"missing\\\")\\n    assert extensions == []\\n    assert errors == []\\n\\n\\ndef test_discover_seed_skips_directories_without_manifest(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Operators may stage non-extension content alongside bundles.\\\"\\\"\\\"\\n    seed = tmp_path / \\\"seed\\\"\\n    seed.mkdir()\\n    (seed / \\\"garbage\\\").mkdir()\\n    (seed / \\\"garbage\\\" / \\\"README.md\\\").write_text(\\\"just docs\\\\n\\\")\\n    _write_extension_json(seed / \\\"lfx_openai\\\", _manifest(\\\"lfx-openai\\\", \\\"openai\\\"))\\n\\n    extensions, errors = discover_seed_extensions(seed_dir_env=str(seed))\\n\\n    assert errors == []\\n    assert [ext.extension_id for ext in extensions] == [\\\"lfx-openai\\\"]\\n\\n\\ndef test_discover_seed_skips_dot_directories(tmp_path: Path) -> None:\\n    seed = tmp_path / \\\"seed\\\"\\n    seed.mkdir()\\n    hidden = seed / \\\".cache\\\"\\n    hidden.mkdir()\\n    _write_extension_json(hidden, _manifest(\\\"lfx-hidden\\\", \\\"hidden\\\"))\\n    _write_extension_json(seed / \\\"lfx_visible\\\", _manifest(\\\"lfx-visible\\\", \\\"visible\\\"))\\n\\n    extensions, _ = discover_seed_extensions(seed_dir_env=str(seed))\\n    ids = {ext.extension_id for ext in extensions}\\n    assert ids == {\\\"lfx-visible\\\"}\\n\\n\\ndef test_discover_seed_emits_typed_error_on_malformed_manifest(tmp_path: Path) -> None:\\n    seed = tmp_path / \\\"seed\\\"\\n    seed.mkdir()\\n    bad = seed / \\\"lfx_broken\\\"\\n    bad.mkdir()\\n    (bad / \\\"extension.json\\\").write_text(\\\"{ not json\\\", encoding=\\\"utf-8\\\")\\n    # Plus a healthy neighbour to confirm the scan keeps going.\\n    _write_extension_json(seed / \\\"lfx_openai\\\", _manifest(\\\"lfx-openai\\\", \\\"openai\\\"))\\n\\n    extensions, errors = discover_seed_extensions(seed_dir_env=str(seed))\\n\\n    assert {ext.extension_id for ext in extensions} == {\\\"lfx-openai\\\"}\\n    assert len(errors) == 1\\n    assert errors[0].code == \\\"manifest-invalid\\\"\\n\\n\\ndef test_discover_seed_uses_default_when_env_unset(monkeypatch: pytest.MonkeyPatch, tmp_path: Path) -> None:\\n    \\\"\\\"\\\"``seed_dir_env=None`` falls through to the live env-var lookup.\\\"\\\"\\\"\\n    seed = tmp_path / \\\"default_seed\\\"\\n    _write_extension_json(seed / \\\"lfx_openai\\\", _manifest(\\\"lfx-openai\\\", \\\"openai\\\"))\\n    monkeypatch.delenv(SEED_DIR_ENV_VAR, raising=False)\\n\\n    extensions, errors = discover_seed_extensions(default=seed)\\n    assert errors == []\\n    assert {ext.extension_id for ext in extensions} == {\\\"lfx-openai\\\"}\\n\\n\\ndef test_default_seed_dir_constant_is_opt_langflow_bundles() -> None:\\n    \\\"\\\"\\\"Pinning the documented default so docs and code agree.\\\"\\\"\\\"\\n    assert Path(\\\"/opt/langflow/bundles\\\") == DEFAULT_SEED_DIR\\n\\n\\n# ---------------------------------------------------------------------------\\n# Combined entry point\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_discover_all_merges_installed_and_seed(\\n    fake_installed_distributions: list[_FakeDistribution],\\n    tmp_path: Path,\\n) -> None:\\n    \\\"\\\"\\\"``discover_all_extensions`` returns installed first, then seeded.\\\"\\\"\\\"\\n    seed = tmp_path / \\\"seed\\\"\\n    _write_extension_json(seed / \\\"lfx_seed_only\\\", _manifest(\\\"lfx-seed-only\\\", \\\"seed_only\\\"))\\n\\n    extensions, errors = discover_all_extensions(\\n        distributions=fake_installed_distributions,\\n        seed_dir_env=str(seed),\\n        default_seed_dir=None,\\n    )\\n\\n    assert errors == []\\n    # Three installed + one seed.\\n    assert len(extensions) == 4\\n    # Installed precede seeded.\\n    assert [ext.source_kind for ext in extensions] == [\\n        \\\"installed\\\",\\n        \\\"installed\\\",\\n        \\\"installed\\\",\\n        \\\"seed\\\",\\n    ]\\n    assert any(ext.extension_id == \\\"lfx-seed-only\\\" for ext in extensions)\\n\\n\\ndef test_discover_all_emits_seed_bundle_shadowed_when_ids_collide(\\n    fake_installed_distributions: list[_FakeDistribution],\\n    tmp_path: Path,\\n) -> None:\\n    \\\"\\\"\\\"A seed bundle with the same id as an installed one is flagged, not silently dropped.\\n\\n    Installed wins by precedence (documented contract); the operator\\n    still gets a typed ``seed-bundle-shadowed`` error so the shadow is\\n    visible instead of disappearing into discovery debug logs.\\n    \\\"\\\"\\\"\\n    # ``fake_installed_distributions`` ships ``lfx-openai``; the seed dir\\n    # below carries the same id from a different on-disk source.\\n    seed = tmp_path / \\\"seed\\\"\\n    shadow_root = seed / \\\"lfx_openai_shadow\\\"\\n    _write_extension_json(shadow_root, _manifest(\\\"lfx-openai\\\", \\\"openai\\\", version=\\\"9.9.9\\\"))\\n    fresh_root = seed / \\\"lfx_only_seed\\\"\\n    _write_extension_json(fresh_root, _manifest(\\\"lfx-only-seed\\\", \\\"only_seed\\\"))\\n\\n    extensions, errors = discover_all_extensions(\\n        distributions=fake_installed_distributions,\\n        seed_dir_env=str(seed),\\n        default_seed_dir=None,\\n    )\\n\\n    # The non-colliding seed bundle survives; the shadowed one does not.\\n    extension_ids = [ext.extension_id for ext in extensions]\\n    assert extension_ids.count(\\\"lfx-openai\\\") == 1\\n    assert any(ext.extension_id == \\\"lfx-openai\\\" and ext.source_kind == \\\"installed\\\" for ext in extensions)\\n    assert any(ext.extension_id == \\\"lfx-only-seed\\\" for ext in extensions)\\n\\n    shadow_errors = [err for err in errors if err.code == \\\"seed-bundle-shadowed\\\"]\\n    assert len(shadow_errors) == 1\\n    [err] = shadow_errors\\n    assert err.content == \\\"lfx-openai\\\"\\n    assert str(shadow_root.resolve(strict=False)) in err.location or str(shadow_root) in err.location\\n\\n\\ndef test_discover_all_handles_partial_failures(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A broken installed dist plus a missing seed dir both surface errors.\\n\\n    Neither aborts the other source's scan.\\n    \\\"\\\"\\\"\\n    bad_root = tmp_path / \\\"site-packages/lfx_broken\\\"\\n    bad_root.mkdir(parents=True)\\n    (bad_root / \\\"extension.json\\\").write_text(\\\"not json\\\", encoding=\\\"utf-8\\\")\\n    bad = _FakeDistribution(name=\\\"lfx-broken\\\", root=bad_root, manifest_relative=\\\"extension.json\\\")\\n\\n    extensions, errors = discover_all_extensions(\\n        distributions=[bad],\\n        seed_dir_env=str(tmp_path / \\\"seed_missing\\\"),\\n        default_seed_dir=None,\\n    )\\n\\n    assert extensions == []\\n    codes = sorted(err.code for err in errors)\\n    assert \\\"manifest-unreadable\\\" in codes\\n    assert \\\"seed-directory-not-found\\\" in codes\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/lfx/tests/unit/extension/test_errors.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"dcb1104bd25b5c59ee36b4757dc26b7f307fbbddd3087e877c08cbbf79127c5a\",\"content\":\"\\\"\\\"\\\"Snapshot tests for format_extension_error -- one branch per error code.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport pytest\\nfrom lfx.extension.errors import (\\n    DOCS_BASE,\\n    ERROR_CODES,\\n    ExtensionError,\\n    ExtensionErrorCollection,\\n    format_extension_error,\\n)\\n\\n\\ndef test_extension_error_rejects_unknown_code() -> None:\\n    with pytest.raises(ValueError, match=\\\"Unknown extension error code\\\"):\\n        ExtensionError(code=\\\"not-a-real-code\\\", message=\\\"x\\\", hint=\\\"y\\\")\\n\\n\\ndef test_ref_url_default_anchors_to_code() -> None:\\n    err = ExtensionError(code=\\\"manifest-invalid\\\", message=\\\"x\\\", hint=\\\"y\\\")\\n    assert err.ref_url == f\\\"{DOCS_BASE}\\\"\\n\\n\\ndef test_to_dict_contains_all_fields() -> None:\\n    err = ExtensionError(\\n        code=\\\"manifest-invalid\\\",\\n        message=\\\"bad\\\",\\n        hint=\\\"fix it\\\",\\n        location=\\\"/x/y\\\",\\n        content=\\\"oops\\\",\\n    )\\n    payload = err.to_dict()\\n    assert set(payload) == {\\\"code\\\", \\\"message\\\", \\\"location\\\", \\\"content\\\", \\\"hint\\\", \\\"ref_url\\\"}\\n    assert p";
